INSERT INTO public.asvs_categories VALUES
	(1, 'V1', 'Architecture, Design and Threat Modeling', 'Verify the secure software development lifecycle, architecture, and threat modeling.', 1, '2026-02-08 21:52:31.960437', '2026-02-08 22:03:59.512'),
	(2, 'V2', 'Authentication', 'Verify the security of authentication mechanisms.', 2, '2026-02-08 21:52:32.140919', '2026-02-08 22:04:03.473'),
	(3, 'V3', 'Session Management', 'Verify the security of session management.', 3, '2026-02-08 21:52:32.262915', '2026-02-08 22:04:09.317'),
	(4, 'V4', 'Access Control', 'Verify the enforcement of access controls.', 4, '2026-02-08 21:52:32.381547', '2026-02-08 22:04:11.563'),
	(5, 'V5', 'Validation, Sanitization and Encoding', 'Verify input validation and output encoding to prevent injection attacks.', 5, '2026-02-08 21:52:32.497916', '2026-02-08 22:04:12.77'),
	(6, 'V6', 'Stored Cryptography', 'Verify the secure storage of cryptographic keys and data.', 6, '2026-02-08 21:52:32.615277', '2026-02-08 22:04:16.107'),
	(7, 'V7', 'Error Handling and Logging', 'Verify secure error handling and logging practices.', 7, '2026-02-08 21:52:32.733106', '2026-02-08 22:04:17.675'),
	(8, 'V8', 'Data Protection', 'Verify the protection of sensitive data.', 8, '2026-02-08 21:52:32.851005', '2026-02-08 22:04:19.03'),
	(9, 'V9', 'Communication', 'Verify the security of data in transit.', 9, '2026-02-08 21:52:32.967476', '2026-02-08 22:04:20.794'),
	(10, 'V10', 'Malicious Code', 'Verify defenses against malicious code.', 10, '2026-02-08 21:52:33.084921', '2026-02-08 22:04:21.756'),
	(11, 'V11', 'Business Logic', 'Verify the security of business logic.', 11, '2026-02-08 21:52:33.201216', '2026-02-08 22:04:22.52'),
	(12, 'V12', 'Files and Resources', 'Verify the secure handling of files and resources.', 12, '2026-02-08 21:52:33.3191', '2026-02-08 22:04:23.59'),
	(13, 'V13', 'API and Web Service', 'Verify the security of APIs and web services.', 13, '2026-02-08 21:52:33.43802', '2026-02-08 22:04:25.388'),
	(14, 'V14', 'Configuration', 'Verify the secure configuration of the application.', 14, '2026-02-08 21:52:33.554155', '2026-02-08 22:04:26.942');
INSERT INTO public.asvs_requirements VALUES
	(1, 'V1', '1.1', 'Secure Software Development Lifecycle', '1.1.1', 'Verify the use of a secure software development lifecycle that addresses security in all stages of development.', true, true, true, 'CWE-1120', 'NIST-800-63', '4.0.3', '2026-02-08 21:52:33.671973'),
	(3, 'V1', '1.1', 'Secure Software Development Lifecycle', '1.1.3', 'Verify that all user stories and features contain functional security constraints, such as "As a user, I should be able to view and edit my profile. I should not be able to view or edit anyone else''s profile"', true, true, true, '', '', '4.0.3', '2026-02-08 21:52:33.922494'),
	(8, 'V1', '1.1', 'Secure Software Development Lifecycle', '1.1.4', 'Verify documentation and justification of all the application''s trust boundaries, components, and significant data flows.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:44.692441'),
	(5, 'V2', '2.1', 'Password Security', '2.1.2', 'Verify that passwords of at least 64 characters are permitted, and that passwords of more than 128 characters are denied. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '521', '5.1.1.2', '4.0.3', '2026-02-08 21:52:34.157094'),
	(56, 'V2', '2.2', 'General Authenticator Security', '2.2.6', 'Verify replay resistance through the mandated use of One-time Passwords (OTP) devices, cryptographic authenticators, or lookup codes.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:50.780979'),
	(9, 'V1', '1.1', 'Secure Software Development Lifecycle', '1.1.5', 'Verify definition and security analysis of the application''s high-level architecture and all connected remote services. ([C1](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:44.815915'),
	(10, 'V1', '1.1', 'Secure Software Development Lifecycle', '1.1.6', 'Verify implementation of centralized, simple (economy of design), vetted, secure, and reusable security controls to avoid duplicate, missing, ineffective, or insecure controls. ([C10](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:44.932934'),
	(11, 'V1', '1.1', 'Secure Software Development Lifecycle', '1.1.7', 'Verify availability of a secure coding checklist, security requirements, guideline, or policy to all developers and testers.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:45.051459'),
	(12, 'V1', '1.2', 'Authentication Architecture', '1.2.1', 'Verify the use of unique or special low-privilege operating system accounts for all application components, services, and servers. ([C3](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:45.172723'),
	(13, 'V1', '1.2', 'Authentication Architecture', '1.2.2', 'Verify that communications between application components, including APIs, middleware and data layers, are authenticated. Components should have the least necessary privileges needed. ([C3](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:45.293427'),
	(14, 'V1', '1.2', 'Authentication Architecture', '1.2.3', 'Verify that the application uses a single vetted authentication mechanism that is known to be secure, can be extended to include strong authentication, and has sufficient logging and monitoring to detect account abuse or breaches.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:45.41203'),
	(15, 'V1', '1.2', 'Authentication Architecture', '1.2.4', 'Verify that all authentication pathways and identity management APIs implement consistent authentication security control strength, such that there are no weaker alternatives per the risk of the application.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:45.530828'),
	(16, 'V1', '1.4', 'Access Control Architecture', '1.4.1', 'Verify that trusted enforcement points, such as access control gateways, servers, and serverless functions, enforce access controls. Never enforce access controls on the client.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:45.649015'),
	(17, 'V1', '1.4', 'Access Control Architecture', '1.4.4', 'Verify the application uses a single and well-vetted access control mechanism for accessing protected data and resources. All requests must pass through this single mechanism to avoid copy and paste or insecure alternative paths. ([C7](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:45.767534'),
	(18, 'V1', '1.4', 'Access Control Architecture', '1.4.5', 'Verify that attribute or feature-based access control is used whereby the code checks the user''s authorization for a feature/data item rather than just their role. Permissions should still be allocated using roles. ([C7](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:45.886994'),
	(19, 'V1', '1.5', 'Input and Output Architecture', '1.5.1', 'Verify that input and output requirements clearly define how to handle and process data based on type, content, and applicable laws, regulations, and other policy compliance.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:46.004761'),
	(20, 'V1', '1.5', 'Input and Output Architecture', '1.5.2', 'Verify that serialization is not used when communicating with untrusted clients. If this is not possible, ensure that adequate integrity controls (and possibly encryption if sensitive data is sent) are enforced to prevent deserialization attacks including object injection.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:46.122955'),
	(21, 'V1', '1.5', 'Input and Output Architecture', '1.5.3', 'Verify that input validation is enforced on a trusted service layer. ([C5](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:46.24107'),
	(22, 'V1', '1.5', 'Input and Output Architecture', '1.5.4', 'Verify that output encoding occurs close to or by the interpreter for which it is intended. ([C4](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:46.358521'),
	(23, 'V1', '1.6', 'Cryptographic Architecture', '1.6.1', 'Verify that there is an explicit policy for management of cryptographic keys and that a cryptographic key lifecycle follows a key management standard such as NIST SP 800-57.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:46.479602'),
	(24, 'V1', '1.6', 'Cryptographic Architecture', '1.6.2', 'Verify that consumers of cryptographic services protect key material and other secrets by using key vaults or API based alternatives.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:46.597493'),
	(25, 'V1', '1.6', 'Cryptographic Architecture', '1.6.3', 'Verify that all keys and passwords are replaceable and are part of a well-defined process to re-encrypt sensitive data.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:46.718493'),
	(26, 'V1', '1.6', 'Cryptographic Architecture', '1.6.4', 'Verify that the architecture treats client-side secrets--such as symmetric keys, passwords, or API tokens--as insecure and never uses them to protect or access sensitive data.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:46.836963'),
	(27, 'V1', '1.7', 'Errors, Logging and Auditing Architecture', '1.7.1', 'Verify that a common logging format and approach is used across the system. ([C9](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:46.955437'),
	(28, 'V1', '1.9', 'Communications Architecture', '1.9.1', 'Verify the application encrypts communications between components, particularly when these components are in different containers, systems, sites, or cloud providers. ([C3](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:47.073745'),
	(4, 'V2', '2.1', 'Password Security', '2.1.1', 'Verify that user set passwords are at least 12 characters in length (after multiple spaces are combined). ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '521', '5.1.1.2', '4.0.3', '2026-02-08 21:52:34.041506'),
	(31, 'V1', '1.11', 'Business Logic Architecture', '1.11.1', 'Verify the definition and documentation of all application components in terms of the business or security functions they provide.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:47.427006'),
	(32, 'V1', '1.11', 'Business Logic Architecture', '1.11.2', 'Verify that all high-value business logic flows, including authentication, session management and access control, do not share unsynchronized state.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:47.548949'),
	(33, 'V1', '1.12', 'Secure File Upload Architecture', '1.12.2', 'Verify that user-uploaded files - if required to be displayed or downloaded from the application - are served by either octet stream downloads, or from an unrelated domain, such as a cloud file storage bucket. Implement a suitable Content Security Policy (CSP) to reduce the risk from XSS vectors or other attacks from the uploaded file.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:47.668551'),
	(34, 'V1', '1.14', 'Configuration Architecture', '1.14.1', 'Verify the segregation of components of differing trust levels through well-defined security controls, firewall rules, API gateways, reverse proxies, cloud-based security groups, or similar mechanisms.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:47.786488'),
	(35, 'V1', '1.14', 'Configuration Architecture', '1.14.2', 'Verify that binary signatures, trusted connections, and verified endpoints are used to deploy binaries to remote devices.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:47.903961'),
	(36, 'V1', '1.14', 'Configuration Architecture', '1.14.3', 'Verify that the build pipeline warns of out-of-date or insecure components and takes appropriate actions.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:48.0638'),
	(37, 'V1', '1.14', 'Configuration Architecture', '1.14.5', 'Verify that application deployments adequately sandbox, containerize and/or isolate at the network level to delay and deter attackers from attacking other applications, especially when they are performing sensitive or dangerous actions such as deserialization. ([C5](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:48.186628'),
	(38, 'V1', '1.14', 'Configuration Architecture', '1.14.6', 'Verify the application does not use unsupported, insecure, or deprecated client-side technologies such as NSAPI plugins, Flash, Shockwave, ActiveX, Silverlight, NACL, or client-side Java applets.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:48.318469'),
	(41, 'V2', '2.1', 'Password Security', '2.1.3', 'Verify that password truncation is not performed. However, consecutive multiple spaces may be replaced by a single space. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '521', '5.1.1.2', '4.0.3', '2026-02-08 21:59:49.004874'),
	(42, 'V2', '2.1', 'Password Security', '2.1.4', 'Verify that any printable Unicode character, including language neutral characters such as spaces and Emojis are permitted in passwords.', true, true, true, '521', '5.1.1.2', '4.0.3', '2026-02-08 21:59:49.125076'),
	(43, 'V2', '2.1', 'Password Security', '2.1.5', 'Verify users can change their password.', true, true, true, '620', '5.1.1.2', '4.0.3', '2026-02-08 21:59:49.244054'),
	(44, 'V2', '2.1', 'Password Security', '2.1.6', 'Verify that password change functionality requires the user''s current and new password.', true, true, true, '620', '5.1.1.2', '4.0.3', '2026-02-08 21:59:49.361891'),
	(46, 'V2', '2.1', 'Password Security', '2.1.8', 'Verify that a password strength meter is provided to help users set a stronger password.', true, true, true, '521', '5.1.1.2', '4.0.3', '2026-02-08 21:59:49.597965'),
	(47, 'V2', '2.1', 'Password Security', '2.1.9', 'Verify that there are no password composition rules limiting the type of characters permitted. There should be no requirement for upper or lower case or numbers or special characters. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '521', '5.1.1.2', '4.0.3', '2026-02-08 21:59:49.715953'),
	(48, 'V2', '2.1', 'Password Security', '2.1.10', 'Verify that there are no periodic credential rotation or password history requirements.', true, true, true, '263', '5.1.1.2', '4.0.3', '2026-02-08 21:59:49.834024'),
	(49, 'V2', '2.1', 'Password Security', '2.1.11', 'Verify that "paste" functionality, browser password helpers, and external password managers are permitted.', true, true, true, '521', '5.1.1.2', '4.0.3', '2026-02-08 21:59:49.95034'),
	(50, 'V2', '2.1', 'Password Security', '2.1.12', 'Verify that the user can choose to either temporarily view the entire masked password, or temporarily view the last typed character of the password on platforms that do not have this as built-in functionality.', true, true, true, '521', '5.1.1.2', '4.0.3', '2026-02-08 21:59:50.068832'),
	(51, 'V2', '2.2', 'General Authenticator Security', '2.2.1', 'Verify that anti-automation controls are effective at mitigating breached credential testing, brute force, and account lockout attacks. Such controls include blocking the most common breached passwords, soft lockouts, rate limiting, CAPTCHA, ever increasing delays between attempts, IP address restrictions, or risk-based restrictions such as location, first login on a device, recent attempts to unlock the account, or similar. Verify that no more than 100 failed attempts per hour is possible on a single account.', true, true, true, '307', '5.2.2 / 5.1.1.2 / 5.1.4.2 / 5.1.5.2', '4.0.3', '2026-02-08 21:59:50.18699'),
	(52, 'V2', '2.2', 'General Authenticator Security', '2.2.2', 'Verify that the use of weak authenticators (such as SMS and email) is limited to secondary verification and transaction approval and not as a replacement for more secure authentication methods. Verify that stronger methods are offered before weak methods, users are aware of the risks, or that proper measures are in place to limit the risks of account compromise.', true, true, true, '304', '5.2.10', '4.0.3', '2026-02-08 21:59:50.304071'),
	(53, 'V2', '2.2', 'General Authenticator Security', '2.2.3', 'Verify that secure notifications are sent to users after updates to authentication details, such as credential resets, email or address changes, logging in from unknown or risky locations. The use of push notifications - rather than SMS or email - is preferred, but in the absence of push notifications, SMS or email is acceptable as long as no sensitive information is disclosed in the notification.', true, true, true, '620', '', '4.0.3', '2026-02-08 21:59:50.421032'),
	(54, 'V2', '2.2', 'General Authenticator Security', '2.2.4', 'Verify impersonation resistance against phishing, such as the use of multi-factor authentication, cryptographic devices with intent (such as connected keys with a push to authenticate), or at higher AAL levels, client-side certificates.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:50.540504'),
	(55, 'V2', '2.2', 'General Authenticator Security', '2.2.5', 'Verify that where a Credential Service Provider (CSP) and the application verifying authentication are separated, mutually authenticated TLS is in place between the two endpoints.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:50.662985'),
	(59, 'V2', '2.3', 'Authenticator Lifecycle', '2.3.2', 'Verify that enrollment and use of user-provided authentication devices are supported, such as a U2F or FIDO tokens.', true, true, true, '6.1.3', '', '4.0.3', '2026-02-08 21:59:51.142067'),
	(60, 'V2', '2.3', 'Authenticator Lifecycle', '2.3.3', 'Verify that renewal instructions are sent with sufficient time to renew time bound authenticators.', true, true, true, '6.1.4', '', '4.0.3', '2026-02-08 21:59:51.261037'),
	(61, 'V2', '2.4', 'Credential Storage', '2.4.1', 'Verify that passwords are stored in a form that is resistant to offline attacks. Passwords SHALL be salted and hashed using an approved one-way key derivation or password hashing function. Key derivation and password hashing functions take a password, a salt, and a cost factor as inputs when generating a password hash. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '5.1.1.2', '', '4.0.3', '2026-02-08 21:59:51.37858'),
	(62, 'V2', '2.4', 'Credential Storage', '2.4.2', 'Verify that the salt is at least 32 bits in length and be chosen arbitrarily to minimize salt value collisions among stored hashes. For each credential, a unique salt value and the resulting hash SHALL be stored. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '5.1.1.2', '', '4.0.3', '2026-02-08 21:59:51.495555'),
	(63, 'V2', '2.4', 'Credential Storage', '2.4.3', 'Verify that if PBKDF2 is used, the iteration count SHOULD be as large as verification server performance will allow, typically at least 100,000 iterations. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '5.1.1.2', '', '4.0.3', '2026-02-08 21:59:51.61201'),
	(64, 'V2', '2.4', 'Credential Storage', '2.4.4', 'Verify that if bcrypt is used, the work factor SHOULD be as large as verification server performance will allow, with a minimum of 10. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '5.1.1.2', '', '4.0.3', '2026-02-08 21:59:51.729607'),
	(65, 'V2', '2.4', 'Credential Storage', '2.4.5', 'Verify that an additional iteration of a key derivation function is performed, using a salt value that is secret and known only to the verifier. Generate the salt value using an approved random bit generator [SP 800-90Ar1] and provide at least the minimum security strength specified in the latest revision of SP 800-131A. The secret salt value SHALL be stored separately from the hashed passwords (e.g., in a specialized device like a hardware security module).', true, true, true, '5.1.1.2', '', '4.0.3', '2026-02-08 21:59:51.846071'),
	(66, 'V2', '2.5', 'Credential Recovery', '2.5.1', 'Verify that a system generated initial activation or recovery secret is not sent in clear text to the user. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '640', '5.1.1.2', '4.0.3', '2026-02-08 21:59:51.965532'),
	(67, 'V2', '2.5', 'Credential Recovery', '2.5.2', 'Verify password hints or knowledge-based authentication (so-called "secret questions") are not present.', true, true, true, '640', '5.1.1.2', '4.0.3', '2026-02-08 21:59:52.083725'),
	(68, 'V2', '2.5', 'Credential Recovery', '2.5.3', 'Verify password credential recovery does not reveal the current password in any way. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '640', '5.1.1.2', '4.0.3', '2026-02-08 21:59:52.204649'),
	(69, 'V2', '2.5', 'Credential Recovery', '2.5.4', 'Verify shared or default accounts are not present (e.g. "root", "admin", or "sa").', true, true, true, '16', '5.1.1.2 / A.3', '4.0.3', '2026-02-08 21:59:52.323531'),
	(70, 'V2', '2.5', 'Credential Recovery', '2.5.5', 'Verify that if an authentication factor is changed or replaced, that the user is notified of this event.', true, true, true, '304', '6.1.2.3', '4.0.3', '2026-02-08 21:59:52.449679'),
	(71, 'V2', '2.5', 'Credential Recovery', '2.5.6', 'Verify forgotten password, and other recovery paths use a secure recovery mechanism, such as time-based OTP (TOTP) or other soft token, mobile push, or another offline recovery mechanism. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '640', '5.1.1.2', '4.0.3', '2026-02-08 21:59:52.566603'),
	(72, 'V2', '2.5', 'Credential Recovery', '2.5.7', 'Verify that if OTP or multi-factor authentication factors are lost, that evidence of identity proofing is performed at the same level as during enrollment.', true, true, true, '6.1.2.3', '', '4.0.3', '2026-02-08 21:59:52.687201'),
	(73, 'V2', '2.6', 'Look-up Secret Verifier', '2.6.1', 'Verify that lookup secrets can be used only once.', true, true, true, '5.1.2.2', '', '4.0.3', '2026-02-08 21:59:52.808367'),
	(74, 'V2', '2.6', 'Look-up Secret Verifier', '2.6.2', 'Verify that lookup secrets have sufficient randomness (112 bits of entropy), or if less than 112 bits of entropy, salted with a unique and random 32-bit salt and hashed with an approved one-way hash.', true, true, true, '5.1.2.2', '', '4.0.3', '2026-02-08 21:59:52.925647'),
	(75, 'V2', '2.6', 'Look-up Secret Verifier', '2.6.3', 'Verify that lookup secrets are resistant to offline attacks, such as predictable values.', true, true, true, '5.1.2.2', '', '4.0.3', '2026-02-08 21:59:53.044087'),
	(76, 'V2', '2.7', 'Out of Band Verifier', '2.7.1', 'Verify that clear text out of band (NIST "restricted") authenticators, such as SMS or PSTN, are not offered by default, and stronger alternatives such as push notifications are offered first.', true, true, true, '287', '5.1.3.2', '4.0.3', '2026-02-08 21:59:53.162444'),
	(77, 'V2', '2.7', 'Out of Band Verifier', '2.7.2', 'Verify that the out of band verifier expires out of band authentication requests, codes, or tokens after 10 minutes.', true, true, true, '287', '5.1.3.2', '4.0.3', '2026-02-08 21:59:53.280069'),
	(78, 'V2', '2.7', 'Out of Band Verifier', '2.7.3', 'Verify that the out of band verifier authentication requests, codes, or tokens are only usable once, and only for the original authentication request.', true, true, true, '287', '5.1.3.2', '4.0.3', '2026-02-08 21:59:53.399227'),
	(79, 'V2', '2.7', 'Out of Band Verifier', '2.7.4', 'Verify that the out of band authenticator and verifier communicates over a secure independent channel.', true, true, true, '523', '5.1.3.2', '4.0.3', '2026-02-08 21:59:53.517559'),
	(80, 'V2', '2.7', 'Out of Band Verifier', '2.7.5', 'Verify that the out of band verifier retains only a hashed version of the authentication code.', true, true, true, '5.1.3.2', '', '4.0.3', '2026-02-08 21:59:53.634621'),
	(81, 'V2', '2.7', 'Out of Band Verifier', '2.7.6', 'Verify that the initial authentication code is generated by a secure random number generator, containing at least 20 bits of entropy (typically a six digital random number is sufficient).', true, true, true, '5.1.3.2', '', '4.0.3', '2026-02-08 21:59:53.754342'),
	(82, 'V2', '2.8', 'One Time Verifier', '2.8.1', 'Verify that time-based OTPs have a defined lifetime before expiring.', true, true, true, '613', '5.1.4.2 / 5.1.5.2', '4.0.3', '2026-02-08 21:59:53.874111'),
	(83, 'V2', '2.8', 'One Time Verifier', '2.8.2', 'Verify that symmetric keys used to verify submitted OTPs are highly protected, such as by using a hardware security module or secure operating system based key storage.', true, true, true, '5.1.4.2 / 5.1.5.2', '', '4.0.3', '2026-02-08 21:59:53.997587'),
	(84, 'V2', '2.8', 'One Time Verifier', '2.8.3', 'Verify that approved cryptographic algorithms are used in the generation, seeding, and verification of OTPs.', true, true, true, '5.1.4.2 / 5.1.5.2', '', '4.0.3', '2026-02-08 21:59:54.115593'),
	(85, 'V2', '2.8', 'One Time Verifier', '2.8.4', 'Verify that time-based OTP can be used only once within the validity period.', true, true, true, '5.1.4.2 / 5.1.5.2', '', '4.0.3', '2026-02-08 21:59:54.233046'),
	(86, 'V2', '2.8', 'One Time Verifier', '2.8.5', 'Verify that if a time-based multi-factor OTP token is re-used during the validity period, it is logged and rejected with secure notifications being sent to the holder of the device.', true, true, true, '5.1.5.2', '', '4.0.3', '2026-02-08 21:59:54.353613'),
	(88, 'V2', '2.8', 'One Time Verifier', '2.8.7', 'Verify that biometric authenticators are limited to use only as secondary factors in conjunction with either something you have and something you know.', true, true, true, '5.2.3', '', '4.0.3', '2026-02-08 21:59:54.59485'),
	(90, 'V2', '2.9', 'Cryptographic Verifier', '2.9.2', 'Verify that the challenge nonce is at least 64 bits in length, and statistically unique or unique over the lifetime of the cryptographic device.', true, true, true, '5.1.7.2', '', '4.0.3', '2026-02-08 21:59:54.83407'),
	(91, 'V2', '2.9', 'Cryptographic Verifier', '2.9.3', 'Verify that approved cryptographic algorithms are used in the generation, seeding, and verification.', true, true, true, '5.1.7.2', '', '4.0.3', '2026-02-08 21:59:54.956757'),
	(92, 'V2', '2.10', 'Service Authentication', '2.10.1', 'Verify that intra-service secrets do not rely on unchanging credentials such as passwords, API keys or shared accounts with privileged access.', true, true, true, '5.1.1.1', '', '4.0.3', '2026-02-08 21:59:55.080606'),
	(93, 'V2', '2.10', 'Service Authentication', '2.10.2', 'Verify that if passwords are required for service authentication, the service account used is not a default credential. (e.g. root/root or admin/admin are default in some services during installation).', true, true, true, '5.1.1.1', '', '4.0.3', '2026-02-08 21:59:55.203075'),
	(94, 'V2', '2.10', 'Service Authentication', '2.10.3', 'Verify that passwords are stored with sufficient protection to prevent offline recovery attacks, including local system access.', true, true, true, '5.1.1.1', '', '4.0.3', '2026-02-08 21:59:55.326655'),
	(95, 'V2', '2.10', 'Service Authentication', '2.10.4', 'Verify passwords, integrations with databases and third-party systems, seeds and internal secrets, and API keys are managed securely and not included in the source code or stored within source code repositories. Such storage SHOULD resist offline attacks. The use of a secure software key store (L1), hardware TPM, or an HSM (L3) is recommended for password storage.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:55.444589'),
	(96, 'V3', '3.1', 'Fundamental Session Management Security', '3.1.1', 'Verify the application never reveals session tokens in URL parameters.', true, true, true, '598', '', '4.0.3', '2026-02-08 21:59:55.900682'),
	(97, 'V3', '3.2', 'Session Binding', '3.2.1', 'Verify the application generates a new session token on user authentication. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '384', '7.1', '4.0.3', '2026-02-08 21:59:56.019863'),
	(98, 'V3', '3.2', 'Session Binding', '3.2.2', 'Verify that session tokens possess at least 64 bits of entropy. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '331', '7.1', '4.0.3', '2026-02-08 21:59:56.137278'),
	(99, 'V3', '3.2', 'Session Binding', '3.2.3', 'Verify the application only stores session tokens in the browser using secure methods such as appropriately secured cookies (see section 3.4) or HTML 5 session storage.', true, true, true, '539', '7.1', '4.0.3', '2026-02-08 21:59:56.259167'),
	(100, 'V3', '3.2', 'Session Binding', '3.2.4', 'Verify that session tokens are generated using approved cryptographic algorithms. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '7.1', '', '4.0.3', '2026-02-08 21:59:56.37958'),
	(101, 'V3', '3.3', 'Session Termination', '3.3.1', 'Verify that logout and expiration invalidate the session token, such that the back button or a downstream relying party does not resume an authenticated session, including across relying parties. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '613', '7.1', '4.0.3', '2026-02-08 21:59:56.497171'),
	(102, 'V3', '3.3', 'Session Termination', '3.3.2', 'If authenticators permit users to remain logged in, verify that re-authentication occurs periodically both when actively used or after an idle period. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '613', '7.2', '4.0.3', '2026-02-08 21:59:56.617159'),
	(103, 'V3', '3.3', 'Session Termination', '3.3.3', 'Verify that the application gives the option to terminate all other active sessions after a successful password change (including change via password reset/recovery), and that this is effective across the application, federated login (if present), and any relying parties.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:56.739091'),
	(104, 'V3', '3.3', 'Session Termination', '3.3.4', 'Verify that users are able to view and (having re-entered login credentials) log out of any or all currently active sessions and devices.', true, true, true, '7.1', '', '4.0.3', '2026-02-08 21:59:56.857089'),
	(105, 'V3', '3.4', 'Cookie-based Session Management', '3.4.1', 'Verify that cookie-based session tokens have the ''Secure'' attribute set. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '614', '7.1.1', '4.0.3', '2026-02-08 21:59:56.975598'),
	(106, 'V3', '3.4', 'Cookie-based Session Management', '3.4.2', 'Verify that cookie-based session tokens have the ''HttpOnly'' attribute set. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '1004', '7.1.1', '4.0.3', '2026-02-08 21:59:57.101068'),
	(107, 'V3', '3.4', 'Cookie-based Session Management', '3.4.3', 'Verify that cookie-based session tokens utilize the ''SameSite'' attribute to limit exposure to cross-site request forgery attacks. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '16', '7.1.1', '4.0.3', '2026-02-08 21:59:57.219663'),
	(108, 'V3', '3.4', 'Cookie-based Session Management', '3.4.4', 'Verify that cookie-based session tokens use the "__Host-" prefix so cookies are only sent to the host that initially set the cookie.', true, true, true, '16', '7.1.1', '4.0.3', '2026-02-08 21:59:57.33807'),
	(109, 'V3', '3.4', 'Cookie-based Session Management', '3.4.5', 'Verify that if the application is published under a domain name with other applications that set or use session cookies that might disclose the session cookies, set the path attribute in cookie-based session tokens using the most precise path possible. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '16', '7.1.1', '4.0.3', '2026-02-08 21:59:57.458055'),
	(110, 'V3', '3.5', 'Token-based Session Management', '3.5.1', 'Verify the application allows users to revoke OAuth tokens that form trust relationships with linked applications.', true, true, true, '7.1.2', '', '4.0.3', '2026-02-08 21:59:57.577254'),
	(111, 'V3', '3.5', 'Token-based Session Management', '3.5.2', 'Verify the application uses session tokens rather than static API secrets and keys, except with legacy implementations.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:57.694164'),
	(112, 'V3', '3.5', 'Token-based Session Management', '3.5.3', 'Verify that stateless session tokens use digital signatures, encryption, and other countermeasures to protect against tampering, enveloping, replay, null cipher, and key substitution attacks.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:57.815725');
INSERT INTO public.asvs_requirements VALUES
	(113, 'V3', '3.6', 'Federated Re-authentication', '3.6.1', 'Verify that Relying Parties (RPs) specify the maximum authentication time to Credential Service Providers (CSPs) and that CSPs re-authenticate the user if they haven''t used a session within that period.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:57.93311'),
	(114, 'V3', '3.6', 'Federated Re-authentication', '3.6.2', 'Verify that Credential Service Providers (CSPs) inform Relying Parties (RPs) of the last authentication event, to allow RPs to determine if they need to re-authenticate the user.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:58.054807'),
	(115, 'V3', '3.7', 'Defenses Against Session Management Exploits', '3.7.1', 'Verify the application ensures a full, valid login session or requires re-authentication or secondary verification before allowing any sensitive transactions or account modifications.', true, true, true, '306', '', '4.0.3', '2026-02-08 21:59:58.170834'),
	(2, 'V1', '1.1', 'Secure Software Development Lifecycle', '1.1.2', 'Verify the use of threat modeling for every design change or sprint planning to identify threats, plan for countermeasures, facilitate appropriate risk responses, and guide security testing.', true, true, true, '', '', '4.0.3', '2026-02-08 21:52:33.80352'),
	(29, 'V1', '1.9', 'Communications Architecture', '1.9.2', 'Verify that application components verify the authenticity of each side in a communication link to prevent person-in-the-middle attacks. For example, application components should validate TLS certificates and chains.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:47.1905'),
	(30, 'V1', '1.10', 'Malicious Software Architecture', '1.10.1', 'Verify that a source code control system is in use, with procedures to ensure that check-ins are accompanied by issues or change tickets. The source code control system should have access control and identifiable users to allow traceability of any changes.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:47.309476'),
	(45, 'V2', '2.1', 'Password Security', '2.1.7', 'Verify that passwords submitted during account registration, login, and password change are checked against a set of breached passwords either locally (such as the top 1,000 or 10,000 most common passwords which match the system''s password policy) or using an external API. If using an API a zero knowledge proof or other mechanism should be used to ensure that the plain text password is not sent or used in verifying the breach status of the password. If the password is breached, the application must require the user to set a new non-breached password. ([C6](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '521', '5.1.1.2', '4.0.3', '2026-02-08 21:59:49.479589'),
	(57, 'V2', '2.2', 'General Authenticator Security', '2.2.7', 'Verify intent to authenticate by requiring the entry of an OTP token or user-initiated action such as a button press on a FIDO hardware key.', true, true, true, '', '', '4.0.3', '2026-02-08 21:59:50.900496'),
	(58, 'V2', '2.3', 'Authenticator Lifecycle', '2.3.1', 'Verify system generated initial passwords or activation codes SHOULD be securely randomly generated, SHOULD be at least 6 characters long, and MAY contain letters and numbers, and expire after a short period of time. These initial secrets must not be permitted to become the long term password.', true, true, true, '330', '5.1.1.2 / A.3', '4.0.3', '2026-02-08 21:59:51.021492'),
	(87, 'V2', '2.8', 'One Time Verifier', '2.8.6', 'Verify physical single-factor OTP generator can be revoked in case of theft or other loss. Ensure that revocation is immediately effective across logged in sessions, regardless of location.', true, true, true, '5.2.1', '', '4.0.3', '2026-02-08 21:59:54.472596'),
	(89, 'V2', '2.9', 'Cryptographic Verifier', '2.9.1', 'Verify that cryptographic keys used in verification are stored securely and protected against disclosure, such as using a Trusted Platform Module (TPM) or Hardware Security Module (HSM), or an OS service that can use this secure storage.', true, true, true, '5.1.7.2', '', '4.0.3', '2026-02-08 21:59:54.714087'),
	(226, 'V4', '4.1', 'General Access Control Design', '4.1.1', 'Verify that the application enforces access control rules on a trusted service layer, especially if client-side access control is present and could be bypassed.', true, true, true, '602', '', '4.0.3', '2026-02-08 22:04:17.363655'),
	(227, 'V4', '4.1', 'General Access Control Design', '4.1.2', 'Verify that all user and data attributes and policy information used by access controls cannot be manipulated by end users unless specifically authorized.', true, true, true, '639', '', '4.0.3', '2026-02-08 22:04:17.461493'),
	(228, 'V4', '4.1', 'General Access Control Design', '4.1.3', 'Verify that the principle of least privilege exists - users should only be able to access functions, data files, URLs, controllers, services, and other resources, for which they possess specific authorization. This implies protection against spoofing and elevation of privilege. ([C7](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '285', '', '4.0.3', '2026-02-08 22:04:17.559791'),
	(229, 'V4', '4.1', 'General Access Control Design', '4.1.5', 'Verify that access controls fail securely including when an exception occurs. ([C10](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '285', '', '4.0.3', '2026-02-08 22:04:17.659158'),
	(230, 'V4', '4.2', 'Operation Level Access Control', '4.2.1', 'Verify that sensitive data and APIs are protected against Insecure Direct Object Reference (IDOR) attacks targeting creation, reading, updating and deletion of records, such as creating or updating someone else''s record, viewing everyone''s records, or deleting all records.', true, true, true, '639', '', '4.0.3', '2026-02-08 22:04:17.75703'),
	(231, 'V4', '4.2', 'Operation Level Access Control', '4.2.2', 'Verify that the application or framework enforces a strong anti-CSRF mechanism to protect authenticated functionality, and effective anti-automation or anti-CSRF protects unauthenticated functionality.', true, true, true, '352', '', '4.0.3', '2026-02-08 22:04:17.85449'),
	(232, 'V4', '4.3', 'Other Access Control Considerations', '4.3.1', 'Verify administrative interfaces use appropriate multi-factor authentication to prevent unauthorized use.', true, true, true, '419', '', '4.0.3', '2026-02-08 22:04:17.954069'),
	(233, 'V4', '4.3', 'Other Access Control Considerations', '4.3.2', 'Verify that directory browsing is disabled unless deliberately desired. Additionally, applications should not allow discovery or disclosure of file or directory metadata, such as Thumbs.db, .DS_Store, .git or .svn folders.', true, true, true, '548', '', '4.0.3', '2026-02-08 22:04:18.054783'),
	(234, 'V4', '4.3', 'Other Access Control Considerations', '4.3.3', 'Verify the application has additional authorization (such as step up or adaptive authentication) for lower value systems, and / or segregation of duties for high value applications to enforce anti-fraud controls as per the risk of application and past fraud.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:18.156281'),
	(235, 'V5', '5.1', 'Input Validation', '5.1.1', 'Verify that the application has defenses against HTTP parameter pollution attacks, particularly if the application framework makes no distinction about the source of request parameters (GET, POST, cookies, headers, or environment variables).', true, true, true, '235', '', '4.0.3', '2026-02-08 22:04:18.558509'),
	(236, 'V5', '5.1', 'Input Validation', '5.1.2', 'Verify that frameworks protect against mass parameter assignment attacks, or that the application has countermeasures to protect against unsafe parameter assignment, such as marking fields private or similar. ([C5](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '915', '', '4.0.3', '2026-02-08 22:04:18.655259'),
	(237, 'V5', '5.1', 'Input Validation', '5.1.3', 'Verify that all input (HTML form fields, REST requests, URL parameters, HTTP headers, cookies, batch files, RSS feeds, etc) is validated using positive validation (allow lists). ([C5](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '20', '', '4.0.3', '2026-02-08 22:04:18.754089'),
	(238, 'V5', '5.1', 'Input Validation', '5.1.4', 'Verify that structured data is strongly typed and validated against a defined schema including allowed characters, length and pattern (e.g. credit card numbers, e-mail addresses, telephone numbers, or validating that two related fields are reasonable, such as checking that suburb and zip/postcode match). ([C5](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '20', '', '4.0.3', '2026-02-08 22:04:18.851084'),
	(239, 'V5', '5.1', 'Input Validation', '5.1.5', 'Verify that URL redirects and forwards only allow destinations which appear on an allow list, or show a warning when redirecting to potentially untrusted content.', true, true, true, '601', '', '4.0.3', '2026-02-08 22:04:18.952073'),
	(240, 'V5', '5.2', 'Sanitization and Sandboxing', '5.2.1', 'Verify that all untrusted HTML input from WYSIWYG editors or similar is properly sanitized with an HTML sanitizer library or framework feature. ([C5](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '116', '', '4.0.3', '2026-02-08 22:04:19.050481'),
	(241, 'V5', '5.2', 'Sanitization and Sandboxing', '5.2.2', 'Verify that unstructured data is sanitized to enforce safety measures such as allowed characters and length.', true, true, true, '138', '', '4.0.3', '2026-02-08 22:04:19.151487'),
	(242, 'V5', '5.2', 'Sanitization and Sandboxing', '5.2.3', 'Verify that the application sanitizes user input before passing to mail systems to protect against SMTP or IMAP injection.', true, true, true, '147', '', '4.0.3', '2026-02-08 22:04:19.251632'),
	(243, 'V5', '5.2', 'Sanitization and Sandboxing', '5.2.4', 'Verify that the application avoids the use of eval() or other dynamic code execution features. Where there is no alternative, any user input being included must be sanitized or sandboxed before being executed.', true, true, true, '95', '', '4.0.3', '2026-02-08 22:04:19.35052'),
	(244, 'V5', '5.2', 'Sanitization and Sandboxing', '5.2.5', 'Verify that the application protects against template injection attacks by ensuring that any user input being included is sanitized or sandboxed.', true, true, true, '94', '', '4.0.3', '2026-02-08 22:04:19.449487'),
	(245, 'V5', '5.2', 'Sanitization and Sandboxing', '5.2.6', 'Verify that the application protects against SSRF attacks, by validating or sanitizing untrusted data or HTTP file metadata, such as filenames and URL input fields, and uses allow lists of protocols, domains, paths and ports.', true, true, true, '918', '', '4.0.3', '2026-02-08 22:04:19.552001'),
	(246, 'V5', '5.2', 'Sanitization and Sandboxing', '5.2.7', 'Verify that the application sanitizes, disables, or sandboxes user-supplied Scalable Vector Graphics (SVG) scriptable content, especially as they relate to XSS resulting from inline scripts, and foreignObject.', true, true, true, '159', '', '4.0.3', '2026-02-08 22:04:19.652089'),
	(247, 'V5', '5.2', 'Sanitization and Sandboxing', '5.2.8', 'Verify that the application sanitizes, disables, or sandboxes user-supplied scriptable or expression template language content, such as Markdown, CSS or XSL stylesheets, BBCode, or similar.', true, true, true, '94', '', '4.0.3', '2026-02-08 22:04:19.754528'),
	(248, 'V5', '5.3', 'Output Encoding and Injection Prevention', '5.3.1', 'Verify that output encoding is relevant for the interpreter and context required. For example, use encoders specifically for HTML values, HTML attributes, JavaScript, URL parameters, HTTP headers, SMTP, and others as the context requires, especially from untrusted inputs (e.g. names with Unicode or apostrophes, such as ねこ or O''Hara). ([C4](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '116', '', '4.0.3', '2026-02-08 22:04:19.851489'),
	(249, 'V5', '5.3', 'Output Encoding and Injection Prevention', '5.3.2', 'Verify that output encoding preserves the user''s chosen character set and locale, such that any Unicode character point is valid and safely handled. ([C4](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '176', '', '4.0.3', '2026-02-08 22:04:19.948694'),
	(250, 'V5', '5.3', 'Output Encoding and Injection Prevention', '5.3.3', 'Verify that context-aware, preferably automated - or at worst, manual - output escaping protects against reflected, stored, and DOM based XSS. ([C4](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '79', '', '4.0.3', '2026-02-08 22:04:20.045368'),
	(251, 'V5', '5.3', 'Output Encoding and Injection Prevention', '5.3.4', 'Verify that data selection or database queries (e.g. SQL, HQL, ORM, NoSQL) use parameterized queries, ORMs, entity frameworks, or are otherwise protected from database injection attacks. ([C3](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '89', '', '4.0.3', '2026-02-08 22:04:20.142029'),
	(252, 'V5', '5.3', 'Output Encoding and Injection Prevention', '5.3.5', 'Verify that where parameterized or safer mechanisms are not present, context-specific output encoding is used to protect against injection attacks, such as the use of SQL escaping to protect against SQL injection. ([C3, C4](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '89', '', '4.0.3', '2026-02-08 22:04:20.242005'),
	(253, 'V5', '5.3', 'Output Encoding and Injection Prevention', '5.3.6', 'Verify that the application protects against JSON injection attacks, JSON eval attacks, and JavaScript expression evaluation. ([C4](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '830', '', '4.0.3', '2026-02-08 22:04:20.342584'),
	(254, 'V5', '5.3', 'Output Encoding and Injection Prevention', '5.3.7', 'Verify that the application protects against LDAP injection vulnerabilities, or that specific security controls to prevent LDAP injection have been implemented. ([C4](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '90', '', '4.0.3', '2026-02-08 22:04:20.439038'),
	(255, 'V5', '5.3', 'Output Encoding and Injection Prevention', '5.3.8', 'Verify that the application protects against OS command injection and that operating system calls use parameterized OS queries or use contextual command line output encoding. ([C4](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '78', '', '4.0.3', '2026-02-08 22:04:20.541107'),
	(256, 'V5', '5.3', 'Output Encoding and Injection Prevention', '5.3.9', 'Verify that the application protects against Local File Inclusion (LFI) or Remote File Inclusion (RFI) attacks.', true, true, true, '829', '', '4.0.3', '2026-02-08 22:04:20.638627'),
	(257, 'V5', '5.3', 'Output Encoding and Injection Prevention', '5.3.10', 'Verify that the application protects against XPath injection or XML injection attacks. ([C4](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '643', '', '4.0.3', '2026-02-08 22:04:20.746659'),
	(258, 'V5', '5.4', 'Memory, String, and Unmanaged Code', '5.4.1', 'Verify that the application uses memory-safe string, safer memory copy and pointer arithmetic to detect or prevent stack, buffer, or heap overflows.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:20.846585'),
	(259, 'V5', '5.4', 'Memory, String, and Unmanaged Code', '5.4.2', 'Verify that format strings do not take potentially hostile input, and are constant.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:20.944597'),
	(260, 'V5', '5.4', 'Memory, String, and Unmanaged Code', '5.4.3', 'Verify that sign, range, and input validation techniques are used to prevent integer overflows.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:21.044059'),
	(261, 'V5', '5.5', 'Deserialization Prevention', '5.5.1', 'Verify that serialized objects use integrity checks or are encrypted to prevent hostile object creation or data tampering. ([C5](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '502', '', '4.0.3', '2026-02-08 22:04:21.141167'),
	(262, 'V5', '5.5', 'Deserialization Prevention', '5.5.2', 'Verify that the application correctly restricts XML parsers to only use the most restrictive configuration possible and to ensure that unsafe features such as resolving external entities are disabled to prevent XML eXternal Entity (XXE) attacks.', true, true, true, '611', '', '4.0.3', '2026-02-08 22:04:21.244052'),
	(263, 'V5', '5.5', 'Deserialization Prevention', '5.5.3', 'Verify that deserialization of untrusted data is avoided or is protected in both custom code and third-party libraries (such as JSON, XML and YAML parsers).', true, true, true, '502', '', '4.0.3', '2026-02-08 22:04:21.343515'),
	(264, 'V5', '5.5', 'Deserialization Prevention', '5.5.4', 'Verify that when parsing JSON in browsers or JavaScript-based backends, JSON.parse is used to parse the JSON document. Do not use eval() to parse JSON.', true, true, true, '95', '', '4.0.3', '2026-02-08 22:04:21.440599'),
	(265, 'V6', '6.1', 'Data Classification', '6.1.1', 'Verify that regulated private data is stored encrypted while at rest, such as Personally Identifiable Information (PII), sensitive personal information, or data assessed likely to be subject to EU''s GDPR.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:21.897536'),
	(266, 'V6', '6.1', 'Data Classification', '6.1.2', 'Verify that regulated health data is stored encrypted while at rest, such as medical records, medical device details, or de-anonymized research records.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:21.995651'),
	(267, 'V6', '6.1', 'Data Classification', '6.1.3', 'Verify that regulated financial data is stored encrypted while at rest, such as financial accounts, defaults or credit history, tax records, pay history, beneficiaries, or de-anonymized market or research records.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:22.093686'),
	(268, 'V6', '6.2', 'Algorithms', '6.2.1', 'Verify that all cryptographic modules fail securely, and errors are handled in a way that does not enable Padding Oracle attacks.', true, true, true, '310', '', '4.0.3', '2026-02-08 22:04:22.190798'),
	(269, 'V6', '6.2', 'Algorithms', '6.2.2', 'Verify that industry proven or government approved cryptographic algorithms, modes, and libraries are used, instead of custom coded cryptography. ([C8](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:22.289088'),
	(270, 'V6', '6.2', 'Algorithms', '6.2.3', 'Verify that encryption initialization vector, cipher configuration, and block modes are configured securely using the latest advice.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:22.387064'),
	(271, 'V6', '6.2', 'Algorithms', '6.2.4', 'Verify that random number, encryption or hashing algorithms, key lengths, rounds, ciphers or modes, can be reconfigured, upgraded, or swapped at any time, to protect against cryptographic breaks. ([C8](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:22.485072'),
	(272, 'V6', '6.2', 'Algorithms', '6.2.5', 'Verify that known insecure block modes (i.e. ECB, etc.), padding modes (i.e. PKCS#1 v1.5, etc.), ciphers with small block sizes (i.e. Triple-DES, Blowfish, etc.), and weak hashing algorithms (i.e. MD5, SHA1, etc.) are not used unless required for backwards compatibility.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:22.584072'),
	(273, 'V6', '6.2', 'Algorithms', '6.2.6', 'Verify that nonces, initialization vectors, and other single use numbers must not be used more than once with a given encryption key. The method of generation must be appropriate for the algorithm being used.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:22.687073'),
	(274, 'V6', '6.3', 'Random Values', '6.3.1', 'Verify that all random numbers, random file names, random GUIDs, and random strings are generated using the cryptographic module''s approved cryptographically secure random number generator when these random values are intended to be not guessable by an attacker.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:22.786546'),
	(275, 'V6', '6.3', 'Random Values', '6.3.2', 'Verify that random GUIDs are created using the GUID v4 algorithm, and a Cryptographically-secure Pseudo-random Number Generator (CSPRNG). GUIDs created using other pseudo-random number generators may be predictable.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:22.886076'),
	(276, 'V6', '6.4', 'Secret Management', '6.4.1', 'Verify that a secrets management solution such as a key vault is used to securely create, store, control access to and destroy secrets. ([C8](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:22.986039'),
	(277, 'V6', '6.4', 'Secret Management', '6.4.2', 'Verify that key material is not exposed to the application but instead uses an isolated security module like a vault for cryptographic operations. ([C8](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:23.091707'),
	(278, 'V7', '7.1', 'Log Content', '7.1.1', 'Verify that the application does not log credentials or payment details. Session tokens should only be stored in logs in an irreversible, hashed form. ([C9, C10](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '532', '', '4.0.3', '2026-02-08 22:04:23.466585'),
	(279, 'V7', '7.1', 'Log Content', '7.1.2', 'Verify that the application does not log other sensitive data as defined under local privacy laws or relevant security policy. ([C9](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '532', '', '4.0.3', '2026-02-08 22:04:23.564572'),
	(280, 'V7', '7.1', 'Log Content', '7.1.3', 'Verify that the application logs security relevant events including successful and failed authentication events, access control failures, deserialization failures and input validation failures. ([C5, C7](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:23.662079'),
	(281, 'V7', '7.1', 'Log Content', '7.1.4', 'Verify that each log event includes necessary information that would allow for a detailed investigation of the timeline when an event happens. ([C9](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:23.760361'),
	(282, 'V7', '7.2', 'Log Processing', '7.2.1', 'Verify that all authentication decisions are logged, without storing sensitive session tokens or passwords. This should include requests with relevant metadata needed for security investigations.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:23.859821'),
	(283, 'V7', '7.2', 'Log Processing', '7.2.2', 'Verify that all access control decisions can be logged and all failed decisions are logged. This should include requests with relevant metadata needed for security investigations.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:23.956918'),
	(284, 'V7', '7.3', 'Log Protection', '7.3.1', 'Verify that all logging components appropriately encode data to prevent log injection. ([C9](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:24.057853'),
	(285, 'V7', '7.3', 'Log Protection', '7.3.3', 'Verify that security logs are protected from unauthorized access and modification. ([C9](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:24.15718'),
	(286, 'V7', '7.4', 'Error Handling', '7.4.1', 'Verify that a generic message is shown when an unexpected or security sensitive error occurs, potentially with a unique ID which support personnel can use to investigate. ([C10](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '210', '', '4.0.3', '2026-02-08 22:04:24.257715'),
	(287, 'V7', '7.4', 'Error Handling', '7.4.2', 'Verify that exception handling (or a functional equivalent) is used across the codebase to account for expected and unexpected error conditions. ([C10](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:24.353596'),
	(288, 'V7', '7.4', 'Error Handling', '7.4.3', 'Verify that a "last resort" error handler is defined which will catch all unhandled exceptions. ([C10](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:24.451107'),
	(289, 'V8', '8.1', 'General Data Protection', '8.1.1', 'Verify the application protects sensitive data from being cached in server components such as load balancers and application caches.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:24.825286'),
	(290, 'V8', '8.1', 'General Data Protection', '8.1.2', 'Verify that all cached or temporary copies of sensitive data stored on the server are protected from unauthorized access or purged/invalidated after the authorized user accesses the sensitive data.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:24.923677'),
	(291, 'V8', '8.1', 'General Data Protection', '8.1.3', 'Verify the application minimizes the number of parameters in a request, such as hidden fields, Ajax variables, cookies and header values.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:25.020249'),
	(292, 'V8', '8.1', 'General Data Protection', '8.1.4', 'Verify the application can detect and alert on abnormal numbers of requests, such as by IP, user, total per hour or day, or whatever makes sense for the application.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:25.118121'),
	(293, 'V8', '8.2', 'Client-side Data Protection', '8.2.1', 'Verify the application sets sufficient anti-caching headers so that sensitive data is not cached in modern browsers.', true, true, true, '525', '', '4.0.3', '2026-02-08 22:04:25.220712'),
	(294, 'V8', '8.2', 'Client-side Data Protection', '8.2.2', 'Verify that data stored in browser storage (such as localStorage, sessionStorage, IndexedDB, or cookies) does not contain sensitive data.', true, true, true, '922', '', '4.0.3', '2026-02-08 22:04:25.32364'),
	(295, 'V8', '8.2', 'Client-side Data Protection', '8.2.3', 'Verify that authenticated data is cleared from client storage, such as the browser DOM, after the client or session is terminated.', true, true, true, '922', '', '4.0.3', '2026-02-08 22:04:25.420164'),
	(296, 'V8', '8.3', 'Sensitive Private Data', '8.3.1', 'Verify that sensitive data is sent to the server in the HTTP message body or headers, and that query string parameters from any HTTP verb do not contain sensitive data.', true, true, true, '319', '', '4.0.3', '2026-02-08 22:04:25.522151'),
	(297, 'V8', '8.3', 'Sensitive Private Data', '8.3.2', 'Verify that users have a method to remove or export their data on demand.', true, true, true, '212', '', '4.0.3', '2026-02-08 22:04:25.61867'),
	(298, 'V8', '8.3', 'Sensitive Private Data', '8.3.3', 'Verify that users are provided clear language regarding collection and use of supplied personal information and that users have provided opt-in consent for the use of that data before it is used in any way.', true, true, true, '285', '', '4.0.3', '2026-02-08 22:04:25.717656'),
	(299, 'V8', '8.3', 'Sensitive Private Data', '8.3.4', 'Verify that all sensitive data created and processed by the application has been identified, and ensure that a policy is in place on how to deal with sensitive data. ([C8](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '200', '', '4.0.3', '2026-02-08 22:04:25.815163'),
	(300, 'V8', '8.3', 'Sensitive Private Data', '8.3.5', 'Verify accessing sensitive data is audited (without logging the sensitive data itself), if the data is collected under relevant data protection directives or where logging of access is required.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:25.918124'),
	(301, 'V8', '8.3', 'Sensitive Private Data', '8.3.6', 'Verify that sensitive information contained in memory is overwritten as soon as it is no longer required to mitigate memory dumping attacks, using zeroes or random data.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:26.016681'),
	(302, 'V8', '8.3', 'Sensitive Private Data', '8.3.7', 'Verify that sensitive or private information that is required to be encrypted, is encrypted using approved algorithms that provide both confidentiality and integrity. ([C8](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:26.118193'),
	(303, 'V8', '8.3', 'Sensitive Private Data', '8.3.8', 'Verify that sensitive personal information is subject to data retention classification, such that old or out of date data is deleted automatically, on a schedule, or as the situation requires.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:26.216234'),
	(304, 'V9', '9.1', 'Client Communication Security', '9.1.1', 'Verify that TLS is used for all client connectivity, and does not fall back to insecure or unencrypted communications. ([C8](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '319', '', '4.0.3', '2026-02-08 22:04:26.586177'),
	(305, 'V9', '9.1', 'Client Communication Security', '9.1.2', 'Verify using up to date TLS testing tools that only strong cipher suites are enabled, with the strongest cipher suites set as preferred.', true, true, true, '326', '', '4.0.3', '2026-02-08 22:04:26.684271'),
	(306, 'V9', '9.1', 'Client Communication Security', '9.1.3', 'Verify that only the latest recommended versions of the TLS protocol are enabled, such as TLS 1.2 and TLS 1.3. The latest version of the TLS protocol should be the preferred option.', true, true, true, '326', '', '4.0.3', '2026-02-08 22:04:26.781126'),
	(307, 'V9', '9.2', 'Server Communication Security', '9.2.1', 'Verify that connections to and from the server use trusted TLS certificates. Where internally generated or self-signed certificates are used, the server must be configured to only trust specific internal CAs and specific self-signed certificates. All others should be rejected.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:26.882634'),
	(308, 'V9', '9.2', 'Server Communication Security', '9.2.2', 'Verify that encrypted communications such as TLS is used for all inbound and outbound connections, including for management ports, monitoring, authentication, API, or web service calls, database, cloud, serverless, mainframe, external, and partner connections. The server must not fall back to insecure or unencrypted protocols.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:26.980126'),
	(309, 'V9', '9.2', 'Server Communication Security', '9.2.3', 'Verify that all encrypted connections to external systems that involve sensitive information or functions are authenticated.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:27.080628'),
	(310, 'V9', '9.2', 'Server Communication Security', '9.2.4', 'Verify that proper certification revocation, such as Online Certificate Status Protocol (OCSP) Stapling, is enabled and configured.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:27.178148'),
	(311, 'V10', '10.2', 'Malicious Code Search', '10.2.1', 'Verify that the application source code and third party libraries do not contain unauthorized phone home or data collection capabilities. Where such functionality exists, obtain the user''s permission for it to operate before collecting any data.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:27.546144'),
	(312, 'V10', '10.2', 'Malicious Code Search', '10.2.2', 'Verify that the application does not ask for unnecessary or excessive permissions to privacy related features or sensors, such as contacts, cameras, microphones, or location.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:27.647754'),
	(313, 'V10', '10.3', 'Application Integrity', '10.3.1', 'Verify that if the application has a client or server auto-update feature, updates should be obtained over secure channels and digitally signed. The update code must validate the digital signature of the update before installing or executing the update.', true, true, true, '16', '', '4.0.3', '2026-02-08 22:04:27.743695'),
	(314, 'V10', '10.3', 'Application Integrity', '10.3.2', 'Verify that the application employs integrity protections, such as code signing or subresource integrity. The application must not load or execute code from untrusted sources, such as loading includes, modules, plugins, code, or libraries from untrusted sources or the Internet.', true, true, true, '353', '', '4.0.3', '2026-02-08 22:04:27.841277');
INSERT INTO public.asvs_requirements VALUES
	(315, 'V10', '10.3', 'Application Integrity', '10.3.3', 'Verify that the application has protection from subdomain takeovers if the application relies upon DNS entries or DNS subdomains, such as expired domain names, out of date DNS pointers or CNAMEs, expired projects at public source code repos, or transient cloud APIs, serverless functions, or storage buckets (*autogen-bucket-id*.cloud.example.com) or similar. Protections can include ensuring that DNS names used by applications are regularly checked for expiry or change.', true, true, true, '350', '', '4.0.3', '2026-02-08 22:04:27.940649'),
	(316, 'V11', '11.1', 'Business Logic Security', '11.1.1', 'Verify that the application will only process business logic flows for the same user in sequential step order and without skipping steps.', true, true, true, '841', '', '4.0.3', '2026-02-08 22:04:28.309326'),
	(317, 'V11', '11.1', 'Business Logic Security', '11.1.2', 'Verify that the application will only process business logic flows with all steps being processed in realistic human time, i.e. transactions are not submitted too quickly.', true, true, true, '799', '', '4.0.3', '2026-02-08 22:04:28.411228'),
	(318, 'V11', '11.1', 'Business Logic Security', '11.1.3', 'Verify the application has appropriate limits for specific business actions or transactions which are correctly enforced on a per user basis.', true, true, true, '770', '', '4.0.3', '2026-02-08 22:04:28.508711'),
	(319, 'V11', '11.1', 'Business Logic Security', '11.1.4', 'Verify that the application has anti-automation controls to protect against excessive calls such as mass data exfiltration, business logic requests, file uploads or denial of service attacks.', true, true, true, '770', '', '4.0.3', '2026-02-08 22:04:28.607723'),
	(320, 'V11', '11.1', 'Business Logic Security', '11.1.5', 'Verify the application has business logic limits or validation to protect against likely business risks or threats, identified using threat modeling or similar methodologies.', true, true, true, '841', '', '4.0.3', '2026-02-08 22:04:28.704738'),
	(321, 'V11', '11.1', 'Business Logic Security', '11.1.6', 'Verify that the application does not suffer from "Time Of Check to Time Of Use" (TOCTOU) issues or other race conditions for sensitive operations.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:28.801772'),
	(322, 'V11', '11.1', 'Business Logic Security', '11.1.7', 'Verify that the application monitors for unusual events or activity from a business logic perspective. For example, attempts to perform actions out of order or actions which a normal user would never attempt. ([C9](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:28.900738'),
	(323, 'V11', '11.1', 'Business Logic Security', '11.1.8', 'Verify that the application has configurable alerting when automated attacks or unusual activity is detected.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:29.00173'),
	(324, 'V12', '12.1', 'File Upload', '12.1.1', 'Verify that the application will not accept large files that could fill up storage or cause a denial of service.', true, true, true, '400', '', '4.0.3', '2026-02-08 22:04:29.378204'),
	(325, 'V12', '12.1', 'File Upload', '12.1.2', 'Verify that the application checks compressed files (e.g. zip, gz, docx, odt) against maximum allowed uncompressed size and against maximum number of files before uncompressing the file.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:29.474771'),
	(326, 'V12', '12.1', 'File Upload', '12.1.3', 'Verify that a file size quota and maximum number of files per user is enforced to ensure that a single user cannot fill up the storage with too many files, or excessively large files.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:29.572503'),
	(327, 'V12', '12.2', 'File Integrity', '12.2.1', 'Verify that files obtained from untrusted sources are validated to be of expected type based on the file''s content.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:29.669471'),
	(328, 'V12', '12.3', 'File Execution', '12.3.1', 'Verify that user-submitted filename metadata is not used directly by system or framework filesystems and that a URL API is used to protect against path traversal.', true, true, true, '22', '', '4.0.3', '2026-02-08 22:04:29.767852'),
	(329, 'V12', '12.3', 'File Execution', '12.3.2', 'Verify that user-submitted filename metadata is validated or ignored to prevent the disclosure, creation, updating or removal of local files (LFI).', true, true, true, '73', '', '4.0.3', '2026-02-08 22:04:29.865718'),
	(330, 'V12', '12.3', 'File Execution', '12.3.3', 'Verify that user-submitted filename metadata is validated or ignored to prevent the disclosure or execution of remote files via Remote File Inclusion (RFI) or Server-side Request Forgery (SSRF) attacks.', true, true, true, '98', '', '4.0.3', '2026-02-08 22:04:29.964235'),
	(331, 'V12', '12.3', 'File Execution', '12.3.4', 'Verify that the application protects against Reflective File Download (RFD) by validating or ignoring user-submitted filenames in a JSON, JSONP, or URL parameter, the response Content-Type header should be set to text/plain, and the Content-Disposition header should have a fixed filename.', true, true, true, '641', '', '4.0.3', '2026-02-08 22:04:30.060911'),
	(332, 'V12', '12.3', 'File Execution', '12.3.5', 'Verify that untrusted file metadata is not used directly with system API or libraries, to protect against OS command injection.', true, true, true, '78', '', '4.0.3', '2026-02-08 22:04:30.160268'),
	(333, 'V12', '12.3', 'File Execution', '12.3.6', 'Verify that the application does not include and execute functionality from untrusted sources, such as unverified content distribution networks, JavaScript libraries, node npm libraries, or server-side DLLs.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:30.258715'),
	(334, 'V12', '12.4', 'File Storage', '12.4.1', 'Verify that files obtained from untrusted sources are stored outside the web root, with limited permissions.', true, true, true, '552', '', '4.0.3', '2026-02-08 22:04:30.356768'),
	(335, 'V12', '12.4', 'File Storage', '12.4.2', 'Verify that files obtained from untrusted sources are scanned by antivirus scanners to prevent upload and serving of known malicious content.', true, true, true, '509', '', '4.0.3', '2026-02-08 22:04:30.4577'),
	(336, 'V12', '12.5', 'File Download', '12.5.1', 'Verify that the web tier is configured to serve only files with specific file extensions to prevent unintentional information and source code leakage. For example, backup files (e.g. .bak), temporary working files (e.g. .swp), compressed files (.zip, .tar.gz, etc) and other extensions commonly used by editors should be blocked unless required.', true, true, true, '552', '', '4.0.3', '2026-02-08 22:04:30.611413'),
	(337, 'V12', '12.5', 'File Download', '12.5.2', 'Verify that direct requests to uploaded files will never be executed as HTML/JavaScript content.', true, true, true, '434', '', '4.0.3', '2026-02-08 22:04:30.7094'),
	(338, 'V12', '12.6', 'SSRF Protection', '12.6.1', 'Verify that the web or application server is configured with an allow list of resources or systems to which the server can send requests or load data/files from.', true, true, true, '918', '', '4.0.3', '2026-02-08 22:04:30.810188'),
	(339, 'V13', '13.1', 'Generic Web Service Security', '13.1.1', 'Verify that all application components use the same encodings and parsers to avoid parsing attacks that exploit different URI or file parsing behavior that could be used in SSRF and RFI attacks.', true, true, true, '116', '', '4.0.3', '2026-02-08 22:04:31.178699'),
	(340, 'V13', '13.1', 'Generic Web Service Security', '13.1.3', 'Verify API URLs do not expose sensitive information, such as the API key, session tokens etc.', true, true, true, '598', '', '4.0.3', '2026-02-08 22:04:31.277173'),
	(341, 'V13', '13.1', 'Generic Web Service Security', '13.1.4', 'Verify that authorization decisions are made at both the URI, enforced by programmatic or declarative security at the controller or router, and at the resource level, enforced by model-based permissions.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:31.374253'),
	(342, 'V13', '13.1', 'Generic Web Service Security', '13.1.5', 'Verify that requests containing unexpected or missing content types are rejected with appropriate headers (HTTP response status 406 Unacceptable or 415 Unsupported Media Type).', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:31.472804'),
	(343, 'V13', '13.2', 'RESTful Web Service', '13.2.1', 'Verify that enabled RESTful HTTP methods are a valid choice for the user or action, such as preventing normal users using DELETE or PUT on protected API or resources.', true, true, true, '650', '', '4.0.3', '2026-02-08 22:04:31.571736'),
	(344, 'V13', '13.2', 'RESTful Web Service', '13.2.2', 'Verify that JSON schema validation is in place and verified before accepting input.', true, true, true, '20', '', '4.0.3', '2026-02-08 22:04:31.670701'),
	(345, 'V13', '13.2', 'RESTful Web Service', '13.2.3', 'Verify that RESTful web services that utilize cookies are protected from Cross-Site Request Forgery via the use of at least one or more of the following: double submit cookie pattern, CSRF nonces, or Origin request header checks.', true, true, true, '352', '', '4.0.3', '2026-02-08 22:04:31.771231'),
	(346, 'V13', '13.2', 'RESTful Web Service', '13.2.5', 'Verify that REST services explicitly check the incoming Content-Type to be the expected one, such as application/xml or application/json.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:31.868261'),
	(347, 'V13', '13.2', 'RESTful Web Service', '13.2.6', 'Verify that the message headers and payload are trustworthy and not modified in transit. Requiring strong encryption for transport (TLS only) may be sufficient in many cases as it provides both confidentiality and integrity protection. Per-message digital signatures can provide additional assurance on top of the transport protections for high-security applications but bring with them additional complexity and risks to weigh against the benefits.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:31.974747'),
	(348, 'V13', '13.3', 'SOAP Web Service', '13.3.1', 'Verify that XSD schema validation takes place to ensure a properly formed XML document, followed by validation of each input field before any processing of that data takes place.', true, true, true, '20', '', '4.0.3', '2026-02-08 22:04:32.072224'),
	(349, 'V13', '13.3', 'SOAP Web Service', '13.3.2', 'Verify that the message payload is signed using WS-Security to ensure reliable transport between client and service.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:32.171198'),
	(350, 'V13', '13.4', 'GraphQL', '13.4.1', 'Verify that a query allow list or a combination of depth limiting and amount limiting is used to prevent GraphQL or data layer expression Denial of Service (DoS) as a result of expensive, nested queries. For more advanced scenarios, query cost analysis should be used.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:32.269747'),
	(351, 'V13', '13.4', 'GraphQL', '13.4.2', 'Verify that GraphQL or other data layer authorization logic should be implemented at the business logic layer instead of the GraphQL layer.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:32.371268'),
	(352, 'V14', '14.1', 'Build and Deploy', '14.1.2', 'Verify that compiler flags are configured to enable all available buffer overflow protections and warnings, including stack randomization, data execution prevention, and to break the build if an unsafe pointer, memory, format string, integer, or string operations are found.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:32.733868'),
	(353, 'V14', '14.1', 'Build and Deploy', '14.1.3', 'Verify that server configuration is hardened as per the recommendations of the application server and frameworks in use.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:32.832291'),
	(354, 'V14', '14.2', 'Dependency', '14.2.1', 'Verify that all components are up to date, preferably using a dependency checker during build or compile time. ([C2](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '1026', '', '4.0.3', '2026-02-08 22:04:32.928737'),
	(355, 'V14', '14.2', 'Dependency', '14.2.2', 'Verify that all unneeded features, documentation, sample applications and configurations are removed.', true, true, true, '1002', '', '4.0.3', '2026-02-08 22:04:33.029253'),
	(356, 'V14', '14.2', 'Dependency', '14.2.3', 'Verify that if application assets, such as JavaScript libraries, CSS or web fonts, are hosted externally on a Content Delivery Network (CDN) or external provider, Subresource Integrity (SRI) is used to validate the integrity of the asset.', true, true, true, '829', '', '4.0.3', '2026-02-08 22:04:33.1303'),
	(357, 'V14', '14.2', 'Dependency', '14.2.4', 'Verify that third party components come from pre-defined, trusted and continually maintained repositories. ([C2](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:33.232807'),
	(358, 'V14', '14.2', 'Dependency', '14.2.6', 'Verify that the attack surface is reduced by sandboxing or encapsulating third party libraries to expose only the required behaviour into the application. ([C2](https://owasp.org/www-project-proactive-controls/#div-numbering))', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:33.337737'),
	(359, 'V14', '14.3', 'Unintended Security Disclosure', '14.3.2', 'Verify that web or application server and application framework debug modes are disabled in production to eliminate debug features, developer consoles, and unintended security disclosures.', true, true, true, '497', '', '4.0.3', '2026-02-08 22:04:33.435387'),
	(360, 'V14', '14.3', 'Unintended Security Disclosure', '14.3.3', 'Verify that the HTTP headers or any part of the HTTP response do not expose detailed version information of system components.', true, true, true, '200', '', '4.0.3', '2026-02-08 22:04:33.532815'),
	(361, 'V14', '14.4', 'HTTP Security Headers', '14.4.1', 'Verify that every HTTP response contains a Content-Type header. Also specify a safe character set (e.g., UTF-8, ISO-8859-1) if the content types are text/*, /+xml and application/xml. Content must match with the provided Content-Type header.', true, true, true, '173', '', '4.0.3', '2026-02-08 22:04:33.628751'),
	(362, 'V14', '14.4', 'HTTP Security Headers', '14.4.2', 'Verify that all API responses contain a Content-Disposition: attachment; filename="api.json" header (or other appropriate filename for the content type).', true, true, true, '116', '', '4.0.3', '2026-02-08 22:04:33.729239'),
	(363, 'V14', '14.4', 'HTTP Security Headers', '14.4.3', 'Verify that a Content Security Policy (CSP) response header is in place that helps mitigate impact for XSS attacks like HTML, DOM, JSON, and JavaScript injection vulnerabilities.', true, true, true, '1021', '', '4.0.3', '2026-02-08 22:04:33.827797'),
	(364, 'V14', '14.4', 'HTTP Security Headers', '14.4.4', 'Verify that all responses contain a X-Content-Type-Options: nosniff header.', true, true, true, '116', '', '4.0.3', '2026-02-08 22:04:33.92927'),
	(365, 'V14', '14.4', 'HTTP Security Headers', '14.4.5', 'Verify that a Strict-Transport-Security header is included on all responses and for all subdomains, such as Strict-Transport-Security: max-age=15724800; includeSubdomains.', true, true, true, '523', '', '4.0.3', '2026-02-08 22:04:34.027307'),
	(366, 'V14', '14.4', 'HTTP Security Headers', '14.4.6', 'Verify that a suitable Referrer-Policy header is included to avoid exposing sensitive information in the URL through the Referer header to untrusted parties.', true, true, true, '116', '', '4.0.3', '2026-02-08 22:04:34.124783'),
	(367, 'V14', '14.4', 'HTTP Security Headers', '14.4.7', 'Verify that the content of a web application cannot be embedded in a third-party site by default and that embedding of the exact resources is only allowed where necessary by using suitable Content-Security-Policy: frame-ancestors and X-Frame-Options response headers.', true, true, true, '1021', '', '4.0.3', '2026-02-08 22:04:34.222274'),
	(368, 'V14', '14.5', 'HTTP Request Header Validation', '14.5.1', 'Verify that the application server only accepts the HTTP methods in use by the application/API, including pre-flight OPTIONS, and logs/alerts on any requests that are not valid for the application context.', true, true, true, '749', '', '4.0.3', '2026-02-08 22:04:34.318832'),
	(369, 'V14', '14.5', 'HTTP Request Header Validation', '14.5.2', 'Verify that the supplied Origin header is not used for authentication or access control decisions, as the Origin header can easily be changed by an attacker.', true, true, true, '346', '', '4.0.3', '2026-02-08 22:04:34.417287'),
	(370, 'V14', '14.5', 'HTTP Request Header Validation', '14.5.3', 'Verify that the Cross-Origin Resource Sharing (CORS) Access-Control-Allow-Origin header uses a strict allow list of trusted domains and subdomains to match against and does not support the "null" origin.', true, true, true, '346', '', '4.0.3', '2026-02-08 22:04:34.515387'),
	(371, 'V14', '14.5', 'HTTP Request Header Validation', '14.5.4', 'Verify that HTTP headers added by a trusted proxy or SSO devices, such as a bearer token, are authenticated by the application.', true, true, true, '', '', '4.0.3', '2026-02-08 22:04:34.616284');
INSERT INTO public.audit_findings VALUES
	(1, 3, 'iuhhiihuhiuhui', 'oihiojooijoiijo', 'medium', 'open', NULL, 1, '2026-02-01 13:17:33.504957', '2026-02-01 13:17:33.504957', NULL),
	(2, 3, 'dsdfsdf', 'hrthrthrth', 'high', 'open', NULL, 1, '2026-03-26 15:48:30.378878', '2026-03-26 15:48:30.378878', NULL);
