INSERT INTO public.comments VALUES
	(1, 1, 'policy', 1612, 'llllll', '2026-02-19 12:29:08.144545', '2026-02-19 12:29:08.144545', 3, NULL, false, NULL, NULL, NULL),
	(2, 1, 'policy', 1612, 'This has to be rewritten', '2026-02-19 13:33:51.17503', '2026-02-19 13:37:29.701', 3, NULL, true, 1, '2026-02-19 13:37:29.701', '"{\"quote\":\"The purpose of this Network Security Policy is to establish the comprehensive standards, architectural principles, and operational procedures required to protect the confidentiality, integrity, \",\"index\":36,\"length\":194}"'),
	(3, 1, 'policy', 1612, 'test', '2026-02-19 13:57:44.77022', '2026-02-19 13:57:44.77022', 3, NULL, false, NULL, NULL, '"{\"quote\":\"The purpose of this Network Security Policy is to establish the comprehensive standards, architectural principles, and operational procedures required to protect the confidentiality, integrity, \",\"index\":36,\"length\":194}"'),
	(4, 1, 'policy', 1612, 'test2', '2026-02-19 13:58:27.207618', '2026-02-19 13:58:27.207618', 3, NULL, false, NULL, NULL, '"{\"quote\":\"Personnel: All full-time and part-time employees, contractors, consultants, temporary staff, interns, and any other third-party individuals granted access to Intellfence networks or data.\\nAssets: All network infrastructure components, including but not limited to: routers, switches, \",\"index\":999,\"length\":284}"'),
	(5, 1, 'policy', 1628, 'tesrt', '2026-02-20 10:55:11.204588', '2026-02-20 10:55:11.204588', 3, NULL, false, NULL, NULL, '"{\"quote\":\"his policy is explicitly designed to satisfy and provide auditable evidence for key control requirements within ISO/IEC 27001:2022 (Annex A controls A.5.9, A.5.10, A.5.12, A.5.13, A.5.15, A.8.1, A.8.2, A.8.3), SOC 2 (CCS 2017 Trust Services Criteria, particularly Security, Availability, and Confidentiality), and aligns with principles of GDPR, CCPA/CPRA, and other relevant data protection frameworks.\",\"index\":791,\"length\":403}"'),
	(6, 1, 'policy', 1628, 'lkjjjkpojpojpojpopopopo', '2026-02-20 11:03:26.36696', '2026-02-20 11:03:26.36696', 3, NULL, false, NULL, NULL, '"{\"quote\":\"All proposed revisions must be documented, circulated for stakeholder comment, and submitted for formal approval to the executive management team or designated governance committee (e.g., Security & Compliance Steering Committee). Upon approval, the revised policy shall be communicated to all affected personnel, and the previous version shall be archived. The latest approved version of this policy shall be made readily accessible to all personnel covered by its scope through the corporate intranet or policy management system.\",\"index\":19633,\"length\":531}"'),
	(7, 1, 'policy', 1628, 'test', '2026-02-20 11:03:48.718353', '2026-02-20 11:03:48.718353', 3, NULL, false, NULL, NULL, '"{\"quote\":\"Record: Recorded information, in any format or medium, created, received, and maintained by Intellfence as evidence of, or in connection with, its legal obligations, business transactions, strategic decisions, operational activities, or client engagements. A record serves as the definitive source of truth for the matter it documents.\",\"index\":2228,\"length\":335}"'),
	(8, 1, 'policy', 1634, 'fgfggdfg', '2026-02-20 13:22:30.405063', '2026-02-20 13:22:30.405063', 3, NULL, false, NULL, NULL, '"{\"quote\":\"This policy establishes the mandatory framework for the timely identification, containment, eradication, investigation, notification, and recovery from a Data Breach or Security Incident involving Intellfence information assets, including client data for which Intellfence acts as a Data Processor or Sub-processor. The primary purpose is to minimize operational disruption, financial loss, reputational damage, and legal liability. As a cybersecurity provider, our response must exemplify industry best practices and ensure strict compliance with statutory, regulatory, and contractual obligations across our operational regions (North America and European Union). This policy is designed to meet and exceed the requirements of key frameworks including ISO/IEC 27001:2022, SOC 2, the EU General Data Protection Regulation (GDPR), and various U.S. state data breach notification laws, thereby preserving client trust and our market credibility.\\n2.0 Scope\",\"index\":290,\"length\":954}"'),
	(9, 1, 'policy', 1636, 'fwefwef', '2026-02-20 13:52:32.768857', '2026-02-20 13:52:32.768857', 3, NULL, false, NULL, NULL, '"{\"quote\":\"This Wireless Security Policy shall be reviewed by the Information Security Team at least annually. Reviews may be triggered more frequently in response to significant security incidents, material changes in the threat landscape, the introduction of new wireless technologies, or updates to relevant compliance standards (e.g., ISO 27001, NIST guidelines).\",\"index\":15962,\"length\":356}"'),
	(10, 1, 'policy', 1649, 'ihojhoijoj', '2026-02-20 18:54:31.398731', '2026-02-20 18:54:31.398731', 3, NULL, false, NULL, NULL, '"{\"quote\":\"Compliance with this Incident Response Policy is mandatory for all covered individuals and entities. Adherence is critical to the security of Intellfence and its clients.\",\"index\":18656,\"length\":170}"');
