INSERT INTO public.control_history VALUES
	(1, 125, 1, 'The entity maintains, monitors, and evaluates', 'The entity maintains, monitors, and evaluates the ongoing availability and performance of information systems.', 'SOC 2', '', '', NULL, 0, 'teest', '2025-12-20 20:46:03.350206'),
	(2, 125, 2, 'The entity maintains, monitors, and evaluates', 'The entity maintains, monitors, and evaluates the ongoing availability and performance of information systems.', 'SOC 2', 'Emma Jones', 'Annual', 'Document', 0, 'test', '2025-12-20 20:52:01.378532'),
	(3, 125, 3, 'The entity maintains, monitors, and evaluates', 'The entity maintains, monitors, and evaluates the ongoing availability and performance of information systems.', 'SOC 2', 'Emma Jones', 'Annual', 'Document', 0, 'Updated', '2025-12-20 21:06:25.912378'),
	(4, 126, 1, 'The entity authorizes, designs, develops', 'The entity authorizes, designs, develops, configures, documents, tests, approves, and implements changes to protect the availability of information systems.', 'SOC 2', '', '', NULL, 0, 'Updated', '2025-12-20 21:07:29.628514'),
	(5, 126, 2, 'The entity authorizes, designs, develops', 'The entity authorizes, designs, develops, configures, documents, tests, approves, and implements changes to protect the availability of information systems.', 'SOC 2', '', 'Annual', 'Document', 0, 'Updated', '2025-12-20 21:07:36.78381'),
	(6, 127, 1, 'The entity identifies, develops, and implements', 'The entity identifies, develops, and implements recovery and continuity strategies.', 'SOC 2', '', '', NULL, 0, 'Updated', '2025-12-22 18:40:08.163217'),
	(7, 111, 1, 'Prior to issuing system credentials', 'Prior to issuing system credentials, the entity registers and authorizes new internal and external users whose access is to be managed by the entity.', 'SOC 2', '', '', NULL, 0, 'Updated', '2025-12-31 23:07:29.782036'),
	(8, 102, 1, 'The board of directors demonstrates independence', 'The board of directors demonstrates independence from management and exercises oversight.', 'SOC 2', '', '', NULL, 0, 'Updated', '2026-01-02 16:40:16.060492'),
	(9, 29, 1, 'Monitoring, review and change management of supplier services', 'The organization shall regularly monitor, review, evaluate and manage change in supplier services.', 'ISO 27001', '', '', NULL, 0, 'Updated', '2026-01-11 22:54:13.153517'),
	(10, 8, 1, 'Policies for information security', 'Information security policy and topic-specific policies shall be defined, approved by management, published, communicated to and acknowledged by relevant personnel.', 'ISO 27001', '', '', NULL, 0, 'AI Generated Guidance', '2026-02-02 06:36:31.760084'),
	(11, 8, 2, 'Policies for information security', 'Information security policy and topic-specific policies shall be defined, approved by management, published, communicated to and acknowledged by relevant personnel.', 'ISO 27001', '', '', NULL, 0, 'AI Generated Guidance', '2026-02-02 06:39:45.443532'),
	(12, 17, 1, 'Acceptable use of information and other associated assets', 'Rules for the acceptable use and procedures for handling information and other associated assets shall be identified and documented.', 'ISO 27001', '', '', NULL, 0, 'AI Generated Guidance', '2026-02-02 06:46:33.447474'),
	(13, 28, 1, 'Managing information security in the ICT supply chain', 'Processes and procedures shall be defined to manage the information security risks associated with the ICT supply chain.', 'ISO 27001', '', '', NULL, 0, 'AI Generated Guidance', '2026-02-02 06:47:04.976202'),
	(14, 9, 1, 'Information security roles and responsibilities', 'Information security roles and responsibilities shall be defined and allocated according to the organization needs.', 'ISO 27001', '', '', NULL, 0, 'AI Generated Guidance', '2026-02-02 22:10:57.223565'),
	(15, 10, 1, 'Segregation of duties', 'Conflicting duties and conflicting areas of responsibility shall be segregated.', 'ISO 27001', '', '', NULL, 0, 'AI Generated Guidance', '2026-02-02 22:11:16.726345'),
	(16, 50, 1, 'Confidentiality or non-disclosure agreements', 'Confidentiality or non-disclosure agreements reflecting the organization''s needs shall be identified and signed.', 'ISO 27001', '', '', NULL, 0, 'AI Generated Guidance', '2026-02-15 21:08:02.366704'),
	(17, 1494, 5, 'Account Management', 'The organization identifies and selects the following types of information system accounts to support organizational missions/business functions: [Assignment: organization-defined information system account types]; assigns account managers for information system accounts; establishes conditions for group and role membership; specifies authorized users of the information system, group and role membership, and access authorizations (i.e., privileges) and other attributes (as required) for each account; requires approvals by [Assignment: organization-defined personnel or roles] for requests to create information system accounts; creates, enables, modifies, disables, and removes information system accounts in accordance with [Assignment: organization-defined procedures or conditions]; monitors the use of information system accounts; notifies account managers when accounts are no longer required, when users are terminated or transferred, and when individual information system usage or need-to-know changes; authorizes access to the information system based on a valid access authorization, intended system usage, and other attributes as required by the organization or associated mission/business functions; reviews accounts for compliance with account management requirements [Assignment: organization-defined frequency]; and establishes a process for reissuing shared/group account credentials (if deployed) when individuals are removed from the group.', 'NIST 800-53', NULL, 'Annual', 'Document', 0, 'Updated', '2026-03-06 13:45:01.374377'),
	(18, 1495, 5, 'Automated System Account Management', 'Support the management of system accounts using {{ insert: param, ac-02.01_odp }}.', 'NIST SP 800-53 Rev 5', NULL, NULL, NULL, 0, 'Updated', '2026-03-06 13:45:35.200801');
