INSERT INTO public.control_tech_mappings VALUES
	(1, 'A.5.1', 'ISO 27001:2022', 'policy-management-reciprocity', 'Reciprocity', 'ZenGRC', 'Governance, risk, and compliance platform with policy management, version control, and attestation workflows', '"[\"Built-in policy templates for ISO 27001, SOC 2, GDPR\",\"Automated policy review cycles and approvals\",\"Integration with ticketing systems\"]"', '"[\"Can be expensive for small teams\",\"Requires training for full utilization\"]"', 'medium', 'mature', '"[{\"url\":\"https://reciprocity.com/platform/policy-management/\",\"title\":\"Reciprocity Policy Management\"}]"', '2026-01-01 18:57:09.126172', '2026-01-01 18:57:09.126172'),
	(2, 'A.5.1', 'ISO 27001:2022', 'policy-management-drata', 'Drata', 'Compliance Automation Platform', 'Automates compliance monitoring with policy management and continuous evidence collection', '"[\"Easy onboarding\",\"Automated evidence collection\",\"Real-time compliance monitoring\"]"', '"[\"Limited customization for unique policies\",\"Premium pricing\"]"', 'low', 'mature', '"[{\"url\":\"https://drata.com/features/policy-management\",\"title\":\"Drata Policy Management\"}]"', '2026-01-01 18:57:09.969807', '2026-01-01 18:57:09.969807'),
	(3, 'A.8.1', 'ISO 27001:2022', 'asset-discovery-servicenow', 'ServiceNow', 'IT Asset Management (ITAM)', 'Enterprise asset management with auto-discovery, lifecycle tracking, and financial management', '"[\"Comprehensive asset tracking across hardware, software, cloud\",\"Strong integration ecosystem\",\"Scalable for large organizations\"]"', '"[\"High cost and complexity\",\"Steep learning curve\"]"', 'high', 'mature', '"[{\"url\":\"https://www.servicenow.com/products/it-asset-management.html\",\"title\":\"ServiceNow ITAM\"}]"', '2026-01-01 18:57:10.873398', '2026-01-01 18:57:10.873398'),
	(4, 'A.8.1', 'ISO 27001:2022', 'asset-discovery-snipeit', 'Open Source', 'Snipe-IT', 'Free, open-source IT asset management with barcode scanning, check-in/check-out, and custom fields', '"[\"Free and open-source\",\"Easy to deploy (Docker available)\",\"Active community support\"]"', '"[\"Manual setup required\",\"Limited auto-discovery vs commercial tools\"]"', 'low', 'mature', '"[{\"url\":\"https://snipeitapp.com/\",\"title\":\"Snipe-IT Homepage\"}]"', '2026-01-01 18:57:11.785643', '2026-01-01 18:57:11.785643'),
	(5, 'A.9.2', 'ISO 27001:2022', 'iam-okta', 'Okta', 'Okta Identity Cloud', 'Cloud-native IAM with SSO, MFA, and lifecycle management for 7000+ integrations', '"[\"Extensive app catalog (7000+ pre-built integrations)\",\"Strong MFA options (push, SMS, TOTP, WebAuthn)\",\"Excellent user experience\",\"Automated provisioning/deprovisioning\"]"', '"[\"Premium features require higher tiers\",\"Complex policy configuration for advanced use cases\"]"', 'medium', 'mature', '"[{\"url\":\"https://www.okta.com/resources/whitepaper/okta-iso-27001-guide/\",\"title\":\"Okta ISO 27001 Guide\"}]"', '2026-01-01 18:57:12.641346', '2026-01-01 18:57:12.641346'),
	(6, 'A.9.2', 'ISO 27001:2022', 'iam-azure-ad', 'Microsoft', 'Azure Active Directory / Entra ID', 'Cloud IAM with deep Microsoft 365 integration and conditional access policies', '"[\"Deep integration with M365 and Azure ecosystem\",\"Conditional access and risk-based authentication\",\"Included in many Microsoft licensing bundles\"]"', '"[\"Licensing complexity (P1/P2 features)\",\"Best for Microsoft-centric environments\"]"', 'low', 'mature', '"[{\"url\":\"https://learn.microsoft.com/en-us/azure/active-directory/\",\"title\":\"Azure AD Documentation\"}]"', '2026-01-01 18:57:13.544432', '2026-01-01 18:57:13.544432'),
	(7, 'A.9.2', 'ISO 27001:2022', 'iam-auth0', 'Auth0 (Okta)', 'Auth0 Identity Platform', 'Developer-friendly IAM with customizable login flows and extensive SDK support', '"[\"Easy integration for custom applications\",\"Flexible authentication flows\",\"Strong developer documentation\"]"', '"[\"Can get expensive with high MAU\",\"Enterprise features require higher plans\"]"', 'medium', 'mature', '"[{\"url\":\"https://auth0.com/docs/get-started/identity-fundamentals\",\"title\":\"Auth0 Documentation\"}]"', '2026-01-01 18:57:14.391988', '2026-01-01 18:57:14.391988'),
	(8, 'A.12.3', 'ISO 27001:2022', 'backup-veeam', 'Veeam', 'Veeam Backup & Replication', 'Enterprise backup solution for virtual, physical, and cloud workloads with immutable backups', '"[\"Supports wide range of platforms (VMware, Hyper-V, cloud)\",\"Immutable backup for ransomware protection\",\"Fast recovery with Instant VM Recovery\"]"', '"[\"Licensing costs can be high\",\"Requires dedicated infrastructure\"]"', 'medium', 'mature', '"[{\"url\":\"https://www.veeam.com/products/veeam-data-platform.html\",\"title\":\"Veeam Backup & Replication\"}]"', '2026-01-01 18:57:15.253015', '2026-01-01 18:57:15.253015'),
	(9, 'A.12.3', 'ISO 27001:2022', 'backup-aws-backup', 'AWS', 'AWS Backup', 'Centralized backup service for AWS resources with policy-based automation', '"[\"Native integration with AWS services\",\"Cross-region and cross-account backups\",\"Compliance-ready vault lock\"]"', '"[\"AWS-only (doesn''t backup on-prem or other clouds natively)\",\"Pricing can add up for large volumes\"]"', 'low', 'mature', '"[{\"url\":\"https://aws.amazon.com/backup/\",\"title\":\"AWS Backup\"}]"', '2026-01-01 18:57:16.231919', '2026-01-01 18:57:16.231919'),
	(10, 'A.14.2', 'ISO 27001:2022', 'devsecops-github-actions', 'GitHub', 'GitHub Advanced Security + Actions', 'Integrated CI/CD with code scanning, secret scanning, and dependency review', '"[\"Integrated into developer workflow\",\"Automated security scanning in pull requests\",\"Broad language support\"]"', '"[\"Requires GitHub Enterprise for private repos\",\"Can have false positives requiring tuning\"]"', 'low', 'mature', '"[{\"url\":\"https://docs.github.com/en/code-security\",\"title\":\"GitHub Advanced Security\"}]"', '2026-01-01 18:57:17.173119', '2026-01-01 18:57:17.173119'),
	(11, 'A.14.2', 'ISO 27001:2022', 'devsecops-snyk', 'Snyk', 'Snyk Security Platform', 'Developer-first security with vulnerability scanning for code, containers, IaC, and open-source dependencies', '"[\"Very developer-friendly UI and IDE integrations\",\"Excellent open-source vulnerability database\",\"Actionable fix recommendations\"]"', '"[\"Can be costly for large organizations\",\"May overwhelm teams with alerts initially\"]"', 'low', 'mature', '"[{\"url\":\"https://snyk.io/product/\",\"title\":\"Snyk Platform\"}]"', '2026-01-01 18:57:18.28944', '2026-01-01 18:57:18.28944'),
	(12, 'A.16.1', 'ISO 27001:2022', 'incident-pagerduty', 'PagerDuty', 'PagerDuty Incident Response', 'Incident response platform with on-call management, escalation, and postmortem workflows', '"[\"Excellent on-call scheduling and rotations\",\"Broad integration with monitoring tools\",\"Structured incident response workflows\"]"', '"[\"Can be expensive for large teams\",\"Requires process discipline to be effective\"]"', 'medium', 'mature', '"[{\"url\":\"https://www.pagerduty.com/platform/incident-response/\",\"title\":\"PagerDuty Incident Response\"}]"', '2026-01-01 18:57:19.183966', '2026-01-01 18:57:19.183966'),
	(13, 'A.16.1', 'ISO 27001:2022', 'incident-jira-service-desk', 'Atlassian', 'Jira Service Management', 'ITSM platform with incident management, problem tracking, and change management', '"[\"Integrates with Jira Software for development tracking\",\"Customizable workflows\",\"Strong reporting and analytics\"]"', '"[\"Can be complex to configure\",\"Performance issues with very large instances\"]"', 'medium', 'mature', '"[{\"url\":\"https://www.atlassian.com/software/jira/service-management\",\"title\":\"Jira Service Management\"}]"', '2026-01-01 18:57:20.133009', '2026-01-01 18:57:20.133009'),
	(14, 'A.17.1', 'ISO 27001:2022', 'dr-zerto', 'Zerto (HP)', 'Zerto Disaster Recovery', 'Continuous data protection and disaster recovery for VMs and cloud workloads', '"[\"Near-zero RPO with continuous replication\",\"Automated failover and failback\",\"Non-disruptive testing\"]"', '"[\"Enterprise pricing\",\"Complexity in multi-cloud scenarios\"]"', 'high', 'mature', '"[{\"url\":\"https://www.zerto.com/\",\"title\":\"Zerto Platform\"}]"', '2026-01-01 18:57:20.997285', '2026-01-01 18:57:20.997285'),
	(15, 'A.18.1', 'ISO 27001:2022', 'compliance-vanta', 'Vanta', 'Vanta Automation Platform', 'Automated compliance for SOC 2, ISO 27001, GDPR with continuous monitoring', '"[\"Fast time to certification\",\"Automates evidence collection\",\"User-friendly interface\"]"', '"[\"Can be expensive\",\"Less flexibility for custom frameworks\"]"', 'low', 'mature', '"[{\"url\":\"https://www.vanta.com/\",\"title\":\"Vanta Platform\"}]"', '2026-01-01 18:57:22.003552', '2026-01-01 18:57:22.003552'),
	(16, 'A.18.1', 'ISO 27001:2022', 'compliance-secureframe', 'Secureframe', 'Compliance Automation', 'Automated compliance platform with AI-powered evidence collection and streamlined auditor collaboration', '"[\"Strong auditor collaboration features\",\"Automated evidence collection from 100+ integrations\",\"Good customer support\"]"', '"[\"Premium pricing\",\"Limited customization for niche requirements\"]"', 'low', 'mature', '"[{\"url\":\"https://secureframe.com/\",\"title\":\"Secureframe Platform\"}]"', '2026-01-01 18:57:22.988975', '2026-01-01 18:57:22.988975');
INSERT INTO public.controls VALUES
	(2373, 'SA-19.4', 'Anti-counterfeit Scanning', '', 'NIST SP 800-53 Rev 5', NULL, NULL, NULL, 'active', 5, 'System and Services Acquisition', NULL, '2026-01-09 09:38:07.637309', '2026-01-09 09:38:07.637309', 'System and Services Acquisition', '', NULL, NULL, NULL, NULL, NULL),
	(2416, 'SC-7.17', 'Automated Enforcement of Protocol Formats', 'Enforce adherence to protocol formats.', 'NIST SP 800-53 Rev 5', NULL, NULL, NULL, 'active', 5, 'System and Communications Protection', NULL, '2026-01-09 09:38:07.760287', '2026-01-09 09:38:07.760287', 'System and Communications Protection', 'System components that enforce protocol formats include deep packet inspection firewalls and XML gateways. The components verify adherence to protocol formats and specifications at the application layer and identify vulnerabilities that cannot be detected by devices operating at the network or transport layers.', NULL, NULL, NULL, NULL, NULL),
	(3037, 'TEST-1769433005020', 'Test Control', NULL, 'Custom', NULL, NULL, NULL, 'draft', 1, NULL, NULL, '2026-01-26 13:10:07.306124', '2026-01-26 13:10:07.306124', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	(11, 'A.5.4', 'Management responsibilities', 'Management shall require all personnel to apply information security in accordance with the established policies and procedures.', 'ISO/IEC 27001:2022', '', '', NULL, 'active', 1, 'Organisational', 'Information Security Policy', '2025-12-19 06:15:26.563672', '2025-12-19 06:15:26.563672', 'Organisational', NULL, NULL, NULL, NULL, NULL, NULL),
	(3980, 'SAMM-EDUCATION-GUIDANCE', 'Education & Guidance', 'Security Practice: Education & Guidance under Governance', 'SAMM', NULL, NULL, NULL, 'active', 1, 'Governance', NULL, '2026-02-05 00:27:20.227158', '2026-02-05 00:27:20.227158', 'SAMM', 'See OWASP SAMM (Maturity Model) for details.', NULL, NULL, NULL, NULL, NULL),
	(12, 'A.5.5', 'Contact with authorities', 'The organization shall establish and maintain contact with relevant authorities.', 'ISO/IEC 27001:2022', '', '', NULL, 'active', 1, 'Organisational', 'Information Security Policy', '2025-12-19 06:15:26.784171', '2025-12-19 06:15:26.784171', 'Organisational', NULL, NULL, NULL, NULL, NULL, NULL),
	(3979, 'SAMM-POLICY-COMPLIANCE', 'Policy & Compliance', 'Security Practice: Policy & Compliance under Governance', 'SAMM', NULL, NULL, NULL, 'active', 1, 'Governance', NULL, '2026-02-05 00:27:20.011393', '2026-02-05 00:27:20.011393', 'SAMM', 'See OWASP SAMM (Maturity Model) for details.', NULL, NULL, NULL, NULL, NULL),
	(4391, 'SCVS-2.8', 'Risk Analysis', 'Verify that SBOM is analyzed for risk.', 'SCVS', NULL, 'Annual', 'Document', 'active', 1, 'V2: Software Bill of Materials (SBOM) Requirements', NULL, '2026-02-06 15:18:02.202258', '2026-02-06 15:18:02.202258', NULL, 'Implementation guidance for Risk Analysis based on OWASP Software Component Verification Standard v1.0.', NULL, NULL, NULL, NULL, NULL),
	(4393, 'SCVS-2.10', 'Test Components', 'Verify that SBOM contains an accurate inventory of all test components for the asset or application it describes.', 'SCVS', NULL, 'Annual', 'Document', 'active', 1, 'V2: Software Bill of Materials (SBOM) Requirements', NULL, '2026-02-06 15:18:02.701226', '2026-02-06 15:18:02.701226', NULL, 'Implementation guidance for Test Components based on OWASP Software Component Verification Standard v1.0.', NULL, NULL, NULL, NULL, NULL),
	(2695, '1.2.5', 'Verify that the application protects against OS command injection and that operating system calls use parameterized OS queries or use contextual command line output encoding.', 'Verify that the application protects against OS command injection and that operating system calls use parameterized OS queries or use contextual command line output encoding.', 'ASVS', NULL, NULL, NULL, 'active', 5, 'V1: Encoding and Sanitization', NULL, '2026-01-30 08:52:35.65', '2026-01-09 10:46:12.109604', 'V1.2: Injection Prevention', 'Applicable Levels: L1, L2, L3', NULL, NULL, NULL, NULL, NULL),
	(2696, '1.2.6', 'Verify that the application protects against LDAP injection vulnerabilities, or that specific security controls to prevent LDAP injection have been implemented.', 'Verify that the application protects against LDAP injection vulnerabilities, or that specific security controls to prevent LDAP injection have been implemented.', 'ASVS', NULL, NULL, NULL, 'active', 5, 'V1: Encoding and Sanitization', NULL, '2026-01-30 08:52:35.65', '2026-01-09 10:46:12.109604', 'V1.2: Injection Prevention', 'Applicable Levels: L2, L3', NULL, NULL, NULL, NULL, NULL),
	(2697, '1.2.7', 'Verify that the application is protected against XPath injection attacks by using query parameterization or precompiled queries.', 'Verify that the application is protected against XPath injection attacks by using query parameterization or precompiled queries.', 'ASVS', NULL, NULL, NULL, 'active', 5, 'V1: Encoding and Sanitization', NULL, '2026-01-30 08:52:35.65', '2026-01-09 10:46:12.109604', 'V1.2: Injection Prevention', 'Applicable Levels: L2, L3', NULL, NULL, NULL, NULL, NULL),
	(4394, 'SCVS-2.11', 'Asset Metadata', 'Verify that SBOM contains metadata about the asset or software the SBOM describes.', 'SCVS', NULL, 'Annual', 'Document', 'active', 1, 'V2: Software Bill of Materials (SBOM) Requirements', NULL, '2026-02-06 15:18:02.950476', '2026-02-06 15:18:02.950476', NULL, 'Implementation guidance for Asset Metadata based on OWASP Software Component Verification Standard v1.0.', NULL, NULL, NULL, NULL, NULL),
	(2698, '1.2.8', 'Verify that LaTeX processors are configured securely (such as not using the "--shell-escape" flag) and an allowlist of commands is used to prevent LaTeX injection attacks.', 'Verify that LaTeX processors are configured securely (such as not using the "--shell-escape" flag) and an allowlist of commands is used to prevent LaTeX injection attacks.', 'ASVS', NULL, NULL, NULL, 'active', 5, 'V1: Encoding and Sanitization', NULL, '2026-01-30 08:52:35.65', '2026-01-09 10:46:12.109604', 'V1.2: Injection Prevention', 'Applicable Levels: L2, L3', NULL, NULL, NULL, NULL, NULL),
	(4395, 'SCVS-2.12', 'Native Identifiers', 'Verify that component identifiers are derived from their native ecosystems (if applicable).', 'SCVS', NULL, 'Annual', 'Document', 'active', 1, 'V2: Software Bill of Materials (SBOM) Requirements', NULL, '2026-02-06 15:18:03.195598', '2026-02-06 15:18:03.195598', NULL, 'Implementation guidance for Native Identifiers based on OWASP Software Component Verification Standard v1.0.', NULL, NULL, NULL, NULL, NULL),
	(4396, 'SCVS-2.13', 'Origin Format', 'Verify that component point of origin is identified in a consistent, machine readable format (e.g. PURL).', 'SCVS', NULL, 'Annual', 'Document', 'active', 1, 'V2: Software Bill of Materials (SBOM) Requirements', NULL, '2026-02-06 15:18:03.441292', '2026-02-06 15:18:03.441292', NULL, 'Implementation guidance for Origin Format based on OWASP Software Component Verification Standard v1.0.', NULL, NULL, NULL, NULL, NULL),
	(2699, '1.2.9', 'Verify that the application escapes special characters in regular expressions (typically using a backslash) to prevent them from being misinterpreted as metacharacters.', 'Verify that the application escapes special characters in regular expressions (typically using a backslash) to prevent them from being misinterpreted as metacharacters.', 'ASVS', NULL, NULL, NULL, 'active', 5, 'V1: Encoding and Sanitization', NULL, '2026-01-30 08:52:35.65', '2026-01-09 10:46:12.109604', 'V1.2: Injection Prevention', 'Applicable Levels: L2, L3', NULL, NULL, NULL, NULL, NULL),
	(4397, 'SCVS-2.14', 'License Information', 'Verify that components defined in SBOM have accurate license information.', 'SCVS', NULL, 'Annual', 'Document', 'active', 1, 'V2: Software Bill of Materials (SBOM) Requirements', NULL, '2026-02-06 15:18:03.689159', '2026-02-06 15:18:03.689159', NULL, 'Implementation guidance for License Information based on OWASP Software Component Verification Standard v1.0.', NULL, NULL, NULL, NULL, NULL),
	(4399, 'SCVS-2.17', 'Modification Provenance', 'Verify that components defined in SBOM which have been modified from the original have detailed provenance and pedigree information.', 'SCVS', NULL, 'Annual', 'Document', 'active', 1, 'V2: Software Bill of Materials (SBOM) Requirements', NULL, '2026-02-06 15:18:04.181404', '2026-02-06 15:18:04.181404', NULL, 'Implementation guidance for Modification Provenance based on OWASP Software Component Verification Standard v1.0.', NULL, NULL, NULL, NULL, NULL),
	(4389, 'SCVS-2.7', 'Timestamping', 'Verify that SBOM is timestamped.', 'SCVS', NULL, 'Annual', 'Document', 'active', 1, 'V2: Software Bill of Materials (SBOM) Requirements', NULL, '2026-02-06 15:18:01.688619', '2026-02-06 15:18:01.688619', NULL, 'Implementation guidance for Timestamping based on OWASP Software Component Verification Standard v1.0.', NULL, NULL, NULL, NULL, NULL),
	(4392, 'SCVS-2.9', 'Complete Inventory', 'Verify that SBOM contains a complete and accurate inventory of all components the SBOM describes.', 'SCVS', NULL, 'Annual', 'Document', 'active', 1, 'V2: Software Bill of Materials (SBOM) Requirements', NULL, '2026-02-06 15:18:02.452895', '2026-02-06 15:18:02.452895', NULL, 'Implementation guidance for Complete Inventory based on OWASP Software Component Verification Standard v1.0.', NULL, NULL, NULL, NULL, NULL),
	(3983, 'SAMM-SECURITY-ARCHITECTURE', 'Security Architecture', 'Security Practice: Security Architecture under Design', 'SAMM', NULL, NULL, NULL, 'active', 1, 'Design', NULL, '2026-02-05 00:27:20.872335', '2026-02-05 00:27:20.872335', 'SAMM', 'See OWASP SAMM (Maturity Model) for details.', NULL, NULL, NULL, NULL, NULL),
	(3984, 'SAMM-SECURE-BUILD', 'Secure Build', 'Security Practice: Secure Build under Implementation', 'SAMM', NULL, NULL, NULL, 'active', 1, 'Implementation', NULL, '2026-02-05 00:27:21.090919', '2026-02-05 00:27:21.090919', 'SAMM', 'See OWASP SAMM (Maturity Model) for details.', NULL, NULL, NULL, NULL, NULL),
	(3985, 'SAMM-SECURE-DEPLOYMENT', 'Secure Deployment', 'Security Practice: Secure Deployment under Implementation', 'SAMM', NULL, NULL, NULL, 'active', 1, 'Implementation', NULL, '2026-02-05 00:27:21.306913', '2026-02-05 00:27:21.306913', 'SAMM', 'See OWASP SAMM (Maturity Model) for details.', NULL, NULL, NULL, NULL, NULL),
	(13, 'A.5.6', 'Contact with special interest groups', 'The organization shall establish and maintain contact with special interest groups or other specialist security forums.', 'ISO/IEC 27001:2022', '', '', NULL, 'active', 1, 'Organisational', 'Information Security Policy', '2025-12-19 06:15:26.991692', '2025-12-19 06:15:26.991692', 'Organisational', NULL, NULL, NULL, NULL, NULL, NULL),
	(3982, 'SAMM-SECURITY-REQUIREMENTS', 'Security Requirements', 'Security Practice: Security Requirements under Design', 'SAMM', NULL, NULL, NULL, 'active', 1, 'Design', NULL, '2026-02-05 00:27:20.657399', '2026-02-05 00:27:20.657399', 'SAMM', 'See OWASP SAMM (Maturity Model) for details.', NULL, NULL, NULL, NULL, NULL),
	(33, 'A.5.26', 'Response to information security incidents', 'Information security incidents shall be responded to in accordance with documented procedures.', 'ISO/IEC 27001:2022', '', '', NULL, 'active', 1, 'Organisational', 'Information Security Policy', '2025-12-19 06:15:31.197676', '2025-12-19 06:15:31.197676', 'Organisational', NULL, NULL, NULL, NULL, NULL, NULL),
	(34, 'A.5.27', 'Learning from information security incidents', 'Knowledge gained from information security incidents shall be used to strengthen and improve controls.', 'ISO/IEC 27001:2022', '', '', NULL, 'active', 1, 'Organisational', 'Information Security Policy', '2025-12-19 06:15:31.40368', '2025-12-19 06:15:31.40368', 'Organisational', NULL, NULL, NULL, NULL, NULL, NULL),
	(35, 'A.5.28', 'Collection of evidence', 'The organization shall establish procedures for the identification, collection, acquisition and preservation of evidence.', 'ISO/IEC 27001:2022', '', '', NULL, 'active', 1, 'Organisational', 'Information Security Policy', '2025-12-19 06:15:31.608167', '2025-12-19 06:15:31.608167', 'Organisational', NULL, NULL, NULL, NULL, NULL, NULL),
	(36, 'A.5.29', 'Information security during disruption', 'The organization shall plan how to maintain information security at an appropriate level during disruption.', 'ISO/IEC 27001:2022', '', '', NULL, 'active', 1, 'Organisational', 'Information Security Policy', '2025-12-19 06:15:31.819885', '2025-12-19 06:15:31.819885', 'Organisational', NULL, NULL, NULL, NULL, NULL, NULL),
	(37, 'A.5.30', 'ICT readiness for business continuity', 'ICT readiness shall be planned, implemented, maintained and tested based on business continuity objectives.', 'ISO/IEC 27001:2022', '', '', NULL, 'active', 1, 'Organisational', 'Information Security Policy', '2025-12-19 06:15:32.024231', '2025-12-19 06:15:32.024231', 'Organisational', NULL, NULL, NULL, NULL, NULL, NULL),
	(567, 'DE.AE-03', 'Adverse Event Analysis', 'Event data are collected and correlated from multiple sources and sensors.', 'NIST CSF 2.0', 'Unassigned', 'Annual', 'Document', 'active', 1, 'Detect', 'Incident Response Policy', '2025-12-20 09:07:31.20323', '2025-12-20 09:07:31.20323', 'Adverse Event Analysis', 'Ex1: Constantly transfer log data generated by other sources to a relatively small number of log servers
INSERT INTO public.controls VALUES
	(114, 'A1-005', 'The entity discontinues logical and physical protections', 'The entity discontinues logical and physical protections over physical assets only after the ability to read or recover data has been diminished.', 'SOC 2', '', '', NULL, 'active', 1, 'Logical and Physical Access', NULL, '2025-12-19 06:15:48.22242', '2025-12-19 06:15:48.22242', 'Logical and Physical Access', NULL, NULL, NULL, NULL, NULL, NULL),
	(115, 'A1-006', 'The entity implements logical access security', 'The entity implements logical access security measures to protect against unauthorized internal and external access.', 'SOC 2', '', '', NULL, 'active', 1, 'Logical and Physical Access', NULL, '2025-12-19 06:15:48.42843', '2025-12-19 06:15:48.42843', 'Logical and Physical Access', NULL, NULL, NULL, NULL, NULL, NULL),
	(116, 'A1-007', 'The entity restricts the transmission, movement', 'The entity restricts the transmission, movement, and removal of information.', 'SOC 2', '', '', NULL, 'active', 1, 'Logical and Physical Access', NULL, '2025-12-19 06:15:48.643933', '2025-12-19 06:15:48.643933', 'Logical and Physical Access', NULL, NULL, NULL, NULL, NULL, NULL),
	(117, 'SI-001', 'The entity obtains or generates, uses, and communicates', 'The entity obtains or generates, uses, and communicates relevant, quality information regarding the objectives and responsibilities of internal control.', 'SOC 2', '', '', NULL, 'active', 1, 'System Operations', NULL, '2025-12-19 06:15:48.849452', '2025-12-19 06:15:48.849452', 'System Operations', NULL, NULL, NULL, NULL, NULL, NULL),
	(118, 'SI-002', 'The entity implements policies and procedures', 'The entity implements policies and procedures over system inputs to ensure that all inputs are complete and accurate.', 'SOC 2', '', '', NULL, 'active', 1, 'System Operations', NULL, '2025-12-19 06:15:49.05695', '2025-12-19 06:15:49.05695', 'System Operations', NULL, NULL, NULL, NULL, NULL, NULL),
	(119, 'SI-003', 'The entity implements policies and procedures', 'The entity implements policies and procedures over system processing to ensure that all processing is complete and accurate.', 'SOC 2', '', '', NULL, 'active', 1, 'System Operations', NULL, '2025-12-19 06:15:49.262939', '2025-12-19 06:15:49.262939', 'System Operations', NULL, NULL, NULL, NULL, NULL, NULL),
	(120, 'SI-004', 'The entity implements policies and procedures', 'The entity implements policies and procedures over system outputs to ensure that all outputs are complete and accurate.', 'SOC 2', '', '', NULL, 'active', 1, 'System Operations', NULL, '2025-12-19 06:15:49.470983', '2025-12-19 06:15:49.470983', 'System Operations', NULL, NULL, NULL, NULL, NULL, NULL),
	(121, 'SI-005', 'The entity restricts the transmission, movement', 'The entity restricts the transmission, movement, and removal of information and implements logical access security measures.', 'SOC 2', '', '', NULL, 'active', 1, 'System Operations', NULL, '2025-12-19 06:15:49.679479', '2025-12-19 06:15:49.679479', 'System Operations', NULL, NULL, NULL, NULL, NULL, NULL),
	(122, 'CM-001', 'The entity authorizes, designs, develops', 'The entity authorizes, designs, develops, configures, documents, tests, approves, and implements changes.', 'SOC 2', '', '', NULL, 'active', 1, 'Change Management', NULL, '2025-12-19 06:15:49.892976', '2025-12-19 06:15:49.892976', 'Change Management', NULL, NULL, NULL, NULL, NULL, NULL),
	(123, 'RM-001', 'The entity identifies, analyzes, and responds', 'The entity identifies, analyzes, and responds to risks related to the potential for unauthorized internal and external access.', 'SOC 2', '', '', NULL, 'active', 1, 'Risk Mitigation', NULL, '2025-12-19 06:15:50.103002', '2025-12-19 06:15:50.103002', 'Risk Mitigation', NULL, NULL, NULL, NULL, NULL, NULL),
	(124, 'RM-002', 'The entity identifies, analyzes, and responds', 'The entity identifies, analyzes, and responds to risks associated with potential loss, unavailability, and recovery of information.', 'SOC 2', '', '', NULL, 'active', 1, 'Risk Mitigation', NULL, '2025-12-19 06:15:50.308993', '2025-12-19 06:15:50.308993', 'Risk Mitigation', NULL, NULL, NULL, NULL, NULL, NULL),
	(128, 'PI-001', 'The entity obtains or generates, uses, and communicates', 'The entity obtains or generates, uses, and communicates relevant, quality information regarding the objectives and responsibilities of internal control.', 'SOC 2', '', '', NULL, 'active', 1, 'Processing Integrity', NULL, '2025-12-19 06:15:51.138994', '2025-12-19 06:15:51.138994', 'Processing Integrity', NULL, NULL, NULL, NULL, NULL, NULL),
	(129, 'PI-002', 'The entity implements policies and procedures', 'The entity implements policies and procedures over system inputs to ensure that all inputs are complete and accurate.', 'SOC 2', '', '', NULL, 'active', 1, 'Processing Integrity', NULL, '2025-12-19 06:15:51.349588', '2025-12-19 06:15:51.349588', 'Processing Integrity', NULL, NULL, NULL, NULL, NULL, NULL),
	(130, 'PI-003', 'The entity implements policies and procedures', 'The entity implements policies and procedures over system processing to ensure that all processing is complete and accurate.', 'SOC 2', '', '', NULL, 'active', 1, 'Processing Integrity', NULL, '2025-12-19 06:15:51.558587', '2025-12-19 06:15:51.558587', 'Processing Integrity', NULL, NULL, NULL, NULL, NULL, NULL),
	(131, 'PI-004', 'The entity implements policies and procedures', 'The entity implements policies and procedures over system outputs to ensure that all outputs are complete and accurate.', 'SOC 2', '', '', NULL, 'active', 1, 'Processing Integrity', NULL, '2025-12-19 06:15:51.762489', '2025-12-19 06:15:51.762489', 'Processing Integrity', NULL, NULL, NULL, NULL, NULL, NULL),
	(132, 'PI-005', 'The entity restricts the transmission, movement', 'The entity restricts the transmission, movement, and removal of information and implements logical access security measures.', 'SOC 2', '', '', NULL, 'active', 1, 'Processing Integrity', NULL, '2025-12-19 06:15:51.967187', '2025-12-19 06:15:51.967187', 'Processing Integrity', NULL, NULL, NULL, NULL, NULL, NULL),
	(127, 'A-003', 'The entity identifies, develops, and implements', 'The entity identifies, develops, and implements recovery and continuity strategies.', 'SOC 2', '', 'Annual', 'Document', 'active', 2, 'Availability', NULL, '2025-12-19 06:15:50.932978', '2025-12-19 06:15:50.932978', 'Availability', '## Implementation Guidance for Control A-003
INSERT INTO public.controls VALUES
	(863, 'Req-9', 'Requirement 9: Restrict physical access to cardholder data', 'Restrict physical access to cardholder data. Physical security for onsite data and backups.', 'PCI DSS v4.0', NULL, NULL, NULL, 'active', 1, 'Implement Strong Access Control Measures', NULL, '2026-01-08 22:01:05.295742', '2026-01-08 22:01:05.295742', NULL, 'Refer to official PCI DSS v4.0 standard.', NULL, NULL, NULL, NULL, NULL),
	(864, 'Req-10', 'Requirement 10: Log and monitor all access to system components and cardholder data', 'Log and monitor all access to system components and cardholder data. Track and monitor all access to network resources and cardholder data.', 'PCI DSS v4.0', NULL, NULL, NULL, 'active', 1, 'Regularly Monitor and Test Networks', NULL, '2026-01-08 22:01:05.408741', '2026-01-08 22:01:05.408741', NULL, 'Refer to official PCI DSS v4.0 standard.', NULL, NULL, NULL, NULL, NULL),
	(865, 'Req-11', 'Requirement 11: Test the security of systems and networks regularly', 'Test the security of systems and networks regularly. Run vulnerability scans and penetration tests.', 'PCI DSS v4.0', NULL, NULL, NULL, 'active', 1, 'Regularly Monitor and Test Networks', NULL, '2026-01-08 22:01:05.524831', '2026-01-08 22:01:05.524831', NULL, 'Refer to official PCI DSS v4.0 standard.', NULL, NULL, NULL, NULL, NULL),
	(866, 'Req-12', 'Requirement 12: Support information security with organizational policies and programs', 'Support information security with organizational policies and programs. Maintain a policy that addresses information security for all personnel.', 'PCI DSS v4.0', NULL, NULL, NULL, 'active', 1, 'Maintain an Information Security Policy', NULL, '2026-01-08 22:01:05.638733', '2026-01-08 22:01:05.638733', NULL, 'Refer to official PCI DSS v4.0 standard.', NULL, NULL, NULL, NULL, NULL),
	(901, '2.2.7', '2.2.7 - All non-console administrative access is encrypted using strong cryptography.', 'All non-console administrative access is encrypted using strong cryptography.', 'PCI DSS v4.0', NULL, NULL, NULL, 'active', 1, 'Requirement 2', NULL, '2026-01-08 22:29:40.736335', '2026-01-08 22:29:40.736335', NULL, 'Refer to official PCI DSS v4.0 standard.', NULL, NULL, NULL, NULL, NULL),
	(902, '2.3', '2.3 - Wireless environments are configured and managed securely.', 'Wireless environments are configured and managed securely.', 'PCI DSS v4.0', NULL, NULL, NULL, 'active', 1, 'Requirement 2', NULL, '2026-01-08 22:29:40.845313', '2026-01-08 22:29:40.845313', NULL, 'Refer to official PCI DSS v4.0 standard.', NULL, NULL, NULL, NULL, NULL),
	(137, 'P-003', 'The entity obtains or generates, uses, and communicates', 'The entity obtains or generates, uses, and communicates relevant, quality information regarding the objectives and responsibilities of internal control.', 'SOC 2', '', '', NULL, 'active', 1, 'Privacy', NULL, '2025-12-19 06:15:53.004965', '2025-12-19 06:15:53.004965', 'Privacy', NULL, NULL, NULL, NULL, NULL, NULL),
	(138, 'P-004', 'The entity restricts access to personal information', 'The entity restricts access to personal information to authorized and authenticated users.', 'SOC 2', '', '', NULL, 'active', 1, 'Privacy', NULL, '2025-12-19 06:15:53.208493', '2025-12-19 06:15:53.208493', 'Privacy', NULL, NULL, NULL, NULL, NULL, NULL),
	(139, 'P-005', 'The entity secures personal information', 'The entity secures personal information to protect against unauthorized access.', 'SOC 2', '', '', NULL, 'active', 1, 'Privacy', NULL, '2025-12-19 06:15:53.414996', '2025-12-19 06:15:53.414996', 'Privacy', NULL, NULL, NULL, NULL, NULL, NULL),
	(140, 'P-006', 'The entity retains, disposes, and secures', 'The entity retains, disposes, and secures personal information to protect against unauthorized access.', 'SOC 2', '', '', NULL, 'active', 1, 'Privacy', NULL, '2025-12-19 06:15:53.622521', '2025-12-19 06:15:53.622521', 'Privacy', NULL, NULL, NULL, NULL, NULL, NULL),
	(141, 'P-007', 'The entity identifies and manages risks', 'The entity identifies and manages risks related to the collection, processing, and use of personal information.', 'SOC 2', '', '', NULL, 'active', 1, 'Privacy', NULL, '2025-12-19 06:15:53.826978', '2025-12-19 06:15:53.826978', 'Privacy', NULL, NULL, NULL, NULL, NULL, NULL),
	(142, 'P-008', 'The entity implements a process for receiving', 'The entity implements a process for receiving, addressing, resolving, and communicating the resolution of inquiries.', 'SOC 2', '', '', NULL, 'active', 1, 'Privacy', NULL, '2025-12-19 06:15:54.034012', '2025-12-19 06:15:54.034012', 'Privacy', NULL, NULL, NULL, NULL, NULL, NULL),
	(903, '2.3.1', '2.3.1 - For wireless environments connected to the CDE or transmitting account data, all...', 'For wireless environments connected to the CDE or transmitting account data, all wireless vendor defaults are changed at installation or are confirmed to be secure, including but not limited to:
