INSERT INTO public.disruptive_scenarios VALUES
	(73, 3, 'Ransomware Attack', 'Malicious encryption of production databases by external actor. Systems locked and ransom demanded.', 'High', 'Critical', 'Execute ''Crisis Communcation Protocol'' immediately. Then assess need for ''Active-Active Geo-Replication'' failover.', '2026-01-07 16:01:05.269002'),
	(74, 3, 'Data Center Fire (Primary)', 'Physical destruction of primary availability zone (us-east-1) due to fire or thermal event.', 'Low', 'Critical', 'Execute ''Crisis Communcation Protocol'' immediately. Then assess need for ''Active-Active Geo-Replication'' failover.', '2026-01-07 16:01:05.37852'),
	(75, 3, 'Extended Power Outage', 'Loss of grid power at HQ for > 48 hours. Backup generators fail or run out of fuel.', 'Medium', 'High', 'Execute ''Crisis Communcation Protocol'' immediately. Then assess need for ''Active-Active Geo-Replication'' failover.', '2026-01-07 16:01:05.486054'),
	(76, 3, 'Key Vendor Bankruptcy (Cloud)', 'Sudden cessation of services by critical SaaS provider (e.g., Auth0 or Stripe). No notice given.', 'Low', 'Critical', 'Execute ''Crisis Communcation Protocol'' immediately. Then assess need for ''Active-Active Geo-Replication'' failover.', '2026-01-07 16:01:05.60228'),
	(77, 3, 'Mass Resignation / Strike', 'Walkout by >50% of Customer Support staff due to labor dispute. Capacity severely reduced.', 'Low', 'High', 'Execute ''Crisis Communcation Protocol'' immediately. Then assess need for ''Active-Active Geo-Replication'' failover.', '2026-01-07 16:01:05.71003'),
	(78, 3, 'Global Pandemic / Lockdown', 'Government mandate restricting access to physical offices. 100% remote work required immediately.', 'Low', 'Medium', 'Execute ''Crisis Communcation Protocol'' immediately. Then assess need for ''Active-Active Geo-Replication'' failover.', '2026-01-07 16:01:05.818017'),
	(79, 3, 'Supply Chain Compromise', 'Malicious code injected into a core library dependency (e.g., Log4j style event).', 'Medium', 'Critical', 'Execute ''Crisis Communcation Protocol'' immediately. Then assess need for ''Active-Active Geo-Replication'' failover.', '2026-01-07 16:01:05.927979'),
	(80, 3, 'DDoS Attack', 'Volumetric attack exceeding 100Gbps targeting public API endpoints, rendering them inaccessible.', 'High', 'High', 'Execute ''Crisis Communcation Protocol'' immediately. Then assess need for ''Active-Active Geo-Replication'' failover.', '2026-01-07 16:01:06.038524'),
	(81, 3, 'Insider Threat / Leak', 'Disgruntled employee leaks sensitive customer database to dark web. Reputational crisis.', 'Medium', 'High', 'Execute ''Crisis Communcation Protocol'' immediately. Then assess need for ''Active-Active Geo-Replication'' failover.', '2026-01-07 16:01:06.154762'),
