INSERT INTO public.email_messages VALUES
	(1, 1, 1, 'inbox', 'sent', 'Urgent: SOC 2 Audit Documentation Required', '<p>Hi Team,</p><p>We are missing the evidence for control <strong>CC6.1</strong> (Logical Access). Please upload the user access review logs for Q3.</p><p>Thanks,<br>John Auditor</p>', 'We are missing the evidence for control CC6.1...', 'auditor@securetrust.com', '"[\"me@company.com\"]"', NULL, NULL, false, false, NULL, '2025-12-27 21:58:50.892', '2025-12-27 21:58:50.892', '2025-12-27 21:58:50.892'),
	(2, 1, 1, 'inbox', 'sent', 'New Vendor Onboarding: Acme Corp', '<p>Hello,</p><p>Acme Corp has been added as a new vendor. Please review their security questionnaire and assign a risk tier.</p><p><a href=''#''>View Vendor Details</a></p>', 'Acme Corp has been added as a new vendor. Please review...', 'procurement@company.com', '"[\"me@company.com\"]"', NULL, NULL, true, false, NULL, '2025-12-26 21:58:51.635', '2025-12-26 21:58:51.635', '2025-12-26 21:58:51.635'),
	(3, 1, 1, 'inbox', 'sent', 'Quote for Penetration Testing Services', '<p>Hi,</p><p>Attached is the quote for the upcoming annual pentest. Let me know if you have any questions about the scope.</p><p>Best,<br>Sarah</p>', 'Attached is the quote for the upcoming annual pentest...', 'sales@pentest-experts.io', '"[\"me@company.com\"]"', NULL, NULL, true, false, NULL, '2025-12-25 21:58:51.746', '2025-12-25 21:58:51.746', '2025-12-25 21:58:51.746'),
	(4, 1, 1, 'inbox', 'sent', 'Policy Review Reminder: Acceptable Use Policy', '<p>This is an automated reminder that the <strong>Acceptable Use Policy</strong> is due for review in 5 days.</p>', 'This is an automated reminder that the AUP is due for review...', 'system@compliance-os.com', '"[\"me@company.com\"]"', NULL, NULL, false, false, NULL, '2025-12-27 21:58:51.863', '2025-12-27 21:58:51.863', '2025-12-27 21:58:51.863'),
	(5, 1, 1, 'inbox', 'sent', 'Invitation: Security Steering Committee', '<p>Team,</p><p>Please join us for the quarterly security steering committee meeting on Friday.</p><p>Agenda attached.</p>', 'Please join us for the quarterly security steering committee...', 'ciso@company.com', '"[\"me@company.com\"]"', NULL, NULL, true, false, NULL, '2025-12-24 21:58:51.977', '2025-12-24 21:58:51.977', '2025-12-24 21:58:51.977'),
	(6, 1, 1, 'inbox', 'sent', 'GDPR Data Subject Access Request (DSAR)', '<p>We have received a DSAR from customer ID 99281. Please compile all personal data related to this user within 30 days.</p>', 'We have received a DSAR from customer ID 99281...', 'legal@company.com', '"[\"me@company.com\"]"', NULL, NULL, false, false, NULL, '2025-12-27 21:58:52.09', '2025-12-27 21:58:52.09', '2025-12-27 21:58:52.09'),
	(7, 1, 1, 'inbox', 'sent', 'Update: Cloud Infrastructure Vulnerabilities', '<p>The latest scan detected <strong>3 high severity vulnerabilities</strong> in the production AWS account. Remediation is required immediately.</p>', 'The latest scan detected 3 high severity vulnerabilities...', 'security-ops@company.com', '"[\"me@company.com\"]"', NULL, NULL, true, false, NULL, '2025-12-23 21:58:52.209', '2025-12-23 21:58:52.209', '2025-12-23 21:58:52.209'),
	(8, 1, 1, 'inbox', 'sent', 'Contract Renewal: CloudProvider Inc', '<p>The contract with CloudProvider Inc expires next month. Do we need to renegotiate terms based on the new compliance requirements?</p>', 'The contract with CloudProvider Inc expires next month...', 'finance@company.com', '"[\"me@company.com\"]"', NULL, NULL, true, true, NULL, '2025-12-22 21:58:52.321', '2025-12-22 21:58:52.321', '2025-12-22 21:58:52.321'),
	(9, 1, 1, 'inbox', 'sent', 'Welcome to ComplianceOS!', '<p>Welcome aboard! Here are some resources to get you started with your compliance journey.</p>', 'Welcome aboard! Here are some resources to get you started...', 'hello@compliance-os.com', '"[\"me@company.com\"]"', NULL, NULL, true, false, NULL, '2025-12-17 21:58:52.433', '2025-12-17 21:58:52.433', '2025-12-17 21:58:52.433'),
