	(14, 3, 1, 'inbox', 'sent', 'Policy Review Reminder: Acceptable Use Policy', '<p>This is an automated reminder that the <strong>Acceptable Use Policy</strong> is due for review in 5 days.</p>', 'This is an automated reminder that the AUP is due for review...', 'system@compliance-os.com', '"[\"me@company.com\"]"', NULL, NULL, false, false, NULL, '2025-12-27 22:09:38.203', '2025-12-27 22:09:38.203', '2025-12-27 22:09:38.203'),
