	(16, 3, 1, 'inbox', 'sent', 'GDPR Data Subject Access Request (DSAR)', '<p>We have received a DSAR from customer ID 99281. Please compile all personal data related to this user within 30 days.</p>', 'We have received a DSAR from customer ID 99281...', 'legal@company.com', '"[\"me@company.com\"]"', NULL, NULL, false, true, NULL, '2025-12-27 22:09:38.42', '2025-12-27 22:09:38.42', '2025-12-27 22:09:38.42'),
	(17, 3, 1, 'inbox', 'sent', 'Update: Cloud Infrastructure Vulnerabilities', '<p>The latest scan detected <strong>3 high severity vulnerabilities</strong> in the production AWS account. Remediation is required immediately.</p>', 'The latest scan detected 3 high severity vulnerabilities...', 'security-ops@company.com', '"[\"me@company.com\"]"', NULL, NULL, true, false, NULL, '2025-12-23 22:09:38.534', '2025-12-23 22:09:38.534', '2025-12-23 22:09:38.534'),
	(18, 3, 1, 'inbox', 'sent', 'Contract Renewal: CloudProvider Inc', '<p>The contract with CloudProvider Inc expires next month. Do we need to renegotiate terms based on the new compliance requirements?</p>', 'The contract with CloudProvider Inc expires next month...', 'finance@company.com', '"[\"me@company.com\"]"', NULL, NULL, true, false, NULL, '2025-12-22 22:09:38.644', '2025-12-22 22:09:38.644', '2025-12-22 22:09:38.644'),
	(19, 3, 1, 'inbox', 'sent', 'Welcome to ComplianceOS!', '<p>Welcome aboard! Here are some resources to get you started with your compliance journey.</p>', 'Welcome aboard! Here are some resources to get you started...', 'hello@compliance-os.com', '"[\"me@company.com\"]"', NULL, NULL, true, true, NULL, '2025-12-17 22:09:38.754', '2025-12-17 22:09:38.754', '2025-12-17 22:09:38.754'),
	(20, 3, 1, 'inbox', 'sent', 'Weekly Security Digest', '<p><strong>Weekly Summary</strong></p><ul><li>New Risks: 0</li><li>Open Gaps: 12</li><li>Overdue Tasks: 2</li></ul>', 'Here is your weekly summary of security events...', 'system@compliance-os.com', '"[\"me@company.com\"]"', NULL, NULL, true, true, NULL, '2025-12-20 22:09:38.862', '2025-12-20 22:09:38.862', '2025-12-20 22:09:38.862'),
