INSERT INTO public.framework_requirements VALUES
	(320, 1, 1, 'ISO-P1', 'Define ISMS Scope', 'Establish the boundaries and applicability of the Information Security Management System.', NULL, NULL, '2026-01-25 13:10:52.797745', '2026-01-25 13:10:52.797745'),
	(321, 1, 1, 'ISO-P2', 'Develop ISMS Policy', 'Create the core Information Security Policy endorsed by leadership.', NULL, NULL, '2026-01-25 13:10:53.022744', '2026-01-25 13:10:53.022744'),
	(322, 1, 1, 'ISO-P3', 'Risk Assessment Methodology', 'Define how to identify and evaluate security risks.', NULL, NULL, '2026-01-25 13:10:53.234812', '2026-01-25 13:10:53.234812'),
	(323, 1, 1, 'ISO-P4', 'Asset Inventory', 'Identify and document all critical information assets.', NULL, NULL, '2026-01-25 13:10:53.475685', '2026-01-25 13:10:53.475685'),
	(324, 1, 1, 'ISO-P5', 'Legal & Regulatory Requirements', 'Identify laws and regulations applicable to information security.', NULL, NULL, '2026-01-25 13:10:53.701237', '2026-01-25 13:10:53.701237'),
	(325, 1, 1, 'ISO-P6', 'Statement of Applicability (SoA)', 'Identify controls applicable to your organization.', NULL, NULL, '2026-01-25 13:10:53.912281', '2026-01-25 13:10:53.912281'),
	(326, 1, 2, 'ISO-D1', 'Implement Risk Treatment', 'Deploy controls defined in the Risk Treatment Plan.', NULL, NULL, '2026-01-25 13:10:54.232275', '2026-01-25 13:10:54.232275'),
	(327, 1, 2, 'ISO-D2', 'Security Awareness Training', 'Ensure all personnel understand their security responsibilities.', NULL, NULL, '2026-01-25 13:10:54.445244', '2026-01-25 13:10:54.445244'),
	(328, 1, 2, 'ISO-D3', 'Access Control Management', 'Enforce logical and physical access restrictions.', NULL, NULL, '2026-01-25 13:10:54.675833', '2026-01-25 13:10:54.675833'),
	(329, 1, 2, 'ISO-D4', 'Incident Response Setup', 'Establish procedures to identify and respond to security events.', NULL, NULL, '2026-01-25 13:10:54.885756', '2026-01-25 13:10:54.885756'),
	(330, 1, 2, 'ISO-D5', 'Encryption & Key Management', 'Implement cryptographic controls for data at rest and in transit.', NULL, NULL, '2026-01-25 13:10:55.099716', '2026-01-25 13:10:55.099716'),
	(331, 1, 2, 'ISO-D6', 'Business Continuity Planning', 'Establish procedures to maintain operations during disruptions.', NULL, NULL, '2026-01-25 13:10:55.33983', '2026-01-25 13:10:55.33983'),
	(332, 1, 2, 'ISO-D7', 'Physical Security Controls', 'Secure physical premises and sensitive information areas.', NULL, NULL, '2026-01-25 13:10:55.581757', '2026-01-25 13:10:55.581757'),
	(333, 1, 2, 'ISO-D8', 'Supplier Security Management', 'Ensure third-party vendors meet security standards.', NULL, NULL, '2026-01-25 13:10:55.804767', '2026-01-25 13:10:55.804767'),
	(334, 1, 3, 'ISO-C1', 'Internal Audit Program', 'Perform objective internal reviews of the ISMS.', NULL, NULL, '2026-01-25 13:10:56.143989', '2026-01-25 13:10:56.143989'),
	(335, 1, 3, 'ISO-C2', 'Management Review', 'Review ISMS performance with senior leadership.', NULL, NULL, '2026-01-25 13:10:56.36578', '2026-01-25 13:10:56.36578'),
	(336, 1, 3, 'ISO-C3', 'Control Effectiveness Testing', 'Verify that implemented controls are working as intended.', NULL, NULL, '2026-01-25 13:10:56.574543', '2026-01-25 13:10:56.574543'),
	(337, 1, 4, 'ISO-A1', 'Non-conformity Management', 'React to audit findings and implement corrective actions.', NULL, NULL, '2026-01-25 13:10:57.138919', '2026-01-25 13:10:57.138919'),
	(338, 1, 4, 'ISO-A2', 'Root Cause Analysis', 'Identify why failures occurred to prevent recurrence.', NULL, NULL, '2026-01-25 13:10:57.357321', '2026-01-25 13:10:57.357321'),
	(339, 1, 4, 'ISO-A3', 'Continual Improvement', 'Regularly update the ISMS to address new threats and changes.', NULL, NULL, '2026-01-25 13:10:57.579281', '2026-01-25 13:10:57.579281'),
	(340, 1, 4, 'ISO-A4', 'Corrective Action Tracking', 'Maintain a log of all security improvements and their status.', NULL, NULL, '2026-01-25 13:10:57.812778', '2026-01-25 13:10:57.812778'),
	(341, 2, 41, 'SOC2-P2', 'System Description Drafting', 'Documenting the boundaries and components of the service system.', NULL, NULL, '2026-01-25 13:10:58.507334', '2026-01-25 13:10:58.507334'),
	(342, 2, 41, 'SOC2-P3', 'Control Activity Mapping', 'Linking existing controls to SOC 2 trust principles.', NULL, NULL, '2026-01-25 13:10:58.739826', '2026-01-25 13:10:58.739826'),
	(343, 2, 42, 'SOC2-R1', 'TSC Control Alignment', 'Mapping organization controls to SOC 2 Trust Services Criteria.', NULL, NULL, '2026-01-25 13:10:59.211849', '2026-01-25 13:10:59.211849'),
	(344, 2, 42, 'SOC2-R2', 'Policy Formalization', 'Updating policies to meet SOC 2 specific requirements.', NULL, NULL, '2026-01-25 13:10:59.423787', '2026-01-25 13:10:59.423787'),
