INSERT INTO public.framework_requirements VALUES
	(1260, 15, 118, 'SCVS-4.9', 'User Notification', 'Verify that package repository notifies users of security issues.', 'Implementation guidance for User Notification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:41.972078', '2026-02-06 15:17:41.972078'),
	(1261, 15, 118, 'SCVS-4.10', 'Version Correlation', 'Verify that package repository provides a verifiable way of correlating component versions to specific source codes in version control.', 'Implementation guidance for Version Correlation based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:42.186832', '2026-02-06 15:17:42.186832'),
	(1262, 15, 118, 'SCVS-4.11', 'Update Auditability', 'Verify that package repository provides auditability when components are updated.', 'Implementation guidance for Update Auditability based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:42.402593', '2026-02-06 15:17:42.402593'),
	(1263, 15, 118, 'SCVS-4.12', 'Code Signing', 'Verify that package repository requires code signing to publish packages to production repositories.', 'Implementation guidance for Code Signing based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:42.618999', '2026-02-06 15:17:42.618999'),
	(1264, 15, 118, 'SCVS-4.13', 'Remote Integrity Verification', 'Verify that package manager verifies the integrity of packages when they are retrieved from remote repository.', 'Implementation guidance for Remote Integrity Verification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:42.835081', '2026-02-06 15:17:42.835081'),
	(1265, 15, 118, 'SCVS-4.14', 'Local Integrity Verification', 'Verify that package manager verifies the integrity of packages when they are retrieved from file system.', 'Implementation guidance for Local Integrity Verification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:43.049555', '2026-02-06 15:17:43.049555'),
	(1266, 15, 118, 'SCVS-4.15', 'TLS Enforcement', 'Verify that package repository enforces use of TLS for all interactions.', 'Implementation guidance for TLS Enforcement based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:43.26467', '2026-02-06 15:17:43.26467'),
	(1158, 15, 115, 'SCVS-1.1', 'Build Component Inventory', 'Verify that all direct and transitive components and their versions are known at completion of a build.', 'Implementation guidance for Security Requirements based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 09:50:16.785005', '2026-02-06 09:50:16.785005'),
	(1225, 15, 116, 'SCVS-2.7', 'Timestamping', 'Verify that SBOM is timestamped.', 'Implementation guidance for Timestamping based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:32.802522', '2026-02-06 15:17:32.802522'),
	(1227, 15, 116, 'SCVS-2.9', 'Complete Inventory', 'Verify that SBOM contains a complete and accurate inventory of all components the SBOM describes.', 'Implementation guidance for Complete Inventory based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:33.240378', '2026-02-06 15:17:33.240378'),
	(1242, 15, 117, 'SCVS-3.9', 'Trust Store Integrity', 'Verify that application build pipeline prohibits alteration of certificate trust stores.', 'Implementation guidance for Trust Store Integrity based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:37.297105', '2026-02-06 15:17:37.297105'),
	(1267, 15, 118, 'SCVS-4.16', 'TLS Validation', 'Verify that package manager validates TLS certificate chain to repository and fails securely when validation fails.', 'Implementation guidance for TLS Validation based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:43.481985', '2026-02-06 15:17:43.481985'),
	(1268, 15, 118, 'SCVS-4.17', 'Static Analysis', 'Verify that package repository requires and/or performs static code analysis prior to publishing a component and makes results available for others to consume.', 'Implementation guidance for Static Analysis based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:43.696543', '2026-02-06 15:17:43.696543'),
	(1269, 15, 118, 'SCVS-4.18', 'No Execution', 'Verify that package manager does not execute component code.', 'Implementation guidance for No Execution based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:43.914896', '2026-02-06 15:17:43.914896'),
	(1270, 15, 118, 'SCVS-4.19', 'Installation Documentation', 'Verify that package manager documents package installation in machine-readable form.', 'Implementation guidance for Installation Documentation based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:44.132085', '2026-02-06 15:17:44.132085'),
	(1271, 15, 119, 'SCVS-5.4', 'Vulnerability Identification', 'Verify that an automated process of identifying all publicly disclosed vulnerabilities in third-party and open source components is used.', 'Implementation guidance for Vulnerability Identification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:45.110571', '2026-02-06 15:17:45.110571'),
	(1272, 15, 119, 'SCVS-5.5', 'Exploitability Identification', 'Verify that an automated process of identifying confirmed dataflow exploitability is used.', 'Implementation guidance for Exploitability Identification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:45.329803', '2026-02-06 15:17:45.329803'),
	(1273, 15, 119, 'SCVS-5.6', 'Version Identification', 'Verify that an automated process of identifying non-specified component versions is used.', 'Implementation guidance for Version Identification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:45.544792', '2026-02-06 15:17:45.544792'),
	(1274, 15, 119, 'SCVS-5.7', 'Outdated Component Identification', 'Verify that an automated process of identifying out-of-date components is used.', 'Implementation guidance for Outdated Component Identification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:45.761615', '2026-02-06 15:17:45.761615'),
	(1275, 15, 119, 'SCVS-5.8', 'EOL Identification', 'Verify that an automated process of identifying end-of-life / end-of-support components is used.', 'Implementation guidance for EOL Identification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:45.976869', '2026-02-06 15:17:45.976869'),
	(1276, 15, 119, 'SCVS-5.9', 'Type Identification', 'Verify that an automated process of identifying component type is used.', 'Implementation guidance for Type Identification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:46.193103', '2026-02-06 15:17:46.193103'),
	(1277, 15, 119, 'SCVS-5.10', 'Function Identification', 'Verify that an automated process of identifying component function is used.', 'Implementation guidance for Function Identification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:46.416786', '2026-02-06 15:17:46.416786'),
	(1278, 15, 119, 'SCVS-5.11', 'Quantity Identification', 'Verify that an automated process of identifying component quantity is used.', 'Implementation guidance for Quantity Identification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:46.633575', '2026-02-06 15:17:46.633575'),
	(1279, 15, 119, 'SCVS-5.12', 'License Identification', 'Verify that an automated process of identifying component license is used.', 'Implementation guidance for License Identification based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:46.849167', '2026-02-06 15:17:46.849167'),
	(1280, 15, 120, 'SCVS-6.4', 'Pedigree Documentation', 'Verify that pedigree of component modification is documented and verifiable.', 'Implementation guidance for Pedigree Documentation based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:47.816402', '2026-02-06 15:17:47.816402'),
	(1281, 15, 120, 'SCVS-6.5', 'Unique Modification ID', 'Verify that modified components are uniquely identified and distinct from origin component.', 'Implementation guidance for Unique Modification ID based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:48.032117', '2026-02-06 15:17:48.032117'),
	(1282, 15, 120, 'SCVS-6.6', 'Modification Analysis', 'Verify that modified components are analyzed with the same level of precision as unmodified components.', 'Implementation guidance for Modification Analysis based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:48.253706', '2026-02-06 15:17:48.253706'),
	(1283, 15, 120, 'SCVS-6.7', 'Unique Risk Analysis', 'Verify that risk unique to modified components can be analyzed and associated specifically to modified variant.', 'Implementation guidance for Unique Risk Analysis based on OWASP Software Component Verification Standard v1.0.', NULL, '2026-02-06 15:17:48.471268', '2026-02-06 15:17:48.471268'),
	(1286, 19, 138, 'OSPS-BAS-03', 'FLOSS License', 'Verify that the software is released as FLOSS (Free/Libre and Open Source Software) with an OSI-approved license.', 'Implementation guidance for FLOSS License based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:30.894576', '2026-02-06 15:34:30.894576'),
	(1287, 19, 138, 'OSPS-BAS-04', 'Documentation', 'Verify that the project provides basic documentation on how to install and use the software.', 'Implementation guidance for Documentation based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:31.13606', '2026-02-06 15:34:31.13606'),
	(1288, 19, 138, 'OSPS-BAS-05', 'Secure Sites (HTTPS)', 'Verify that the project sites (website, repository, download URLs) support HTTPS using TLS.', 'Implementation guidance for Secure Sites (HTTPS) based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:31.380493', '2026-02-06 15:34:31.380493'),
	(1285, 19, 138, 'OSPS-BAS-02', 'Contribution Information', 'Verify that the project provides clear information on how to contribute and the contribution process.', 'Implementation guidance for Contribution Information based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:30.65106', '2026-02-06 15:34:30.65106'),
	(1292, 19, 139, 'OSPS-CC-03', 'Semantic Versioning', 'Verify that the project uses a standard version numbering format (e.g., Semantic Versioning or CalVer).', 'Implementation guidance for Semantic Versioning based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:32.474602', '2026-02-06 15:34:32.474602'),
	(1293, 19, 139, 'OSPS-CC-04', 'Release Tags', 'Verify that each release is identified within the version control system (e.g., using git tags).', 'Implementation guidance for Release Tags based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:32.715269', '2026-02-06 15:34:32.715269'),
	(1294, 19, 139, 'OSPS-CC-05', 'Release Notes', 'Verify that release notes are provided for each release, summarizing major changes.', 'Implementation guidance for Release Notes based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:32.954551', '2026-02-06 15:34:32.954551'),
	(1295, 19, 139, 'OSPS-CC-06', 'Vulnerability Identification', 'Verify that release notes identify any fixed vulnerabilities.', 'Implementation guidance for Vulnerability Identification based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:33.194727', '2026-02-06 15:34:33.194727'),
	(1296, 19, 140, 'OSPS-REP-01', 'Bug Reporting Process', 'Verify that the project provides a process for users to submit bug reports.', 'Implementation guidance for Bug Reporting Process based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:33.556652', '2026-02-06 15:34:33.556652'),
	(1297, 19, 140, 'OSPS-REP-02', 'Issue Tracker', 'Verify that the project uses an issue tracker to track individual issues.', 'Implementation guidance for Issue Tracker based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:33.801625', '2026-02-06 15:34:33.801625'),
	(1298, 19, 140, 'OSPS-REP-03', 'Bug Response', 'Verify that the project acknowledges a majority of bug reports submitted in the last 2-12 months.', 'Implementation guidance for Bug Response based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:34.048636', '2026-02-06 15:34:34.048636'),
	(1299, 19, 140, 'OSPS-REP-04', 'Vulnerability Reporting', 'Verify that the project has a documented process for reporting security vulnerabilities.', 'Implementation guidance for Vulnerability Reporting based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:34.296653', '2026-02-06 15:34:34.296653'),
	(1300, 19, 140, 'OSPS-REP-05', 'Private Vulnerability Reporting', 'Verify that the vulnerability reporting process supports private reports (e.g., via email or encrypted channel).', 'Implementation guidance for Private Vulnerability Reporting based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:34.537563', '2026-02-06 15:34:34.537563'),
	(1301, 19, 140, 'OSPS-REP-06', 'Vulnerability Response SLA', 'Verify that the project responds to vulnerability reports within 14 days.', 'Implementation guidance for Vulnerability Response SLA based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:34.778602', '2026-02-06 15:34:34.778602'),
	(1302, 19, 141, 'OSPS-QUAL-01', 'Working Build', 'Verify that the project can be built using standard tools.', 'Implementation guidance for Working Build based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:35.169163', '2026-02-06 15:34:35.169163'),
	(1303, 19, 141, 'OSPS-QUAL-02', 'Automated Test Suite', 'Verify that the project has an automated test suite.', 'Implementation guidance for Automated Test Suite based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:35.412708', '2026-02-06 15:34:35.412708'),
	(1304, 19, 141, 'OSPS-QUAL-03', 'New Test Policy', 'Verify that new features or bug fixes typically include new tests.', 'Implementation guidance for New Test Policy based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:35.652629', '2026-02-06 15:34:35.652629'),
	(1305, 19, 141, 'OSPS-QUAL-04', 'Warning Flags', 'Verify that compiler/linter warning flags are enabled and addressed.', 'Implementation guidance for Warning Flags based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:35.894761', '2026-02-06 15:34:35.894761'),
	(1306, 19, 141, 'OSPS-QUAL-05', 'Test Invocation', 'Verify that there is a standard way to run the tests (e.g., ''npm test'', ''make test'').', 'Implementation guidance for Test Invocation based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:36.141225', '2026-02-06 15:34:36.141225'),
	(1307, 19, 142, 'OSPS-SEC-01', 'Secure Development Knowledge', 'Verify that at least one primary developer knows how to design secure software.', 'Implementation guidance for Secure Development Knowledge based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:36.50718', '2026-02-06 15:34:36.50718'),
	(1308, 19, 142, 'OSPS-SEC-02', 'Good Cryptography', 'Verify that if the project uses cryptography, it uses standard, publicly vetted algorithms and protocols.', 'Implementation guidance for Good Cryptography based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:36.747236', '2026-02-06 15:34:36.747236'),
	(1309, 19, 142, 'OSPS-SEC-03', 'No Leaked Secrets', 'Verify that the repository does not contain leaked private credentials or secrets.', 'Implementation guidance for No Leaked Secrets based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:36.986767', '2026-02-06 15:34:36.986767'),
	(1310, 19, 142, 'OSPS-SEC-04', 'No Broken Algorithms', 'Verify that the project avoids using known broken or weak cryptographic algorithms (e.g., MD5, SHA1 for security).', 'Implementation guidance for No Broken Algorithms based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:37.235178', '2026-02-06 15:34:37.235178'),
	(1311, 19, 142, 'OSPS-SEC-05', 'Secure Delivery', 'Verify that the software is distributed using secure channels (HTTPS).', 'Implementation guidance for Secure Delivery based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:37.476176', '2026-02-06 15:34:37.476176'),
	(1312, 19, 143, 'OSPS-ANA-01', 'Static Code Analysis', 'Verify that the project uses at least one static code analysis tool (linter, SAST) to detect common errors.', 'Implementation guidance for Static Code Analysis based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:37.837454', '2026-02-06 15:34:37.837454'),
	(1313, 19, 143, 'OSPS-ANA-02', 'Dynamic Analysis', 'Verify that the project uses dynamic analysis tools (e.g., fuzzing) if appropriate for the language/type.', 'Implementation guidance for Dynamic Analysis based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:38.079213', '2026-02-06 15:34:38.079213'),
	(1284, 19, 138, 'OSPS-BAS-01', 'Project Website', 'Verify that the project has a website that describes what the software does and how to get it.', 'Implementation guidance for Project Website based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:30.40009', '2026-02-06 15:34:30.40009'),
	(1289, 19, 138, 'OSPS-BAS-06', 'Discussion Mechanisms', 'Verify that the project has a mechanism for discussion (mailing list, forum, issue tracker) that is searchable and accessible.', 'Implementation guidance for Discussion Mechanisms based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:31.625052', '2026-02-06 15:34:31.625052'),
	(1290, 19, 139, 'OSPS-CC-01', 'Public Version Control', 'Verify that the project uses a publicly readable version-controlled source repository (e.g., git).', 'Implementation guidance for Public Version Control based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:31.987571', '2026-02-06 15:34:31.987571'),
	(1291, 19, 139, 'OSPS-CC-02', 'Unique Versioning', 'Verify that project results have a unique version identifier for each release.', 'Implementation guidance for Unique Versioning based on OpenSSF Best Practices.', '"[]"', '2026-02-06 15:34:32.233316', '2026-02-06 15:34:32.233316');
