	(1398, 46, 'Create Baseline Risk Factors from Interview Data', 'Synthesize interview findings into preliminary set of risk factors that reflect organizational risk appetite.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Act', NULL, NULL),
	(1399, 46, 'Develop Validation Criteria and Process', 'Define standards for reviewing risk documentation completeness, accuracy, and communication effectiveness.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Plan', NULL, NULL),
	(1400, 46, 'Review Documented Scenarios and Risk Factors', 'Systematically examine risk documentation against validation criteria for completeness and accuracy.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Do', NULL, NULL),
	(1401, 46, 'Verify Communication to Development Teams', 'Confirm that risk documentation has been effectively published and communicated to relevant development teams.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Check', NULL, NULL),
	(1402, 46, 'Document Validation Findings and Gaps', 'Compile results of validation review, identifying any deficiencies in documentation or communication.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Act', NULL, NULL),
	(1403, 46, 'Analyze Validation Findings for Improvement Areas', 'Review validation report to identify specific risk factors or communication strategies needing refinement.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Plan', NULL, NULL),
	(1404, 46, 'Refine Risk Factors and Documentation', 'Update baseline risk factors and supporting documentation based on validation feedback.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Do', NULL, NULL),
	(1405, 46, 'Test Updated Risk Communication', 'Pilot revised risk communication with sample development teams to verify improved understanding.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Check', NULL, NULL),
	(1406, 46, 'Implement Updated Risk Framework Organization-Wide', 'Deploy refined risk factors and communication strategies across all relevant teams with appropriate training.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Act', NULL, NULL),
	(1407, 46, 'Identify Key Security Metrics Requirements', 'Determine which security aspects need measurement based on secure development lifecycle needs.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Plan', NULL, NULL),
	(1408, 46, 'Design Metrics Collection and Reporting Processes', 'Create procedures for collecting, calculating, and reporting the identified security metrics.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Do', NULL, NULL),
	(1409, 46, 'Validate Metrics Framework with Stakeholders', 'Review proposed metrics and processes with development and security teams for relevance and feasibility.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Check', NULL, NULL),
	(1410, 46, 'Finalize Metrics Framework Documentation', 'Incorporate feedback and create formal documentation of the security metrics framework.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Act', NULL, NULL),
	(1411, 46, 'Select and Configure Collection Tools', 'Choose appropriate software/tools for collecting the 3-5 key security metrics identified.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Plan', NULL, NULL),
	(1412, 46, 'Establish Automated Metric Collection', 'Configure systems to automatically collect the identified security metrics from relevant sources.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Do', NULL, NULL),
	(1413, 46, 'Create Basic Reporting Dashboards', 'Develop initial dashboards that visualize collected metrics for easy consumption.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Do', NULL, NULL),
	(1414, 46, 'Distribute Metrics to Development and Security Teams', 'Share initial metric reports and dashboards with relevant teams and gather initial feedback.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Act', NULL, NULL),
	(1415, 46, 'Establish Monitoring Criteria and Schedule', 'Define standards for evaluating metric collection regularity, reporting accuracy, and team utilization.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Plan', NULL, NULL),
	(1416, 46, 'Audit Metric Collection and Reporting Processes', 'Conduct regular reviews to verify metrics are being collected as designed and reports are accurate.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Do', NULL, NULL),
	(1417, 46, 'Assess Team Utilization of Metrics', 'Evaluate how development and security teams are using the metrics in decision-making and improvement efforts.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Check', NULL, NULL),
	(1418, 46, 'Document Monitoring Findings and Recommendations', 'Compile audit results and utilization assessment into report with recommendations for improvement.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Act', NULL, NULL),
	(1419, 46, 'Analyze Monitoring Findings for Metric Issues', 'Review monitoring report to identify problems with metric definitions, collection, or utilization.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Plan', NULL, NULL),
	(1420, 46, 'Update Metric Definitions and Collection Methods', 'Modify problematic metrics and their collection processes based on monitoring findings.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Do', NULL, NULL),
	(1421, 46, 'Test Refined Metrics with Pilot Teams', 'Implement updated metrics with select teams to verify improvements before organization-wide deployment.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Check', NULL, NULL),
	(1422, 46, 'Deploy Refined Metrics Framework Organization-Wide', 'Roll out updated metrics, collection processes, and reporting to all relevant teams with updated training.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 18:48:01.286141', '2026-02-08 18:48:01.286141', 'Act', NULL, NULL),
	(1680, 47, 'Define SDLC Security Integration Policy', 'Establish a formal policy mandating security integration across all SDLC phases (requirements, design, implementation, testing, deployment, maintenance).', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Plan', NULL, NULL),
	(1681, 47, 'Implement Security Gates in CI/CD Pipeline', 'Configure automated security checks (SAST, SCA) at key stages (commit, build, deploy) to enforce security requirements.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Do', NULL, NULL),
	(1682, 47, 'Audit SDLC Security Compliance', 'Conduct quarterly reviews of SDLC artifacts (threat models, code reviews, test reports) to verify security integration.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Check', NULL, NULL),
	(1683, 47, 'Update SDLC Based on Audit Findings', 'Revise SDLC processes and tools based on audit results to address gaps and improve security coverage.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Act', NULL, NULL),
	(1684, 47, 'Establish Security Story Template', 'Create a standardized template for user stories that includes mandatory security constraints (access control, data validation).', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Plan', NULL, NULL),
	(1685, 47, 'Integrate Security Constraints into Backlog', 'Update all existing and new user stories in the product backlog to include explicit security constraints.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Do', NULL, NULL);
INSERT INTO public.implementation_tasks VALUES
	(1686, 47, 'Review Story Completeness in Sprint Reviews', 'During sprint reviews, verify that implemented features align with the security constraints defined in their user stories.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Check', NULL, NULL),
	(1687, 47, 'Refine Security Constraint Guidelines', 'Update story template and training based on review findings to improve clarity and enforcement of security constraints.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Act', NULL, NULL),
	(1688, 47, 'Define Trust Boundary Documentation Standard', 'Create a standard for documenting trust boundaries, components, and data flows, including diagrams and justifications.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Plan', NULL, NULL),
	(1689, 47, 'Document Current Architecture', 'Produce comprehensive documentation of all trust boundaries, components, and data flows for the existing application.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Do', NULL, NULL),
	(1690, 47, 'Validate Documentation Against Implementation', 'Conduct a review to ensure documentation accurately reflects the live system and all trust boundaries are justified.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Check', NULL, NULL),
	(1691, 47, 'Update Documentation Process', 'Integrate trust boundary updates into the change management process to keep documentation current.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Act', NULL, NULL),
	(1692, 47, 'Set Password Length Policy', 'Define a policy allowing passwords of 64-128 characters and denying those over 128 characters.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Plan', NULL, NULL),
	(1693, 47, 'Configure Authentication System', 'Update password validation logic in the authentication system to enforce the 64-128 character limits.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Do', NULL, NULL),
	(1694, 47, 'Test Password Length Enforcement', 'Perform penetration testing to verify the system correctly accepts 64-128 char passwords and rejects others.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Check', NULL, NULL),
	(1695, 47, 'Adjust Configuration Based on Test Results', 'Modify authentication configuration if testing reveals any deviations from the password length policy.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Act', NULL, NULL),
	(1696, 47, 'Select Replay-Resistant Authentication Methods', 'Choose and document the specific OTP, cryptographic, or lookup code methods to be implemented for replay resistance.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Plan', NULL, NULL),
	(1697, 47, 'Integrate OTP/Cryptographic Authentication', 'Implement the selected authentication methods into the login and transaction verification processes.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Do', NULL, NULL),
	(1698, 47, 'Audit Replay Attack Resistance', 'Conduct security testing to ensure that captured authentication tokens cannot be reused (replayed).', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Check', NULL, NULL),
	(1699, 47, 'Enhance Authentication Based on Findings', 'Update authentication mechanisms if testing shows vulnerabilities to replay attacks.', 'todo', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'medium', 1, '2026-02-08 23:00:50.403652', '2026-02-08 23:00:50.403652', 'Act', NULL, NULL);
INSERT INTO public.implementation_templates VALUES
	(1, NULL, 'ISO 27001 Foundation Kit', 'A comprehensive baseline implementation of the ISO/IEC 27001:2022 Information Security Management System standard.', 120, 'high', 'Compliance', '"[{\"title\":\"Define ISMS Scope and Boundaries\",\"priority\":\"critical\",\"description\":\"Document the organization, location, assets, and technology included in the ISMS.\"},{\"title\":\"Establish Information Security Policy\",\"priority\":\"critical\",\"description\":\"Draft the top-level policy approved by leadership.\"},{\"title\":\"Conduct Asset Inventory\",\"priority\":\"high\",\"description\":\"Identify and owner all information assets.\"},{\"title\":\"Perform Risk Assessment\",\"priority\":\"high\",\"description\":\"Identify threats and vulnerabilities using the risk register.\"},{\"title\":\"Draft Statement of Applicability (SoA)\",\"priority\":\"critical\",\"description\":\"Justify the inclusion or exclusion of Annex A controls.\"},{\"title\":\"Implement Access Control Policy\",\"priority\":\"medium\",\"description\":\"Define user registration, privilege management, and password policies.\"},{\"title\":\"Schedule Internal Audit\",\"priority\":\"medium\",\"description\":\"Plan the first internal audit cycle.\"}]"', '[]', true, NULL, '2026-01-23 16:30:30.249531', '2026-01-23 16:30:30.249531'),
	(2, NULL, 'SOC 2 Type 1 Sprint', 'Rapid readiness plan for SOC 2 Type 1 attestation, focusing on Design of Controls.', 80, 'critical', 'Compliance', '"[{\"title\":\"Define Trust Services Criteria Scope\",\"priority\":\"critical\",\"description\":\"Confirm strict scope: Security, Availability, and/or Confidentiality.\"},{\"title\":\"Draft System Description\",\"priority\":\"high\",\"description\":\"Write the comprehensive narrative description of the system.\"},{\"title\":\"Collect Policy Acknowledgments\",\"priority\":\"medium\",\"description\":\"Ensure all staff have signed the handbook/policies.\"},{\"title\":\"Vendor Risk Review (Critical Vendors)\",\"priority\":\"high\",\"description\":\"Review contracts and SOC reports for AWS, GSuite, etc.\"},{\"title\":\"Penetration Test\",\"priority\":\"high\",\"description\":\"Engage external firm for annual pen test.\"},{\"title\":\"Evidence Collection: Onboarding\",\"priority\":\"medium\",\"description\":\"Gather screenshots of background checks and access provisioning.\"},{\"title\":\"Management Assertion Letter\",\"priority\":\"low\",\"description\":\"Draft the formal assertion for the auditor.\"}]"', '[]', true, NULL, '2026-01-23 16:30:30.501512', '2026-01-23 16:30:30.501512'),
	(3, NULL, 'Ransomware Response Playbook', 'Emergency incident response workflow for active ransomware detection.', 48, 'critical', 'Incident Response', '"[{\"title\":\"Isolate Infected Systems\",\"priority\":\"critical\",\"description\":\"Immediately disconnect affected endpoints from the network.\"},{\"title\":\"Activate Incident Response Team\",\"priority\":\"critical\",\"description\":\"Page the IRT and establish a war room.\"},{\"title\":\"Verify Backup Integrity\",\"priority\":\"critical\",\"description\":\"Check offline backups for immutability and recent success.\"},{\"title\":\"Identify Patient Zero\",\"priority\":\"high\",\"description\":\"Analyze logs to find the entry point.\"},{\"title\":\"Notify Legal Counsel\",\"priority\":\"high\",\"description\":\"Determine regulatory reporting obligations (72h rules).\"},{\"title\":\"Draft Internal Communication\",\"priority\":\"medium\",\"description\":\"Inform employees with clear instructions (do not reboot).\"},{\"title\":\"Engage Forensics Retainer\",\"priority\":\"medium\",\"description\":\"Call external IR firm if scope exceeds internal capability.\"}]"', '[]', true, NULL, '2026-01-23 16:30:30.730386', '2026-01-23 16:30:30.730386'),
	(4, NULL, 'High-Risk Vendor Audit', 'Deep-dive assessment workflow for vendors handling PII or PHI.', 24, 'high', 'TPRM', '"[{\"title\":\"Request SOC 2 / ISO Certification\",\"priority\":\"high\",\"description\":\"Collect most recent attestation report.\"},{\"title\":\"Review Privacy Policy\",\"priority\":\"medium\",\"description\":\"Check compliance with GDPR/CCPA requirements.\"},{\"title\":\"Analyze Bridge Letter\",\"priority\":\"medium\",\"description\":\"Ensure coverage period spans the current gap.\"},{\"title\":\"Confirm Data Processing Agreement (DPA)\",\"priority\":\"critical\",\"description\":\"Verify DPA is signed and legally binding.\"},{\"title\":\"Check Insurance Coverage\",\"priority\":\"low\",\"description\":\"Verify cyber liability limits.\"}]"', '[]', true, NULL, '2026-01-23 16:30:30.972566', '2026-01-23 16:30:30.972566'),
	(5, NULL, 'Q1 Security Housekeeping', 'Routine maintenance and governance tasks for the first quarter.', 16, 'low', 'Maintenance', '"[{\"title\":\"Review User Access Rights\",\"priority\":\"medium\",\"description\":\"Deprovision stale accounts (<90 days activity).\"},{\"title\":\"Test Backups\",\"priority\":\"high\",\"description\":\"Perform a restore test of a non-critical database.\"},{\"title\":\"Policy Review\",\"priority\":\"low\",\"description\":\"Annual review of Information Security Policy.\"},{\"title\":\"Update Threat Library\",\"priority\":\"medium\",\"description\":\"Add new emerging threats (e.g., AI Poisoning).\"},{\"title\":\"Schedule License Renewals\",\"priority\":\"low\",\"description\":\"Check SSL certs and domain expiries.\"}]"', '[]', true, NULL, '2026-01-23 16:30:31.198052', '2026-01-23 16:30:31.198052'),
	(7, 3, 'ISO 27001 Foundation Kit 2', 'A comprehensive baseline implementation of the ISO/IEC 27001:2022 Information Security Management System standard.', 120, 'high', 'Compliance', '"[{\"title\":\"Define ISMS Scope and Boundaries  \",\"priority\":\"medium\"},{\"title\":\"Establish Information Security Policy  \",\"priority\":\"medium\"},{\"title\":\"Identify Internal and External Issues & Interested Parties  \",\"priority\":\"medium\"},{\"title\":\"Conduct Asset Inventory  \",\"priority\":\"medium\"},{\"title\":\"Define Risk Assessment and Treatment Methodology  \",\"priority\":\"medium\"},{\"title\":\"Perform Risk Assessment  \",\"priority\":\"medium\"},{\"title\":\"Develop Risk Treatment Plan  \",\"priority\":\"medium\"},{\"title\":\"Draft Statement of Applicability (SoA)  \",\"priority\":\"medium\"},{\"title\":\"Implement Information Security Objectives  \",\"priority\":\"medium\"},{\"title\":\"Establish Competence, Awareness and Training  \",\"priority\":\"medium\"},{\"title\":\"Implement Access Control Policy  \",\"priority\":\"medium\"},{\"title\":\"Implement Incident Management Process  \",\"priority\":\"medium\"},{\"title\":\"Implement Operational Planning and Control  \",\"priority\":\"medium\"},{\"title\":\"Establish Supplier Security Requirements  \",\"priority\":\"medium\"},{\"title\":\"Schedule Internal Audit Program  \",\"priority\":\"medium\"},{\"title\":\"Conduct Management Review  \",\"priority\":\"medium\"},{\"title\":\"Define and Track ISMS Performance Metrics  \",\"priority\":\"medium\"},{\"title\":\"Implement Continual Improvement Process\",\"priority\":\"medium\"}]"', '"[]"', false, 1, '2026-01-23 16:37:40.890636', '2026-01-23 20:46:03.601'),
	(11, NULL, 'Digital Operational Resilience (DORA)', 'Digital Operational Resilience Act (DORA) roadmap structured around Plan-Do-Check-Act cycle with specific regulatory mappings.', 0, 'medium', 'Financial Sector', '"[{\"title\":\"Governance & Accountability Framework (Art. 5)\",\"description\":\"Define management body oversight, roles, responsibilities, and accountability for the ICT risk management framework.\",\"deliverables\":[\"ICT Governance Charter\",\"Role Designation Documents\"],\"estimatedHours\":40,\"phase\":\"Plan\"},{\"title\":\"ICT Risk Management Strategy (Art. 6)\",\"description\":\"Establish a comprehensive, documented framework for identifying, assessing, and mitigating ICT risks proportional to the entity.\",\"deliverables\":[\"ICT Risk Framework Document\",\"Policy Repository\"],\"estimatedHours\":80,\"phase\":\"Plan\"},{\"title\":\"Risk Identification & Assessment Methodology\",\"description\":\"Perform Business Impact Analysis (BIA) and risk classification for all critical business functions.\",\"deliverables\":[\"BIA Report\",\"Risk Classification Standards\"],\"estimatedHours\":60,\"phase\":\"Plan\"},{\"title\":\"ICT Third-party Risk Strategy (Art. 28-30)\",\"description\":\"Define policies for identifying critical providers, risk assessments, and exit/contingency strategies.\",\"deliverables\":[\"Third-party Risk Policy\",\"Provider Criticality Matrix\"],\"estimatedHours\":40,\"phase\":\"Plan\"},{\"title\":\"Incident Classification & SLA Reporting (Art. 17-23)\",\"description\":\"Operationalize incident classification and reporting workflows for authorities (e.g., ≤4 hours initial notify).\",\"deliverables\":[\"Incident Response Workflow\",\"SLA Reporting Log\"],\"estimatedHours\":60,\"phase\":\"Do\"},{\"title\":\"Digital Operational Resilience Testing (Art. 24-27)\",\"description\":\"Execute the resilience testing programme, including vulnerability assessments and TLPT (if required).\",\"deliverables\":[\"Testing Results Summary\",\"Vulnerability Scan Logs\"],\"estimatedHours\":100,\"phase\":\"Do\"},{\"title\":\"ICT Third-party Oversight active (Art. 28-44)\",\"description\":\"Implement due diligence, mandatory contract clauses, and the Register of Information on all providers.\",\"deliverables\":[\"Master Register of Providers\",\"DORA-Compliant Clauses\"],\"estimatedHours\":80,\"phase\":\"Do\"},{\"title\":\"Operational Backup & Business Continuity\",\"description\":\"Deploy and test backup/recovery procedures and ICT business continuity plans for critical systems.\",\"deliverables\":[\"Recovery Verification Reports\",\"DR Test Summary\"],\"estimatedHours\":40,\"phase\":\"Do\"},{\"title\":\"Independent Internal Audit of ICT Framework (Art. 6)\",\"description\":\"Perform a comprehensive independent review of the ICT risk management framework’s effectiveness.\",\"deliverables\":[\"Audit Report\",\"Compliance Findings Log\"],\"estimatedHours\":80,\"phase\":\"Check\"},{\"title\":\"Resilience Testing Results Evaluation (Art. 25)\",\"description\":\"Analyze outcomes of basic and advanced (TLPT) testing to identify resilience gaps.\",\"deliverables\":[\"Gap Analysis Report\",\"TLPT Evaluation Summary\"],\"estimatedHours\":40,\"phase\":\"Check\"},{\"title\":\"Incident Root Cause & Lessons Learned\",\"description\":\"Perform post-incident reviews (PIRs) for major ICT-related incidents to extract improvements.\",\"deliverables\":[\"PIR Logs\",\"Lessons Learned Report\"],\"estimatedHours\":20,\"phase\":\"Check\"},{\"title\":\"Ongoing Third-party Monitoring & Provider Audit\",\"description\":\"Monitor third-party performance indicators and conduct periodic audits of critical ICT providers.\",\"deliverables\":[\"Provider Performance Scorecard\"],\"estimatedHours\":40,\"phase\":\"Check\"},{\"title\":\"Continuous ICT Framework Improvement (Art. 6)\",\"description\":\"Refine and update the ICT risk management framework based on audit, test, and incident results.\",\"deliverables\":[\"Framework Update Log\",\"Optimized Risk Controls\"],\"estimatedHours\":60,\"phase\":\"Act\"},{\"title\":\"Remediation of Identified Weaknesses & Gaps\",\"description\":\"Assign and track corrective actions stemming from audits, tests, and PIR findings.\",\"deliverables\":[\"Remediation Roadmap\",\"Corrective Action Log\"],\"estimatedHours\":40,\"phase\":\"Act\"},{\"title\":\"Update Contracts & Third-party Strategy\",\"description\":\"Adjust provider relationships, exit strategies, and contractual clauses based on oversight findings.\",\"deliverables\":[\"Updated Provider Strategy\"],\"estimatedHours\":20,\"phase\":\"Act\"}]"', '[]', true, NULL, '2026-01-25 22:32:38.950899', '2026-01-25 22:32:38.950899'),
	(9, NULL, 'HIPAA Compliance Roadmap', 'Comprehensive HIPAA implementation guide for Privacy, Security, and Breach Notification rules, structured around the PDCA cycle.', 0, 'medium', 'Healthcare', '"[{\"title\":\"Security Risk Analysis & Management (§164.308(a)(1))\",\"description\":\"Conduct accurate & thorough assessments of potential risks and vulnerabilities to ePHI.\",\"deliverables\":[\"Risk Assessment Report\",\"Security Management Plan\"],\"estimatedHours\":60,\"phase\":\"Plan\"},{\"title\":\"Designate HIPAA Officers & Planning\",\"description\":\"Appoint Security and Privacy Officers. Develop workforce training and contingency plans.\",\"deliverables\":[\"Officer Appointment Letters\",\"Training Strategy\"],\"estimatedHours\":40,\"phase\":\"Plan\"},{\"title\":\"Develop HIPAA Privacy & Security Policies (§164.316)\",\"description\":\"Create Notice of Privacy Practices, policies for uses/disclosures, and patient rights.\",\"deliverables\":[\"Privacy & Security Policy Repository\",\"Notice of Privacy Practices (NPP)\"],\"estimatedHours\":80,\"phase\":\"Plan\"},{\"title\":\"Business Associate Agreements (BAAs) Strategy\",\"description\":\"Define policies for identifying and managing Business Associates (BAs) and exit strategies.\",\"deliverables\":[\"BAA Templates\",\"Vendor Inventory\"],\"estimatedHours\":40,\"phase\":\"Plan\"},{\"title\":\"Deploy Administrative Safeguards (§164.308)\",\"description\":\"Execute workforce training, sanctions policy, and information system activity review.\",\"deliverables\":[\"Training Completion Records\",\"Sanction Policy\"],\"estimatedHours\":80,\"phase\":\"Do\"},{\"title\":\"Implement Physical & Technical Safeguards (§164.310-312)\",\"description\":\"Deploy access controls, workstation security, audit controls, and encryption (transit/rest).\",\"deliverables\":[\"Access Matrix\",\"Encryption Configuration Audit\"],\"estimatedHours\":120,\"phase\":\"Do\"},{\"title\":\"Operationalize Privacy Rule Operations (§164.500+)\",\"description\":\"Handle patient requests (access, amendment) and accounting of disclosures.\",\"deliverables\":[\"Patient Request Log\",\"Disclosure Accounting Records\"],\"estimatedHours\":60,\"phase\":\"Do\"},{\"title\":\"Execute Breach Investigation & Notification (§164.400)\",\"description\":\"Operationalize breach investigation, mitigation, and notification protocols.\",\"deliverables\":[\"Breach Response Workflow\",\"Incident Logs\"],\"estimatedHours\":40,\"phase\":\"Do\"},{\"title\":\"Periodic Technical & Non-Technical Evaluations (§164.308(a)(8))\",\"description\":\"Perform evaluations in response to environmental or operational changes (annual review).\",\"deliverables\":[\"Evaluation Summary Report\",\"Compliance Gap List\"],\"estimatedHours\":60,\"phase\":\"Check\"},{\"title\":\"System Activity Review & Audit Controls (§164.312(b))\",\"description\":\"Regularly review audit logs from systems containing ePHI to detect anomalies.\",\"deliverables\":[\"Audit Log Review Reports\",\"Anomaly Detection Logs\"],\"estimatedHours\":40,\"phase\":\"Check\"},{\"title\":\"Internal Compliance Audits & Workforce Sanctions Review\",\"description\":\"Review workforce compliance with policies and enforce sanctions where necessary.\",\"deliverables\":[\"Internal Audit Findings\",\"Sanction Action Records\"],\"estimatedHours\":40,\"phase\":\"Check\"},{\"title\":\"KPI & Privacy Metrics Tracking\",\"description\":\"Monitor training completion rates, access violations, and breach trends.\",\"deliverables\":[\"Compliance Performance Dashboard\"],\"estimatedHours\":20,\"phase\":\"Check\"},{\"title\":\"Corrective Action Planning (CAP) & Remediation\",\"description\":\"Remediate weaknesses and gaps identified during technical evaluations and audits.\",\"deliverables\":[\"Remediation Roadmap\",\"Corrective Action Log\"],\"estimatedHours\":60,\"phase\":\"Act\"},{\"title\":\"Update Risk Management & Policies\",\"description\":\"Refine policies, procedures, and risk assessments based on audit findings and new threats.\",\"deliverables\":[\"Updated Risk Assessment\",\"Policy Revision History\"],\"estimatedHours\":40,\"phase\":\"Act\"},{\"title\":\"Refine Breach Response & Training Programmes\",\"description\":\"Optimize response playbooks and training curriculum based on lessons learned from PIRs.\",\"deliverables\":[\"Optimized Training Curriculum\",\"Updated PIR Process\"],\"estimatedHours\":20,\"phase\":\"Act\"}]"', '[]', true, NULL, '2026-01-25 22:29:55.503361', '2026-01-25 22:29:55.503361'),
	(10, NULL, 'PCI DSS 4.0 Readiness', 'Step-by-step implementation roadmap for PCI DSS v4.0 structured around the PDCA cycle, including Targeted Risk Analysis.', 0, 'medium', 'Payments', '"[{\"title\":\"CDE Scoping & Asset Inventory (Requirement 1)\",\"description\":\"Define the Cardholder Data Environment (CDE), connected systems, and perform annual scope confirmation.\",\"deliverables\":[\"CDE Scope Map\",\"System Inventory\"],\"estimatedHours\":40,\"phase\":\"Plan\"},{\"title\":\"Targeted Risk Analysis (TRA - v4.0 Requirement)\",\"description\":\"Perform risk-based analyses for frequency of controls such as vulnerability scans and penetration testing.\",\"deliverables\":[\"TRA Report\",\"Control Frequency Schedule\"],\"estimatedHours\":60,\"phase\":\"Plan\"},{\"title\":\"Develop PCI Security Policies & Procedures (Req 12)\",\"description\":\"Create and disseminate security policies addressing all 12 requirements; assign explicit roles and responsibilities.\",\"deliverables\":[\"Master Security Policy\",\"Roles & Responsibilities Matrix\"],\"estimatedHours\":80,\"phase\":\"Plan\"},{\"title\":\"Define Secure Configuration Standards (Req 2)\",\"description\":\"Establish hardening standards and policies for removing vendor-default settings and secure protocols.\",\"deliverables\":[\"System Hardening Standards\",\"Baseline Configuration Documents\"],\"estimatedHours\":40,\"phase\":\"Plan\"},{\"title\":\"Implement Network Security & Segmentation (Req 1)\",\"description\":\"Deploy firewalls and network security controls (NSCs) to isolate the CDE from untrusted networks.\",\"deliverables\":[\"Firewall Ruleset\",\"Network Segregation Verification\"],\"estimatedHours\":80,\"phase\":\"Do\"},{\"title\":\"Protect Stored & Transmitted Account Data (Req 3-4)\",\"description\":\"Implement encryption (TLS), masking, and tokenization for both stored data and data in transit.\",\"deliverables\":[\"Encryption Audit Report\",\"Data Protection Logs\"],\"estimatedHours\":120,\"phase\":\"Do\"},{\"title\":\"Vulnerability Management & Secure Development (Req 5-6)\",\"description\":\"Deploy anti-malware, secure software development practices, and apply security patches regularly.\",\"deliverables\":[\"Patching Logs\",\"Secure Coding Guidelines\"],\"estimatedHours\":100,\"phase\":\"Do\"},{\"title\":\"Strong Access Control & MFA Implementation (Req 7-9)\",\"description\":\"Restrict access based on least privilege, enforce unique IDs, and implement MFA for all access to the CDE.\",\"deliverables\":[\"Access Control Matrix\",\"MFA Confirmation Reports\"],\"estimatedHours\":60,\"phase\":\"Do\"},{\"title\":\"Logging, Monitoring & Daily Reviews (Req 10)\",\"description\":\"Implement comprehensive logging and automated alerts; perform daily reviews of critical security logs.\",\"deliverables\":[\"Log Management Strategy\",\"Daily Review Records\"],\"estimatedHours\":80,\"phase\":\"Check\"},{\"title\":\"Vulnerability Scans & Penetration Testing (Req 11)\",\"description\":\"Perform quarterly ASV scans (external) and internal scans; conduct annual penetration testing.\",\"deliverables\":[\"ASV Scan Reports\",\"Internal Pen Test Results\"],\"estimatedHours\":100,\"phase\":\"Check\"},{\"title\":\"Periodic Reviews & TRA Updates\",\"description\":\"Re-perform targeted risk analyses after major changes and review overall control effectiveness.\",\"deliverables\":[\"Updated TRA Documentation\",\"Control Effectiveness Review\"],\"estimatedHours\":40,\"phase\":\"Check\"},{\"title\":\"Internal Audit & SAQ/ROC Preparation\",\"description\":\"Conduct self-assessments or internal audits to prepare for formal compliance reporting.\",\"deliverables\":[\"Completed SAQ/Draft ROC\",\"Compliance Evidence Collection\"],\"estimatedHours\":60,\"phase\":\"Check\"},{\"title\":\"Vulnerability Remediation & Feedback Loop\",\"description\":\"Address vulnerabilities within defined SLAs and remediate penetration testing findings.\",\"deliverables\":[\"Remediation Roadmap\",\"Vulnerability Fix Confirmation\"],\"estimatedHours\":60,\"phase\":\"Act\"},{\"title\":\"Strengthen Controls Post-Incident (Lessons Learned)\",\"description\":\"Enhance monitors and controls based on post-incident reviews or identified security weaknesses.\",\"deliverables\":[\"Updated IRP Playbooks\",\"Lessons Learned Summary\"],\"estimatedHours\":40,\"phase\":\"Act\"},{\"title\":\"Continuous Governance & Program Refinement\",\"description\":\"Update policies, training, and governance processes based on findings from the Check phase.\",\"deliverables\":[\"Framework Optimization Plan\",\"Policy Version Records\"],\"estimatedHours\":20,\"phase\":\"Act\"}]"', '[]', true, NULL, '2026-01-25 22:29:55.728785', '2026-01-25 22:29:55.728785'),
	(12, NULL, 'EU AI Act Implementation', 'Comprehensive PDCA implementation for EU AI Act compliance.', 0, 'medium', 'EU Regulation', '"[{\"title\":\"AI Risk Management System Setup (Art. 9)\",\"description\":\"[Plan] Establish a continuous iterative risk management process to identify, estimate, and evaluate risks to health, safety, and fundamental rights.\",\"priority\":\"medium\",\"pdca\":\"Plan\",\"estimatedHours\":80,\"deliverables\":[\"Risk Management Policy\",\"Initial Risk Assessment\"]},{\"title\":\"Quality Management System (QMS) Planning (Art. 17)\",\"description\":\"[Plan] Design a QMS covering design, development, testing, and post-market monitoring procedures.\",\"priority\":\"medium\",\"pdca\":\"Plan\",\"estimatedHours\":100,\"deliverables\":[\"QMS Manual\",\"Development Lifecycle Policy\"]},{\"title\":\"Data Governance & Technical Docs Planning (Art. 10, 11)\",\"description\":\"[Plan] Plan for high-quality training/validation datasets and define technical documentation requirements.\",\"priority\":\"medium\",\"pdca\":\"Plan\",\"estimatedHours\":60,\"deliverables\":[\"Data Governance Policy\",\"Tech Doc Templates\"]},{\"title\":\"Fundamental Rights Impact Assessment (FRIA) Prep\",\"description\":\"[Plan] If applicable (deployer/high-risk), prepare methodology for assessing impact on fundamental rights.\",\"priority\":\"medium\",\"pdca\":\"Plan\",\"estimatedHours\":40,\"deliverables\":[\"FRIA Methodology\"]},{\"title\":\"Implement Human Oversight & Logging (Art. 14, 12)\",\"description\":\"[Do] Embed human-machine interface tools for oversight and automatic logging of system events.\",\"priority\":\"medium\",\"pdca\":\"Do\",\"estimatedHours\":80,\"deliverables\":[\"Oversight Interface Design\",\"Logging Configuration\"]},{\"title\":\"Execute Risk Mitigation & Accuracy Measures\",\"description\":\"[Do] Implement specific design choices to minimize identified risks and ensure accuracy/robustness.\",\"priority\":\"medium\",\"pdca\":\"Do\",\"estimatedHours\":120,\"deliverables\":[\"Mitigation Evidence\",\"Accuracy Test Results\"]},{\"title\":\"Conformity Assessment & CE Marking\",\"description\":\"[Do] Perform internal control or third-party assessment. Draw up Declaration of Conformity.\",\"priority\":\"medium\",\"pdca\":\"Do\",\"estimatedHours\":100,\"deliverables\":[\"EU Declaration of Conformity\",\"CE Marking File\"]},{\"title\":\"Registration in EU Database (Art. 49)\",\"description\":\"[Do] Register the high-risk AI system in the EU database before placing on the market.\",\"priority\":\"medium\",\"pdca\":\"Do\",\"estimatedHours\":20,\"deliverables\":[\"Registration Certificate\"]},{\"title\":\"Post-Market Monitoring (PMM) System (Art. 72)\",\"description\":\"[Check] Actively collect and analyze data on AI system performance in the field.\",\"priority\":\"medium\",\"pdca\":\"Check\",\"estimatedHours\":60,\"deliverables\":[\"PMM Plan\",\"Monitoring Reports\"]},{\"title\":\"Incident & Malfunction Reporting\",\"description\":\"[Check] Process for identifying and reporting serious incidents to market surveillance authorities.\",\"priority\":\"medium\",\"pdca\":\"Check\",\"estimatedHours\":40,\"deliverables\":[\"Incident Logs\",\"Authority Reports\"]},{\"title\":\"Periodic Audits & Conformity Reviews\",\"description\":\"[Check] Regularly audit the QMS and re-assess conformity if substantial changes occur.\",\"priority\":\"medium\",\"pdca\":\"Check\",\"estimatedHours\":60,\"deliverables\":[\"Audit Reports\",\"Conformity Re-assessment\"]},{\"title\":\"Corrective Actions & Model Retraining\",\"description\":\"[Act] Take necessary steps to bring non-compliant systems into conformity (e.g., retraining, bug fixes).\",\"priority\":\"medium\",\"pdca\":\"Act\",\"estimatedHours\":80,\"deliverables\":[\"Corrective Action Report\",\"Model Version 2.0\"]},{\"title\":\"Update Risk Management & Documentation\",\"description\":\"[Act] Update the risk assessment and technical documentation based on PMM data.\",\"priority\":\"medium\",\"pdca\":\"Act\",\"estimatedHours\":40,\"deliverables\":[\"Updated Risk Register\",\"Revised Technical Docs\"]},{\"title\":\"Continuous QMS Improvement\",\"description\":\"[Act] Refine quality processes based on lessons learned from incidents or audits.\",\"priority\":\"medium\",\"pdca\":\"Act\",\"estimatedHours\":20,\"deliverables\":[\"QMS Update Log\"]}]"', '[]', true, 1, '2026-01-26 07:00:30.11803', '2026-01-26 07:00:30.11803'),
	(13, NULL, 'GDPR Implementation', 'End-to-end GDPR compliance roadmap following Governance -> Implementation -> Audit -> Response.', 0, 'high', 'Privacy', '"[{\"title\":\"Appoint Data Protection Officer (DPO) & Governance\",\"description\":\"[Plan] Designate a DPO if required (Art. 37) and establish privacy governance structure.\",\"priority\":\"medium\",\"pdca\":\"Plan\",\"estimatedHours\":40,\"deliverables\":[\"DPO Appointment Letter\",\"Privacy Charter\"]},{\"title\":\"Records of Processing Activities (ROPA - Art. 30)\",\"description\":\"[Plan] Map all personal data flows, categories, purposes, and recipients.\",\"priority\":\"medium\",\"pdca\":\"Plan\",\"estimatedHours\":100,\"deliverables\":[\"ROPA Inventory\",\"Data Flow Maps\"]},{\"title\":\"Data Protection Impact Assessments (DPIA Policy)\",\"description\":\"[Plan] Establish methodology for DPIAs and conduct them for high-risk processing.\",\"priority\":\"medium\",\"pdca\":\"Plan\",\"estimatedHours\":60,\"deliverables\":[\"DPIA Policy\",\"Initial DPIA Reports\"]},{\"title\":\"Vendor Risk Management (Processors)\",\"description\":\"[Plan] Identify all data processors and review Data Processing Agreements (DPAs).\",\"priority\":\"medium\",\"pdca\":\"Plan\",\"estimatedHours\":80,\"deliverables\":[\"Vendor Inventory\",\"Signed DPAs\"]},{\"title\":\"Update Privacy Notices & Transparency\",\"description\":\"[Do] Ensure Article 13/14 disclosures are clear, accessible, and up-to-date.\",\"priority\":\"medium\",\"pdca\":\"Do\",\"estimatedHours\":40,\"deliverables\":[\"Privacy Policy\",\"Cookie Notice\"]},{\"title\":\"Consent Management Implementation\",\"description\":\"[Do] Implement granular consent mechanisms (CMP) for cookies and marketing.\",\"priority\":\"medium\",\"pdca\":\"Do\",\"estimatedHours\":60,\"deliverables\":[\"CMP Deployment\",\"Consent Logs\"]},{\"title\":\"Data Subject Rights (DSR) Workflow\",\"description\":\"[Do] Operationalize handling of Access, Erasure, and Portability requests.\",\"priority\":\"medium\",\"pdca\":\"Do\",\"estimatedHours\":50,\"deliverables\":[\"DSR Standard Operating Procedure\",\"DSR Log\"]},{\"title\":\"Security Measures (TOMs - Art. 32)\",\"description\":\"[Do] Implement encryption, pseudonymization, and access controls.\",\"priority\":\"medium\",\"pdca\":\"Do\",\"estimatedHours\":120,\"deliverables\":[\"Encryption Standards\",\"Access Control Policy\"]},{\"title\":\"GDPR Internal Audit\",\"description\":\"[Check] Conduct an internal audit of privacy controls and ROPA accuracy.\",\"priority\":\"medium\",\"pdca\":\"Check\",\"estimatedHours\":60,\"deliverables\":[\"Internal Audit Report\",\"Gap Analysis\"]},{\"title\":\"Vendor Compliance Review\",\"description\":\"[Check] Audit key processors to ensure adherence to DPA terms.\",\"priority\":\"medium\",\"pdca\":\"Check\",\"estimatedHours\":40,\"deliverables\":[\"Vendor Audit Reports\"]},{\"title\":\"DSR & Breach Metric Review\",\"description\":\"[Check] Review response times for DSRs and effectiveness of breach detection.\",\"priority\":\"medium\",\"pdca\":\"Check\",\"estimatedHours\":20,\"deliverables\":[\"Privacy Metrics Dashboard\"]},{\"title\":\"Data Breach Response Planning (Art. 33/34)\",\"description\":\"[Act] Test and refine the 72-hour breach notification procedure.\",\"priority\":\"medium\",\"pdca\":\"Act\",\"estimatedHours\":40,\"deliverables\":[\"Breach Response Plan\",\"Tabletop Exercise Report\"]},{\"title\":\"Remediation & Continual Improvement\",\"description\":\"[Act] Address audit findings and update policies based on regulatory changes.\",\"priority\":\"medium\",\"pdca\":\"Act\",\"estimatedHours\":40,\"deliverables\":[\"Corrective Action Plan\"]}]"', '[]', true, 1, '2026-01-26 07:35:54.710624', '2026-01-26 07:35:54.710624'),
	(14, NULL, 'SOC 2 Type II Readiness & Audit', 'Complete roadmap for SOC 2 Type II: Readiness, Implementation, Observation Period (6-12mo), and Audit.', 0, 'high', 'Security', '"[{\"title\":\"Define Service Commitments & System Requirements\",\"description\":\"[Plan] Establish the scope of the SOC 2 report (Security, Availability, Confidentiality, etc.) and define service commitments.\",\"priority\":\"high\",\"pdca\":\"Plan\",\"estimatedHours\":40,\"deliverables\":[\"System Description (Section 3)\",\"Service Commitments\"]},{\"title\":\"SOC 2 Risk Assessment\",\"description\":\"[Plan] Identify risks to the achievement of service commitments (CC3.1, CC3.2).\",\"priority\":\"high\",\"pdca\":\"Plan\",\"estimatedHours\":60,\"deliverables\":[\"Risk Assessment Report\"]},{\"title\":\"Information Security Policy Development\",\"description\":\"[Plan] Develop and approve policies covering all Common Criteria (CC) requirements.\",\"priority\":\"high\",\"pdca\":\"Plan\",\"estimatedHours\":80,\"deliverables\":[\"InfoSec Policy Bundle\",\"Acceptable Use Policy\"]},{\"title\":\"Vendor & Third-Party Risk Management\",\"description\":\"[Plan] Inventory vendors and assess risks associated with third-party service providers (CC9.2).\",\"priority\":\"high\",\"pdca\":\"Plan\",\"estimatedHours\":40,\"deliverables\":[\"Vendor Inventory\",\"Vendor Risk Reviews\"]},{\"title\":\"Access Control & MFA Implementation\",\"description\":\"[Do] Enforce logical access controls, MFA, and user access reviews (CC6.1 - CC6.3).\",\"priority\":\"high\",\"pdca\":\"Do\",\"estimatedHours\":60,\"deliverables\":[\"Access Control Config\",\"User Access Review Log\"]},{\"title\":\"Change Management Process (SDLC)\",\"description\":\"[Do] Implement formal change management for software changes (CC8.1).\",\"priority\":\"high\",\"pdca\":\"Do\",\"estimatedHours\":50,\"deliverables\":[\"Change Management Policy\",\"Change Tickets Evidence\"]},{\"title\":\"Security Awareness Training\",\"description\":\"[Do] Conduct security awareness training for all employees (CC2.2).\",\"priority\":\"high\",\"pdca\":\"Do\",\"estimatedHours\":30,\"deliverables\":[\"Training Completion Report\"]},{\"title\":\"Incident Response & Backup Testing\",\"description\":\"[Do] Test incident response plans and backup recovery procedures (CC7.3, A1.2).\",\"priority\":\"high\",\"pdca\":\"Do\",\"estimatedHours\":40,\"deliverables\":[\"IRP Test Report\",\"Backup Restore Log\"]},{\"title\":\"Start Observation Period (Window Open)\",\"description\":\"[Check] Formal start of the audit window. Ensure all controls are operating effectively.\",\"priority\":\"high\",\"pdca\":\"Check\",\"estimatedHours\":10,\"deliverables\":[\"Observation Start Memo\"]},{\"title\":\"Quarterly Access Reviews\",\"description\":\"[Check] Perform and document user access reviews during the observation period.\",\"priority\":\"high\",\"pdca\":\"Check\",\"estimatedHours\":20,\"deliverables\":[\"Q1 Access Review\",\"Q2 Access Review\"]},{\"title\":\"Internal Readiness Assessment (Mid-Window)\",\"description\":\"[Check] Check for control failures halfway through the observation period.\",\"priority\":\"high\",\"pdca\":\"Check\",\"estimatedHours\":40,\"deliverables\":[\"Mid-Window Gap Report\"]},{\"title\":\"Penetration Testing (Annual)\",\"description\":\"[Check] Conduct annual penetration testing during the observation window.\",\"priority\":\"high\",\"pdca\":\"Check\",\"estimatedHours\":60,\"deliverables\":[\"Pen Test Report\"]},{\"title\":\"Auditor Fieldwork Support\",\"description\":\"[Act] Provide evidence samples to the external auditor (QSA/CPA).\",\"priority\":\"high\",\"pdca\":\"Act\",\"estimatedHours\":80,\"deliverables\":[\"Provided Evidence Log\"]},{\"title\":\"Management Representation Letter\",\"description\":\"[Act] Sign management letter asserting responsibility for controls.\",\"priority\":\"high\",\"pdca\":\"Act\",\"estimatedHours\":10,\"deliverables\":[\"Signed Management Rep Letter\"]},{\"title\":\"Final SOC 2 Type II Report\",\"description\":\"[Act] Receive and distribute the final Type II report.\",\"priority\":\"high\",\"pdca\":\"Act\",\"estimatedHours\":20,\"deliverables\":[\"SOC 2 Type II Report\"]}]"', '[]', true, 1, '2026-01-26 07:39:49.997046', '2026-01-26 07:39:49.997046'),
	(8, NULL, 'NIST CSF 2.0 Implementation', 'Full implementation roadmap for NIST CSF 2.0 (Govern, Identify, Protect, Detect, Respond, Recover).', 0, 'high', 'Framework', '"[{\"title\":\"Establish Cybersecurity Governance Structure\",\"description\":\"[Govern] Define roles, responsibilities, and authorities for cybersecurity risk management.\",\"priority\":\"medium\",\"pdca\":\"Govern\",\"estimatedHours\":40,\"deliverables\":[\"Governance Charter\",\"Roles & Responsibilities Matrix\"]},{\"title\":\"Develop Cybersecurity Strategy & Policy\",\"description\":\"[Govern] Create a core cybersecurity strategy aligned with organizational goals.\",\"priority\":\"medium\",\"pdca\":\"Govern\",\"estimatedHours\":60,\"deliverables\":[\"Cybersecurity Strategy Document\",\"Master Policy Document\"]},{\"title\":\"Asset Inventory & Scoping\",\"description\":\"[Identify] Identify systems, people, assets, data, and capabilities that enable the organization to achieve business purposes.\",\"priority\":\"medium\",\"pdca\":\"Identify\",\"estimatedHours\":80,\"deliverables\":[\"Data Flow Diagrams\",\"Asset Register\"]},{\"title\":\"Cybersecurity Risk Assessment\",\"description\":\"[Identify] Identify and prioritize risks to assets and business functions.\",\"priority\":\"medium\",\"pdca\":\"Identify\",\"estimatedHours\":100,\"deliverables\":[\"Risk Assessment Report\",\"Prioritized Mitigation List\"]},{\"title\":\"Identity Management & Access Control\",\"description\":\"[Protect] Establish physical and logical access controls to protected assets.\",\"priority\":\"medium\",\"pdca\":\"Protect\",\"estimatedHours\":120,\"deliverables\":[\"IAM Policy\",\"Access Matrix\"]},{\"title\":\"Data Security Controls\",\"description\":\"[Protect] Implement encryption, data loss prevention, and integrity protection measures.\",\"priority\":\"medium\",\"pdca\":\"Protect\",\"estimatedHours\":160,\"deliverables\":[\"Encryption Standards\",\"DLP Configuration\"]},{\"title\":\"Continuous Security Monitoring\",\"description\":\"[Detect] Monitor information assets and networks for security events.\",\"priority\":\"medium\",\"pdca\":\"Detect\",\"estimatedHours\":80,\"deliverables\":[\"SIEM Configuration\",\"Monitoring Logs\"]},{\"title\":\"Detection Process Verification\",\"description\":\"[Detect] Test and evaluate detection processes to ensure timely alerts.\",\"priority\":\"medium\",\"pdca\":\"Detect\",\"estimatedHours\":40,\"deliverables\":[\"Alert Accuracy Report\"]},{\"title\":\"Incident Response Planning\",\"description\":\"[Respond] Ensure response processes are tested and personnel are trained.\",\"priority\":\"medium\",\"pdca\":\"Respond\",\"estimatedHours\":60,\"deliverables\":[\"IRP Plan\",\"Tabletop Exercise Results\"]},{\"title\":\"Containment & Mitigation Strategy\",\"description\":\"[Respond] Implement procedures to contain and mitigate the impact of events.\",\"priority\":\"medium\",\"pdca\":\"Respond\",\"estimatedHours\":40,\"deliverables\":[\"Containment Playbooks\"]},{\"title\":\"Resilience & Recovery Planning\",\"description\":\"[Recover] Maintain recovery processes and procedures to ensure restoration of systems.\",\"priority\":\"medium\",\"pdca\":\"Recover\",\"estimatedHours\":60,\"deliverables\":[\"BCP/DR Plan\",\"Recovery Time Objectives (RTO) documentation\"]}]"', '[]', true, NULL, '2026-01-25 22:26:49.051636', '2026-01-25 22:26:49.051636'),
	(15, NULL, 'NIS2 Directive Implementation', 'Comprehensive implementation plan for EU NIS2 Directive compliance covering risk management, incident reporting, supply chain security, and cybersecurity measures.', 160, 'high', 'EU Regulation', '"[{\"title\":\"NIS2 Scope Assessment\",\"priority\":\"critical\",\"description\":\"Determine if organization qualifies as Essential or Important Entity under NIS2.\"},{\"title\":\"Cybersecurity Risk Management Measures\",\"priority\":\"critical\",\"description\":\"Implement policies and procedures for risk analysis and security measures (Art. 21).\"},{\"title\":\"Incident Handling & Reporting System\",\"priority\":\"critical\",\"description\":\"Establish processes for detecting, handling, and reporting incidents within 24h (Art. 23).\"},{\"title\":\"Supply Chain Security Assessment\",\"priority\":\"high\",\"description\":\"Evaluate and manage cybersecurity risks in the supply chain (Art. 21).\"},{\"title\":\"Business Continuity & Crisis Management\",\"priority\":\"high\",\"description\":\"Develop business continuity plans and crisis management procedures.\"},{\"title\":\"Encryption & Cryptography Policies\",\"priority\":\"high\",\"description\":\"Implement appropriate encryption for data protection and integrity.\"},{\"title\":\"Vulnerability Handling Procedures\",\"priority\":\"medium\",\"description\":\"Establish processes for identifying, reporting, and remediating vulnerabilities.\"},{\"title\":\"Security in Network Configuration\",\"priority\":\"medium\",\"description\":\"Implement security measures in network and information system design.\"},{\"title\":\"Access Control & Authentication\",\"priority\":\"medium\",\"description\":\"Implement multi-factor authentication and strict access controls.\"},{\"title\":\"Employee Awareness & Training\",\"priority\":\"medium\",\"description\":\"Develop cybersecurity training programs for all staff.\"},{\"title\":\"Management Body Oversight\",\"priority\":\"high\",\"description\":\"Establish governance with management body approval of cybersecurity measures.\"},{\"title\":\"Third-Party Risk Management\",\"priority\":\"medium\",\"description\":\"Implement due diligence for third-party service providers.\"},{\"title\":\"Asset Management & Inventory\",\"priority\":\"medium\",\"description\":\"Maintain inventory of critical assets and information systems.\"},{\"title\":\"Security Testing & Auditing\",\"priority\":\"medium\",\"description\":\"Regular penetration testing and security audits.\"},{\"title\":\"Data Protection Impact Assessment\",\"priority\":\"medium\",\"description\":\"Conduct DPIAs for processing operations under NIS2.\"}]"', '[]', true, NULL, '2026-01-26 18:08:54.771889', '2026-01-26 18:08:54.771889'),
	(16, 3, 'NIS2 Directive Implementation (Copy)', 'Comprehensive implementation plan for EU NIS2 Directive compliance covering risk management, incident reporting, supply chain security, and cybersecurity measures.', 160, 'high', 'EU Regulation', '"[{\"title\":\"NIS2 Scope Assessment\",\"priority\":\"critical\",\"description\":\"Determine if organization qualifies as Essential or Important Entity under NIS2.\"},{\"title\":\"Cybersecurity Risk Management Measures\",\"priority\":\"critical\",\"description\":\"Implement policies and procedures for risk analysis and security measures (Art. 21).\"},{\"title\":\"Incident Handling & Reporting System\",\"priority\":\"critical\",\"description\":\"Establish processes for detecting, handling, and reporting incidents within 24h (Art. 23).\"},{\"title\":\"Supply Chain Security Assessment\",\"priority\":\"high\",\"description\":\"Evaluate and manage cybersecurity risks in the supply chain (Art. 21).\"},{\"title\":\"Business Continuity & Crisis Management\",\"priority\":\"high\",\"description\":\"Develop business continuity plans and crisis management procedures.\"},{\"title\":\"Encryption & Cryptography Policies\",\"priority\":\"high\",\"description\":\"Implement appropriate encryption for data protection and integrity.\"},{\"title\":\"Vulnerability Handling Procedures\",\"priority\":\"medium\",\"description\":\"Establish processes for identifying, reporting, and remediating vulnerabilities.\"},{\"title\":\"Security in Network Configuration\",\"priority\":\"medium\",\"description\":\"Implement security measures in network and information system design.\"},{\"title\":\"Access Control & Authentication\",\"priority\":\"medium\",\"description\":\"Implement multi-factor authentication and strict access controls.\"},{\"title\":\"Employee Awareness & Training\",\"priority\":\"medium\",\"description\":\"Develop cybersecurity training programs for all staff.\"},{\"title\":\"Management Body Oversight\",\"priority\":\"high\",\"description\":\"Establish governance with management body approval of cybersecurity measures.\"},{\"title\":\"Third-Party Risk Management\",\"priority\":\"medium\",\"description\":\"Implement due diligence for third-party service providers.\"},{\"title\":\"Asset Management & Inventory\",\"priority\":\"medium\",\"description\":\"Maintain inventory of critical assets and information systems.\"},{\"title\":\"Security Testing & Auditing\",\"priority\":\"medium\",\"description\":\"Regular penetration testing and security audits.\"},{\"title\":\"Data Protection Impact Assessment\",\"priority\":\"medium\",\"description\":\"Conduct DPIAs for processing operations under NIS2.\"}]"', '"[]"', false, 1, '2026-01-26 18:14:39.974625', '2026-01-26 18:14:39.974625');
