INSERT INTO public.maturity_frameworks VALUES
	('nist-csf-2', 'NIST CSF 2.0', 'National Institute of Standards and Technology Cybersecurity Framework Version 2.0', '2.0', '/frameworks/nist.svg', '"[{\"level\":1,\"name\":\"Partial\",\"description\":\"Risk management is informal and ad-hoc.\"},{\"level\":2,\"name\":\"Risk Informed\",\"description\":\"Risk management practices are approved but not organization-wide.\"},{\"level\":3,\"name\":\"Repeatable\",\"description\":\"Risk management practices are formally approved and expressed as policy.\"},{\"level\":4,\"name\":\"Adaptive\",\"description\":\"The organization adapts its cybersecurity practices based on lessons learned and predictive indicators.\"}]"', 'active', '2026-02-12 08:46:01.885897', '2026-02-12 08:46:01.885897'),
	('cisa-ztmm-2', 'CISA Zero Trust Maturity Model 2.0', 'Cybersecurity and Infrastructure Security Agency Zero Trust Maturity Model Version 2.0', '2.0', '/frameworks/cisa.svg', '"[{\"level\":1,\"name\":\"Traditional\",\"description\":\"Manual configurations and static policies.\"},{\"level\":2,\"name\":\"Initial\",\"description\":\"Starting to automate attribute assignment and configuration lifecycles.\"},{\"level\":3,\"name\":\"Advanced\",\"description\":\"Centralized visibility and identity control across the enterprise.\"},{\"level\":4,\"name\":\"Optimal\",\"description\":\"Fully automated, just-in-time lifecycles and dynamic policies.\"}]"', 'active', '2026-02-12 08:46:02.008409', '2026-02-12 08:46:02.008409'),
	('cmmc-2', 'CMMC 2.0', 'Cybersecurity Maturity Model Certification Version 2.0', '2.0', '/cmmc-logo.png', '"[{\"level\":1,\"name\":\"Foundational\",\"description\":\"Basic safeguarding of FCI (Federal Contract Information).\"},{\"level\":2,\"name\":\"Advanced\",\"description\":\"Protecting CUI (Controlled Unclassified Information).\"},{\"level\":3,\"name\":\"Expert\",\"description\":\"Protecting CUI against APTs (Advanced Persistent Threats).\"}]"', 'active', '2026-02-12 08:46:02.121884', '2026-02-12 08:46:02.121884'),
	('c2m2-2.1', 'C2M2 V2.1', 'Cybersecurity Capability Maturity Model Version 2.1', '2.1', '/frameworks/c2m2.svg', '"[{\"level\":1,\"name\":\"MIL 1\",\"description\":\"Initial implementation of practices.\"},{\"level\":2,\"name\":\"MIL 2\",\"description\":\"Practices are documented and guided by policy.\"},{\"level\":3,\"name\":\"MIL 3\",\"description\":\"Practices are managed and institutionalized.\"}]"', 'active', '2026-02-13 11:06:50.136955', '2026-02-13 11:06:50.136955');
