	(153, 'cmmc-2', 12, '3.1.10', 'Use session lock with pattern', 'Use session lock with pattern-hiding displays to prevent access and viewing of data after a period of inactivity.', 2, 0, 'Determine if:', '[]'),
	(154, 'cmmc-2', 12, '3.1.11', 'Terminate (automatically) a user session after a defined con...', 'Terminate (automatically) a user session after a defined condition.', 2, 0, 'Determine if:', '[]'),
