	(159, 'cmmc-2', 12, '3.1.16', 'Authorize wireless access prior to allowing such connections...', 'Authorize wireless access prior to allowing such connections.', 2, 0, 'Determine if:', '[]'),
	(160, 'cmmc-2', 12, '3.1.17', 'Protect wireless access using authentication and encryption....', 'Protect wireless access using authentication and encryption.', 2, 0, 'Determine if:', '[]'),
	(161, 'cmmc-2', 12, '3.1.18', 'Control connection of mobile devices....', 'Control connection of mobile devices.', 2, 0, 'Determine if:', '[]'),
