	(164, 'cmmc-2', 12, '3.1.21', 'Limit use of organizational portable storage devices on exte...', 'Limit use of organizational portable storage devices on external systems.', 2, 0, 'Determine if:', '[]'),
	(165, 'cmmc-2', 12, '3.1.22', 'Control CUI posted or processed on publicly accessible syste...', 'Control CUI posted or processed on publicly accessible systems.', 2, 0, 'Determine if CUI posted or processed on publicly accessible systems is controlled.', '[]'),
	(166, 'cmmc-2', 16, '3.2.1', 'Ensure that managers, systems administrators, and users of o...', 'Ensure that managers, systems administrators, and users of organizational systems are made aware of the security risks associated with their activities and of the applicable policies, standards, and procedures related to the security of those systems.', 2, 0, 'Determine if:', '[]'),
	(167, 'cmmc-2', 16, '3.2.2', 'Ensure that organizational personnel are adequately trained ...', 'Ensure that organizational personnel are adequately trained to carry out their assigned information security-related duties and responsibilities.', 2, 0, 'Determine if:', '[]'),
