	(170, 'cmmc-2', 17, '3.3.2', 'Ensure that the actions of individual system users can be un...', 'Ensure that the actions of individual system users can be uniquely traced to those users so they can be held accountable for their actions.', 2, 0, 'Determine if:', '[]'),
	(171, 'cmmc-2', 17, '3.3.3', 'Review and update logged events....', 'Review and update logged events.', 2, 0, 'Determine if:', '[]'),
