	(195, 'cmmc-2', 13, '3.5.9', 'Allow temporary password use for system logons with an immed...', 'Allow temporary password use for system logons with an immediate change to a permanent password', 2, 0, 'Determine if an immediate change to a permanent password is required when a temporary password is used for system logon.', '[]'),
	(196, 'cmmc-2', 13, '3.5.10', 'Store and transmit only cryptographically', 'Store and transmit only cryptographically-protected passwords.', 2, 0, 'Determine if:', '[]'),
