	(199, 'cmmc-2', 19, '3.6.2', 'Track, document, and report incidents to designated official...', 'Track, document, and report incidents to designated officials and/or authorities both internal and external to the organization.', 2, 0, 'Determine if:', '[]'),
	(200, 'cmmc-2', 19, '3.6.3', 'Test the organizational incident response capability....', 'Test the organizational incident response capability.', 2, 0, 'Determine if the incident response capability is tested.', '[]'),
	(201, 'cmmc-2', 20, '3.7.1', 'Perform maintenance on organizational systems....', 'Perform maintenance on organizational systems.', 2, 0, 'Determine if system maintenance is performed.', '[]'),
