	(203, 'cmmc-2', 20, '3.7.3', 'Ensure equipment removed for off', 'Ensure equipment removed for off-site maintenance is sanitized of any CUI.', 2, 0, 'Determine if equipment to be removed from organizational spaces for off-site maintenance is sanitized of any CUI.', '[]'),
	(204, 'cmmc-2', 20, '3.7.4', 'Check media containing diagnostic and test programs for mali...', 'Check media containing diagnostic and test programs for malicious code before the media are used in organizational systems', 2, 0, 'Determine if media containing diagnostic and test programs are checked for malicious code before being used in organizational systems that process, store, or transmit CUI.', '[]'),
	(205, 'cmmc-2', 20, '3.7.5', 'Require multifactor authentication to establish nonlocal mai...', 'Require multifactor authentication to establish nonlocal maintenance sessions via external network connections and terminate such connections when nonlocal maintenance is complete. ', 2, 0, 'Determine if:', '[]'),
	(206, 'cmmc-2', 20, '3.7.6', 'Supervise the maintenance activities of maintenance personne...', 'Supervise the maintenance activities of maintenance personnel without required access authorization.', 2, 0, 'Determine if maintenance personnel without required access authorization are supervised during maintenance activities.', '[]'),
	(207, 'cmmc-2', 21, '3.8.1', 'Protect (i.e., physically control and securely store) system...', 'Protect (i.e., physically control and securely store) system media containing CUI, both paper and digital.', 2, 0, 'Determine if:', '[]'),
	(208, 'cmmc-2', 21, '3.8.2', 'Limit access to CUI on system media to authorized users....', 'Limit access to CUI on system media to authorized users.', 2, 0, 'Determine if access to CUI on system media is limited to authorized users.', '[]'),
	(209, 'cmmc-2', 21, '3.8.3', 'Sanitize or destroy system media containing CUI before dispo...', 'Sanitize or destroy system media containing CUI before disposal or release for reuse.', 2, 0, 'Determine if:', '[]'),
	(210, 'cmmc-2', 21, '3.8.4', 'Mark media with necessary CUI markings and distribution limi...', 'Mark media with necessary CUI markings and distribution limitations.', 2, 0, 'Determine if:', '[]'),
	(211, 'cmmc-2', 21, '3.8.5', 'Control access to media containing CUI and maintain accounta...', 'Control access to media containing CUI and maintain accountability for media during transport outside of controlled areas.', 2, 0, 'Determine if:', '[]'),
	(212, 'cmmc-2', 21, '3.8.6', 'Implement cryptographic mechanisms to protect the confidenti...', 'Implement cryptographic mechanisms to protect the confidentiality of CUI stored on digital media during transport unless otherwise protected by alternative physical safeguards.', 2, 0, 'Determine if the confidentiality of CUI stored on digital media is protected during transport using cryptographic mechanisms or alternative physical safeguards.', '[]'),
	(213, 'cmmc-2', 21, '3.8.7', 'Control the use of removable media on system components....', 'Control the use of removable media on system components.', 2, 0, 'Determine if the use of removable media on system components containing CUI is controlled.', '[]'),
	(214, 'cmmc-2', 21, '3.8.8', 'Prohibit the use of portable storage devices when such devic...', 'Prohibit the use of portable storage devices when such devices have no identifiable owner.', 2, 0, 'Determine if the use of portable storage devices is prohibited when such devices have no identifiable owner.', '[]'),
	(215, 'cmmc-2', 21, '3.8.9', 'Protect the confidentiality of backup CUI at storage locatio...', 'Protect the confidentiality of backup CUI at storage locations.', 2, 0, 'Determine if the confidentiality of backup CUI is protected at storage locations.', '[]'),
	(216, 'cmmc-2', 22, '3.9.1', 'Screen individuals prior to authorizing access to organizati...', 'Screen individuals prior to authorizing access to organizational systems containing CUI. ', 2, 0, 'Determine if individuals are screened prior to authorizing access to organizational systems.', '[]'),
