INSERT INTO public.poam_items VALUES
	(2, 3, 'AC-17', 'Remote Access MFA Not Enforced', 'Multi-factor authentication is not currently enforced for all remote access connections to the internal network, including VPN and administrative portals.', 'Chief Information Officer', NULL, '2026-03-30 00:00:00', NULL, 'open', '2026-01-21 22:39:15.581', '2026-01-21 22:39:16.136004', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, false, NULL),
	(3, 3, 'SC-13', 'FIPS 140-2 Encryption Missing', 'The current encryption module used for data-at-rest protection on mobile devices is not FIPS 140-2 validated as required by CMMC Level 2.', 'IT Security Manager', NULL, '2026-04-15 00:00:00', NULL, 'open', '2026-01-21 22:39:15.581', '2026-01-21 22:39:16.136004', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, false, NULL),
	(4, 3, 'AU-2', 'Inadequate Audit Logging on Critical Systems', 'Several legacy application servers are not currently capturing successful/failed login attempts and administrative privilege elevation events.', 'Compliance Officer', NULL, '2026-02-28 00:00:00', NULL, 'open', '2026-01-21 22:39:15.581', '2026-01-21 22:39:16.136004', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, false, NULL),
	(5, 3, 'IA-2', 'Shared Administrative Accounts', 'Generic ''Administrator'' and ''Root'' accounts are still being used for shared system administration tasks instead of uniquely identifiable user accounts.', 'System Administrator', NULL, '2026-03-15 00:00:00', NULL, 'open', '2026-01-21 22:39:15.581', '2026-01-21 22:39:16.136004', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, false, NULL),
	(6, 3, 'PE-3', 'Physical Access Logs Not Maintained', 'Visitor logs for the primary server room are being maintained on paper and at times contain illegible signatures or missing ''Out'' times.', 'Facilities Manager', NULL, '2026-05-01 00:00:00', NULL, 'open', '2026-01-21 22:39:15.581', '2026-01-21 22:39:16.136004', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, false, NULL),
	(7, 4, 'AC-17', 'Remote Access MFA Not Enforced', 'Multi-factor authentication is not currently enforced for all remote access connections to the internal network, including VPN and administrative portals.', 'Chief Information Officer', NULL, '2026-03-30 00:00:00', NULL, 'open', '2026-01-21 23:08:30.02', '2026-01-21 23:08:30.596645', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, false, NULL),
