INSERT INTO public.privacy_assessments VALUES
	(1, 679, 'gdpr', '"{\"test_q\":{\"answer\":\"yes\",\"notes\":\"Verified via script\"}}"', 'in_progress', 15, '2026-01-17 07:11:39.897', '2026-01-17 06:16:44.083266'),
	(2, 6, 'gdpr', '"{\"Q1.1\":{\"answer\":\"Yes\",\"notes\":\"Privacy policy is updated and linked in footer.\"},\"Q1.2\":{\"answer\":\"Partial\",\"notes\":\"Working on cookie consent banner implementation.\"},\"Q2.1\":{\"answer\":\"No\",\"notes\":\"DPIA process needs to be finalized.\"}}"', 'in_progress', 45, '2026-02-14 10:04:58.734447', '2026-02-14 10:04:58.734447'),
	(3, 3, 'BREACH: 43t34t34t3', '"{\"occurredAt\":\"2026-02-27\",\"severity\":\"high\",\"description\":\"b34t34t34t34t34t34t34\",\"loggedAt\":\"2026-02-16T23:57:59.794Z\"}"', 'in_progress', 0, '2026-02-16 23:58:01.328511', '2026-02-16 23:58:01.328511'),
	(8, 731, 'nis2', '"{\"nis2_1.1\":{\"answer\":\"yes\",\"notes\":\"Information Security Policy v2.4 covers NIS2 requirements.\"},\"nis2_1.2\":{\"answer\":\"yes\",\"notes\":\"CISO and Data Owners appointed.\"},\"nis2_2.1\":{\"answer\":\"partial\",\"notes\":\"Risk assessment performed for HQ, but not for branch offices.\"},\"nis2_2.2\":{\"answer\":\"not_started\"},\"nis2_2.3\":{\"answer\":\"not_started\"},\"nis2_3.1\":{\"answer\":\"yes\",\"notes\":\"Incident response plan updated in Jan 2026.\"},\"nis2_3.2\":{\"answer\":\"yes\",\"notes\":\"SIEM deployed and monitored 24/7.\"},\"nis2_3.3\":{\"answer\":\"partial\",\"notes\":\"Internal reporting works, external regulatory reporting needs testing.\"},\"nis2_3.4\":{\"answer\":\"yes\"},\"nis2_3.5\":{\"answer\":\"yes\"},\"nis2_3.6\":{\"answer\":\"yes\"},\"nis2_4.1\":{\"answer\":\"partial\",\"notes\":\"BCP exists, but DRP for cloud systems is in draft.\"},\"nis2_4.2\":{\"answer\":\"yes\",\"notes\":\"Daily backups to encrypted off-site storage.\"},\"nis2_5.1\":{\"answer\":\"not_started\",\"notes\":\"Need to update vendor contracts with security clauses.\"},\"nis2_5.2\":{\"answer\":\"yes\"},\"nis2_6.1\":{\"answer\":\"yes\"},\"nis2_6.2\":{\"answer\":\"partial\",\"notes\":\"SDLC followed for new apps, legacy apps are unmanaged.\"},\"nis2_6.7\":{\"answer\":\"yes\",\"notes\":\"Firewalls and VPNs in place.\"},\"nis2_6.10\":{\"answer\":\"not_started\"},\"nis2_8.1\":{\"answer\":\"yes\",\"notes\":\"Annual security awareness training completed by 95% of staff.\"},\"nis2_9.1\":{\"answer\":\"yes\",\"notes\":\"AES-256 used for data at rest.\"},\"nis2_11.1\":{\"answer\":\"yes\"},\"nis2_11.7\":{\"answer\":\"yes\",\"notes\":\"MFA enforced for all remote access.\"}}"', 'in_progress', 40, '2026-03-10 10:06:04.648', '2026-03-10 10:06:19.93895'),
	(7, 3, 'nis2', '"{\"nis2_1.1\":{\"answer\":\"yes\",\"notes\":\"fdfdfk\"},\"nis2_1.2\":{\"answer\":\"yes\",\"notes\":\"fdbdfbdf\"},\"nis2_2.1\":{\"answer\":\"yes\",\"notes\":\"dsgdfgdfgd\"},\"nis2_2.2\":{\"answer\":\"yes\",\"notes\":\"dfgdfgdd\"},\"nis2_2.3\":{\"answer\":\"yes\",\"notes\":\"bbdfgdfbdfbrergergergregreg\"},\"nis2_3.1\":{\"answer\":\"yes\",\"notes\":\"dfbdfbdfbdfbdfbdfbdfbdfbdfbdfbdfbdfbfdfbdfbdfby\"},\"nis2_3.2\":{\"answer\":\"yes\",\"notes\":\"ergergergerger\"},\"nis2_3.3\":{\"answer\":\"partial\",\"notes\":\"llllll\"},\"nis2_3.4\":{\"answer\":\"partial\",\"notes\":\"\"},\"nis2_3.5\":{\"answer\":\"yes\",\"notes\":\"EMMANUEL\"},\"nis2_3.6\":{\"answer\":\"partial\",\"notes\":\"\"},\"nis2_4.1\":{\"answer\":\"partial\",\"notes\":\"\"},\"nis2_4.2\":{\"answer\":\"yes\",\"notes\":\"\"},\"nis2_4.3\":{\"answer\":\"yes\",\"notes\":\"testuuuuuuuuuuuuuu\"},\"nis2_5.1\":{\"answer\":\"partial\",\"notes\":\"jkjkjkjkjkjkjk\"}}"', 'in_progress', 28, '2026-03-11 22:13:49.84', '2026-03-10 10:06:19.687521');
