INSERT INTO public.questionnaire_questions VALUES
	(1, 1, 'The CSP must respond with “Yes”/ ”No”/ ”NA” next to the corresponding assessment question, and for the portion(s) of the CCM control specification they are responsible and accountable for implementing.', NULL, NULL, '[]', 'pending', '2026-01-19 00:40:51.448858', '2026-01-19 00:40:51.448858', NULL, NULL, '[]', 'internal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, '{}'),
	(2, 1, 'A “Yes” answer indicates that the portion of the control in question is implemented. The CSP indicates the responsible and accountable parties (SSRM control ownership), and optionally elaborates on the implementation “how-to” per relevant party CSP and/or CSC.', NULL, NULL, '[]', 'pending', '2026-01-19 00:40:51.448858', '2026-01-19 00:40:51.448858', NULL, NULL, '[]', 'internal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, '{}'),
	(3, 1, 'A “No” answer indicates that the portion of the control in question is not implemented, while in scope of the assessment. The CSP has to assign the implementation responsibility of the control to the relevant party under column “SSRM control ownership”, and optionally elaborate on the “why” (has not been implemented), and “what” has to be done for its implementation by that party.', NULL, NULL, '[]', 'pending', '2026-01-19 00:40:51.448858', '2026-01-19 00:40:51.448858', NULL, NULL, '[]', 'internal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, '{}'),
	(4, 1, 'A “N/A” answer indicates that the portion of the control in question is out of scope of the assessment. The “SSRM control ownership” column is to be left blank (e.g., greyed out), and optionally the CSP may explain why it is the case (“CSP Implementation Description”).', NULL, NULL, '[]', 'pending', '2026-01-19 00:40:51.448858', '2026-01-19 00:40:51.448858', NULL, NULL, '[]', 'internal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, '{}'),
	(5, 1, 'The CSP control responses shall identify control applicability and ownership for their specific service.', NULL, NULL, '[]', 'pending', '2026-01-19 00:40:51.448858', '2026-01-19 00:40:51.448858', NULL, NULL, '[]', 'internal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, '{}'),
	(6, 1, 'A description (with references) of how the cloud service provider meets (or does not meet) the portion(s) of the SSRM control they are responsible for. If “NA,” explain why.', NULL, NULL, '[]', 'pending', '2026-01-19 00:40:51.448858', '2026-01-19 00:40:51.448858', NULL, NULL, '[]', 'internal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, '{}'),
