INSERT INTO public.samm_practices VALUES
	(1, 'SM', 'Strategy and Metrics', 'Build an efficient and effective plan for realizing your software security objectives within your organization.', 'Governance', 'Create and Promote', 'Develop a security strategy and build stakeholder buy-in', 'Measure and Improve', 'Establish metrics and improve based on data', 'https://owaspsamm.org/model/governance/strategy-and-metrics/', 1, '2026-02-08 14:04:55.833298', '2026-02-08 16:11:29.617704'),
	(2, 'PC', 'Policy and Compliance', 'Understand and meet external legal and regulatory requirements while driving internal security standards.', 'Governance', 'Policy and Standards', 'Establish security and compliance policies', 'Compliance Management', 'Measure compliance and develop evidence', 'https://owaspsamm.org/model/governance/policy-and-compliance/', 2, '2026-02-08 14:04:55.896327', '2026-02-08 16:11:29.675976'),
	(3, 'EG', 'Education and Guidance', 'Equip personnel with the knowledge and resources to build security into their work.', 'Governance', 'Training and Awareness', 'Provide role-specific security training', 'Organization and Culture', 'Build security into the organization and culture', 'https://owaspsamm.org/model/governance/education-and-guidance/', 3, '2026-02-08 14:04:55.950399', '2026-02-08 16:11:29.734012'),
	(5, 'SR', 'Security Requirements', 'Specify security requirements to guide design and development.', 'Design', 'Software Requirements', 'Derive security requirements from business functionality', 'Supplier Security', 'Manage security in the supply chain', 'https://owaspsamm.org/model/design/security-requirements/', 5, '2026-02-08 14:04:56.058343', '2026-02-08 16:11:29.849525'),
	(6, 'SA', 'Secure Architecture', 'Establish architecture to support security throughout the application lifecycle.', 'Design', 'Architecture Design', 'Insert security principles into architecture design', 'Technology Management', 'Manage technology stacks and frameworks for security', 'https://owaspsamm.org/model/design/secure-architecture/', 6, '2026-02-08 14:04:56.111838', '2026-02-08 16:11:29.907509'),
	(7, 'SB', 'Secure Build', 'Build and deploy software using secure processes and tooling.', 'Implementation', 'Build Process', 'Harden the build process', 'Software Dependencies', 'Manage and track software dependencies', 'https://owaspsamm.org/model/implementation/secure-build/', 7, '2026-02-08 14:04:56.165873', '2026-02-08 16:11:29.96548'),
	(8, 'SD', 'Secure Deployment', 'Deploy software into production environments securely.', 'Implementation', 'Deployment Process', 'Establish secure deployment processes', 'Secret Management', 'Handle secrets and credentials securely', 'https://owaspsamm.org/model/implementation/secure-deployment/', 8, '2026-02-08 14:04:56.219872', '2026-02-08 16:11:30.023028'),
	(9, 'DM', 'Defect Management', 'Measure, manage, and learn from security defects.', 'Implementation', 'Defect Tracking', 'Track security findings and remediation', 'Metrics and Feedback', 'Use metrics to improve security over time', 'https://owaspsamm.org/model/implementation/defect-management/', 9, '2026-02-08 14:04:56.273851', '2026-02-08 16:11:30.080481'),
	(10, 'AA', 'Architecture Assessment', 'Review architecture and infrastructure against security requirements.', 'Verification', 'Architecture Validation', 'Validate architecture and design security', 'Architecture Mitigation', 'Mitigate architectural and design flaws', 'https://owaspsamm.org/model/verification/architecture-assessment/', 10, '2026-02-08 14:04:56.327899', '2026-02-08 16:11:30.139496'),
	(12, 'ST', 'Security Testing', 'Test applications for security vulnerabilities.', 'Verification', 'Scalable Baseline', 'Perform consistent security testing', 'Deep Understanding', 'Perform deep security testing', 'https://owaspsamm.org/model/verification/security-testing/', 12, '2026-02-08 14:04:56.436849', '2026-02-08 16:11:30.25557'),
	(13, 'IM', 'Incident Management', 'Detect and respond to security incidents when they occur.', 'Operations', 'Incident Detection', 'Detect security incidents', 'Incident Response', 'Respond to security incidents', 'https://owaspsamm.org/model/operations/incident-management/', 13, '2026-02-08 14:04:56.490334', '2026-02-08 16:11:30.31349'),
	(14, 'EM', 'Environment Management', 'Maintain secure operational environments.', 'Operations', 'Configuration Hardening', 'Harden operational configurations', 'Patching and Updating', 'Maintain patching and updates', 'https://owaspsamm.org/model/operations/environment-management/', 14, '2026-02-08 14:04:56.543887', '2026-02-08 16:11:30.371993'),
	(15, 'OM', 'Operational Management', 'Manage security data and processes in operations.', 'Operations', 'Data Protection', 'Protect sensitive data', 'System Decomissioning', 'Securely decommission systems', 'https://owaspsamm.org/model/operations/operational-management/', 15, '2026-02-08 14:04:56.599344', '2026-02-08 16:11:30.429635'),
	(4, 'TA', 'Threat Assessment', 'Identify and understand threats to the organization and applications.', 'Design', 'Application Risk Profile', 'Identify and catalog application risks', 'Threat Modeling', 'Use threat modeling to understand system-level threats', 'https://owaspsamm.org/model/design/threat-assessment/', 4, '2026-02-08 14:04:56.0044', '2026-02-08 16:11:29.791978'),
	(11, 'RT', 'Requirements-driven Testing', 'Test applications against functional and non-functional security requirements.', 'Verification', 'Control Verification', 'Test security controls', 'Misuse/Abuse Testing', 'Test for common security weaknesses', 'https://owaspsamm.org/model/verification/requirements-driven-testing/', 11, '2026-02-08 14:04:56.381353', '2026-02-08 16:11:30.197993');
