INSERT INTO public.samm_stream_questions VALUES
	(5, 'SM', 'Strategy and Metrics', 'B', 'Measure and Improve', 'Establish metrics and improve based on data', 2, 'Defined', 'Do you use metrics to objectively guide security decisions and measure improvements?', '["Metrics tied to security objectives", "Trend analysis performed", "Metrics used in decision-making", "Regular metric review meetings", "Improvement actions based on metrics", "Metrics reviewed by leadership"]', '["Align metrics with security strategy", "Perform trend analysis", "Use metrics to drive improvements", "Conduct regular metric reviews", "Document decisions based on metrics", "Present metrics to leadership"]', 'Data-driven security program improvement', '["Metrics drive decisions", "Trends documented", "Improvement initiatives launched based on metrics", "Leadership reviews metrics"]', '["Metric trend analysis reports", "Decision documents citing metrics", "Leadership review meeting minutes", "Improvement project documentation"]', 'Governance', 'https://owaspsamm.org/model/governance/strategy-and-metrics/stream-b/', true, '2.0', '2026-02-08 14:04:56.88148', '2026-02-08 16:11:30.723057'),
	(6, 'SM', 'Strategy and Metrics', 'B', 'Measure and Improve', 'Establish metrics and improve based on data', 3, 'Optimized', 'Do you continuously optimize your metrics program and use advanced analytics for insights?', '["Metrics program regularly reviewed and refined", "Advanced analytics (predictive, correlative)", "Automated metric collection and reporting", "Benchmarking against industry standards", "Metrics influence organizational KPIs", "Continuous improvement culture"]', '["Regularly review and optimize metrics", "Implement advanced analytics", "Automate collection and reporting", "Benchmark against industry", "Integrate security metrics into organizational KPIs", "Foster data-driven security culture"]', 'Optimized, data-driven continuous improvement', '["Advanced analytics in use", "Automated reporting", "Security metrics part of organizational KPIs", "Continuous optimization evident"]', '["Advanced metrics dashboards", "Automated reporting systems", "Benchmarking reports", "Organizational KPI documents including security"]', 'Governance', 'https://owaspsamm.org/model/governance/strategy-and-metrics/stream-b/', true, '2.0', '2026-02-08 14:04:56.936398', '2026-02-08 16:11:30.781548'),
	(20, 'EG', 'Education and Guidance', 'A', 'Training and Awareness', 'Provide role-specific security training', 2, 'Defined', 'Do you provide role-specific security training for personnel involved in software development?', '["Specific training for developers (e.g., OWASP Top 10)", "Specific training for testers and architects", "Training includes hands-on exercises", "Feedback collected from participants"]', '["Develop customized training modules for different roles", "Host secure coding workshops", "Provide access to specialized security training platforms", "Update training content annually"]', 'Technical teams have the skills needed to build secure software', '["Role-based training paths", "Skill assessment results"]', '["Training curriculum by role", "Workshop materials", "Hands-on lab logs"]', 'Governance', 'https://owaspsamm.org/model/governance/education-and-guidance/stream-a/', true, '2.0', '2026-02-08 14:55:36.774481', '2026-02-08 16:11:31.253843'),
	(1, 'SM', 'Strategy and Metrics', 'A', 'Create and Promote', 'Develop a security strategy and build stakeholder buy-in', 1, 'Initial', 'Do you understand the enterprise-wide risk appetite for your applications?', '["Interviewed business owners about threats", "Documented worst-case scenarios", "Identified market opportunities from security", "Published baseline risk factors", "Communicated risk factors to development teams"]', '["Interview business owners and stakeholders about threats", "Document industry-specific security drivers", "Identify worst-case scenarios that could impact the organization", "Create baseline and risk factors document", "Publish and communicate to development teams"]', 'Common understanding of organization security posture', '["Risk factors documented and communicated", "Business owners interviewed", "Development teams aware of security priorities"]', '["Risk factor documentation", "Meeting notes from stakeholder interviews", "Communication records to development teams"]', 'Governance', 'https://owaspsamm.org/model/governance/strategy-and-metrics/stream-a/', true, '2.0', '2026-02-08 14:04:56.654358', '2026-02-08 16:11:30.488531'),
	(4, 'SM', 'Strategy and Metrics', 'B', 'Measure and Improve', 'Establish metrics and improve based on data', 1, 'Initial', 'Do you use a consistent set of metrics to measure the effectiveness of the secure development lifecycle?', '["Metrics defined and documented", "At least 3-5 key metrics tracked", "Metrics collected regularly", "Basic reporting in place", "Metrics shared with relevant teams"]', '["Define key security metrics", "Establish metric collection process", "Create basic dashboards or reports", "Share metrics with development and security teams", "Document metric definitions"]', 'Basic visibility into security program performance', '["Metrics documented", "Regular metric collection", "Basic reports generated"]', '["Metrics definition document", "Sample reports or dashboards", "Metric collection procedures"]', 'Governance', 'https://owaspsamm.org/model/governance/strategy-and-metrics/stream-b/', true, '2.0', '2026-02-08 14:04:56.824459', '2026-02-08 16:11:30.665065'),
	(2, 'SM', 'Strategy and Metrics', 'A', 'Create and Promote', 'Develop a security strategy and build stakeholder buy-in', 2, 'Defined', 'Do you have a strategic plan for application security and use it to make decisions?', '["1-3 year security roadmap exists", "Plan aligned with business priorities", "Budget allocated for security initiatives", "Milestones defined and tracked", "Stakeholder buy-in obtained", "Plan published and accessible to relevant teams"]', '["Develop 1-3 year security roadmap", "Align roadmap with business priorities", "Balance financial, process, and cultural changes", "Define frequent milestones for monitoring", "Obtain stakeholder and development team buy-in", "Publish plan to all participants"]', 'Available and agreed upon roadmap of your AppSec program', '["Written strategic plan exists", "Plan regularly reviewed and updated", "Decisions made based on plan", "Budget allocated"]', '["Published security roadmap document", "Budget approval documents", "Stakeholder sign-off records"]', 'Governance', 'https://owaspsamm.org/model/governance/strategy-and-metrics/stream-a/', true, '2.0', '2026-02-08 14:04:56.715932', '2026-02-08 16:11:30.545929'),
	(16, 'PC', 'Policy and Compliance', 'B', 'Compliance Management', 'Measure compliance and develop evidence', 1, 'Initial', 'Do you identify and document the external compliance requirements relevant to your applications?', '["Legal/Regulatory inventory exists", "Context-specific requirements identified", "Responsibility assigned for compliance", "Baseline requirements documented"]', '["Catalog all applicable laws and regulations", "Determine which apps must follow which rules", "Identify key compliance milestones", "Appoint a compliance liaison"]', 'Avoided fines and legal surprises', '["Compliance matrix showing app vs regulation"]', '["Compliance inventory document", "Risk assessment records"]', 'Governance', 'https://owaspsamm.org/model/governance/policy-and-compliance/stream-b/', true, '2.0', '2026-02-08 14:55:36.520027', '2026-02-08 16:11:31.019542'),
	(13, 'PC', 'Policy and Compliance', 'A', 'Policy and Standards', 'Establish security and compliance policies', 1, 'Initial', 'Do you maintain a security policy or a set of technical standards representing the security baseline for all of your applications?', '["Basic security policy exists", "Technical standards documented", "Policy covers authentication and authorization", "Policy shared with development teams"]', '["Draft high-level application security policy", "Define technical standards for common controls", "Communicate policies to all stakeholders", "Establish periodic policy review"]', 'Clear expectations for security across development teams', '["Published policy document", "Teams aware of baseline standards"]', '["Security Policy document", "Technical Standards wiki", "Email records of policy distribution"]', 'Governance', 'https://owaspsamm.org/model/governance/policy-and-compliance/stream-a/', true, '2.0', '2026-02-08 14:55:36.332477', '2026-02-08 16:11:30.839508'),
	(14, 'PC', 'Policy and Compliance', 'A', 'Policy and Standards', 'Establish security and compliance policies', 2, 'Defined', 'Do you maintain a central library of policies, technical standards, and guidance to fulfill security and compliance requirements?', '["Central policy repository exists", "Guidance documents provided for each policy", "Policies mapped to regulatory requirements", "Stakeholders involved in policy creation"]', '["Create a central security knowledge base", "Develop detailed guidance for implementing standards", "Map internal policies to SOC 2, ISO 27001, etc.", "Establish a formal policy approval process"]', 'Standardized implementation of security across the org', '["Library searchability", "Cross-framework mapping documented"]', '["Policy Library portal", "Mapping spreadsheet/tool", "Implementation guides"]', 'Governance', 'https://owaspsamm.org/model/governance/policy-and-compliance/stream-a/', true, '2.0', '2026-02-08 14:55:36.394498', '2026-02-08 16:11:30.89959'),
	(15, 'PC', 'Policy and Compliance', 'A', 'Policy and Standards', 'Establish security and compliance policies', 3, 'Optimized', 'Do you regularly review the security policy and technical standards to ensure compliance and their effectiveness for the organization?', '["Annual policy review cycle", "Modifications based on industry trends", "Incident data influenced policy changes", "Policy effectiveness metrics tracked"]', '["Conduct annual comprehensive policy review", "Update standards based on new architectural patterns", "Incorporate feedback from security incidents", "Review policies against emerging threats"]', 'Policies stay relevant in a changing threat landscape', '["Version history shows regular updates", "Data-driven policy adjustments"]', '["Review logs", "Policy change history", "Effectiveness reports"]', 'Governance', 'https://owaspsamm.org/model/governance/policy-and-compliance/stream-a/', true, '2.0', '2026-02-08 14:55:36.456967', '2026-02-08 16:11:30.957037'),
	(17, 'PC', 'Policy and Compliance', 'B', 'Compliance Management', 'Measure compliance and develop evidence', 2, 'Defined', 'Do you conduct periodic compliance audits and review the results with stakeholders?', '["Scheduled audit calendar", "Evidence collection process exists", "Non-compliance issues tracked", "Executive review of audit findings"]', '["Schedule recurring compliance check-ins", "Collect technical evidence of control operation", "Log and prioritize compliance gaps", "Report compliance status to leadership"]', 'Early detection of compliance failures', '["Audit reports available", "Evidence repository populated"]', '["Audit reports", "Evidence artifacts", "Governance committee minutes"]', 'Governance', 'https://owaspsamm.org/model/governance/policy-and-compliance/stream-b/', true, '2.0', '2026-02-08 14:55:36.581957', '2026-02-08 16:11:31.079002'),
	(18, 'PC', 'Policy and Compliance', 'B', 'Compliance Management', 'Measure compliance and develop evidence', 3, 'Optimized', 'Do you have an automated process to monitor and verify compliance with your security standards and relevant regulations?', '["Real-time compliance monitoring", "Automated alerts for non-compliance", "Drift detection in production", "Compliance-as-Code implementation"]', '["Implement automated policy checks in CI/CD", "Use cloud-native compliance monitoring tools", "Establish automated alerting for policy violations", "Enable self-healing for common misconfigurations"]', 'Reduced cost of compliance and increased assurance', '["Real-time dashboards", "Automation coverage %"]', '["Monitoring dashboard screenshots", "Automated alert logs", "CI/CD pipeline configs"]', 'Governance', 'https://owaspsamm.org/model/governance/policy-and-compliance/stream-b/', true, '2.0', '2026-02-08 14:55:36.644433', '2026-02-08 16:11:31.138307'),
	(23, 'EG', 'Education and Guidance', 'B', 'Organization and Culture', 'Build security into the organization and culture', 2, 'Defined', 'Do you maintain a security community of practice to share knowledge and best practices?', '["Regular forum/meeting for sharing", "Knowledge base of common solutions", "Participation from multiple departments", "Community-driven security standards"]', '["Host internal security conferences or \"brown bags\"", "Create a collaborative Wiki for security patterns", "Establish an internal messaging channel for security", "Involve community in reviewing security standards"]', 'Accelerated learning and consistency across teams', '["Community engagement metrics", "Contribution counts to security KB"]', '["Wiki edit logs", "Presentation slide decks", "Forum/Slack archives"]', 'Governance', 'https://owaspsamm.org/model/governance/education-and-guidance/stream-b/', true, '2.0', '2026-02-08 14:55:36.962003', '2026-02-08 16:11:31.429559'),
	(19, 'EG', 'Education and Guidance', 'A', 'Training and Awareness', 'Provide role-specific security training', 1, 'Initial', 'Do you offer security awareness training to all personnel involved in the software development lifecycle?', '["Training covers basic security concepts", "Participation is tracked", "Training delivered at least annually", "Material is relevant to the organization"]', '["Conduct annual security awareness sessions", "Track attendance and completion", "Publish security newsletters or bulletins", "Incorporate security into employee onboarding"]', 'General awareness of security risks across the company', '["Training logs", "Onboarding checklist includes security"]', '["Training attendance records", "Onboarding documentation", "Security awareness curriculum"]', 'Governance', 'https://owaspsamm.org/model/governance/education-and-guidance/stream-a/', true, '2.0', '2026-02-08 14:55:36.709824', '2026-02-08 16:11:31.195818'),
	(21, 'EG', 'Education and Guidance', 'A', 'Training and Awareness', 'Provide role-specific security training', 3, 'Optimized', 'Do you maintain a security training program with verified effectiveness through testing or certification?', '["Knowledge testing required for completion", "Internal or external certification program", "Training outcomes linked to performance reviews", "Program effectiveness measured via incident reduction"]', '["Implement a \"Security Belt\" or tiered certification program", "Require passing scores on security assessments", "Analyze correlation between training and code quality", "Gamify security training (e.g., Capture the Flag)"]', 'Demonstrable security competence across the organization', '["Certification counts", "Correlation data between training and defects"]', '["Certification records", "Test result reports", "Performance review templates"]', 'Governance', 'https://owaspsamm.org/model/governance/education-and-guidance/stream-a/', true, '2.0', '2026-02-08 14:55:36.836486', '2026-02-08 16:11:31.311795'),
