INSERT INTO public.vendor_assessment_templates VALUES
	(2, 1, 'Standard Security Questionnaire (SIG Lite)', 'Standardized Information Gathering (SIG) Lite questionnaire for vendor risk assessment.', '"{\"sections\":[{\"title\":\"Program Management\",\"description\":\"Organizational security governance and policies.\",\"questions\":[{\"id\":\"PM.1\",\"text\":\"Does the organization have a formally documented information security program?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"PM.2\",\"text\":\"Is there a designated individual responsible for information security?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Data Security\",\"description\":\"Encryption and data protection measures.\",\"questions\":[{\"id\":\"DS.1\",\"text\":\"Is data encrypted at rest?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"DS.2\",\"text\":\"Is data encrypted in transit (TLS 1.2+)?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Access Control\",\"description\":\"Identity management and authentication.\",\"questions\":[{\"id\":\"AC.1\",\"text\":\"Is Multi-Factor Authentication (MFA) enforced for all remote access?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"AC.2\",\"text\":\"Are access rights revoked immediately upon employee termination?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Incident Response\",\"description\":\"Breach detection and reporting.\",\"questions\":[{\"id\":\"IR.1\",\"text\":\"Do you have a documented Incident Response Plan?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"IR.2\",\"text\":\"Are security incidents reported to customers within 72 hours?\",\"type\":\"yes_no\",\"required\":true}]}]}"', 1, '2026-01-18 00:54:06.864458', '2026-01-18 00:54:06.864458'),
	(3, 2, 'Standard Security Questionnaire (SIG Lite)', 'Standardized Information Gathering (SIG) Lite questionnaire for vendor risk assessment.', '"{\"sections\":[{\"title\":\"Program Management\",\"description\":\"Organizational security governance and policies.\",\"questions\":[{\"id\":\"PM.1\",\"text\":\"Does the organization have a formally documented information security program?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"PM.2\",\"text\":\"Is there a designated individual responsible for information security?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Data Security\",\"description\":\"Encryption and data protection measures.\",\"questions\":[{\"id\":\"DS.1\",\"text\":\"Is data encrypted at rest?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"DS.2\",\"text\":\"Is data encrypted in transit (TLS 1.2+)?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Access Control\",\"description\":\"Identity management and authentication.\",\"questions\":[{\"id\":\"AC.1\",\"text\":\"Is Multi-Factor Authentication (MFA) enforced for all remote access?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"AC.2\",\"text\":\"Are access rights revoked immediately upon employee termination?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Incident Response\",\"description\":\"Breach detection and reporting.\",\"questions\":[{\"id\":\"IR.1\",\"text\":\"Do you have a documented Incident Response Plan?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"IR.2\",\"text\":\"Are security incidents reported to customers within 72 hours?\",\"type\":\"yes_no\",\"required\":true}]}]}"', 1, '2026-01-18 00:54:06.977428', '2026-01-18 00:54:06.977428'),
	(1, 3, 'Standard Security Questionnaire (SIG Lite)', 'Updated by debug script at 2026-01-18T00:58:30.999Z', '"{\"sections\":[{\"title\":\"Program Management\",\"description\":\"Organizational security governance and policies.\",\"questions\":[{\"id\":\"PM.1\",\"text\":\"Does the organization have a formally documented information security program?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"PM.2\",\"text\":\"Is there a designated individual responsible for information security?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Data Security\",\"description\":\"Encryption and data protection measures.\",\"questions\":[{\"id\":\"DS.1\",\"text\":\"Is data encrypted at rest?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"DS.2\",\"text\":\"Is data encrypted in transit (TLS 1.2+)?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Access Control\",\"description\":\"Identity management and authentication.\",\"questions\":[{\"id\":\"AC.1\",\"text\":\"Is Multi-Factor Authentication (MFA) enforced for all remote access?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"AC.2\",\"text\":\"Are access rights revoked immediately upon employee termination?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Incident Response\",\"description\":\"Breach detection and reporting.\",\"questions\":[{\"id\":\"IR.1\",\"text\":\"Do you have a documented Incident Response Plan?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"IR.2\",\"text\":\"Are security incidents reported to customers within 72 hours?\",\"type\":\"yes_no\",\"required\":true}]}]}"', 1, '2026-01-18 00:58:31', '2026-01-18 00:54:06.742413'),
	(4, 1, 'Standard Security Questionnaire (VSAQ Core)', 'Based on Google''s Vendor Security Assessment Questionnaire framework.', '"{\"sections\":[{\"title\":\"Web Application Security\",\"description\":\"Questions regarding the security of the web application.\",\"questions\":[{\"id\":\"vsaq_webapp_1\",\"text\":\"Does the application enforce strong password policies (length, complexity, rotation)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_webapp_2\",\"text\":\"Is Multi-Factor Authentication (MFA) supported and enforced for administrative access?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_webapp_3\",\"text\":\"How does the application protect against common vulnerabilities like SQL Injection and XSS?\",\"type\":\"text\",\"required\":true},{\"id\":\"vsaq_webapp_4\",\"text\":\"Are all sensitive data transmissions encrypted using TLS 1.2 or higher?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Infrastructure Security\",\"description\":\"Questions regarding the underlying infrastructure.\",\"questions\":[{\"id\":\"vsaq_infra_1\",\"text\":\"Is the production environment logically separated from development and staging environments?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_infra_2\",\"text\":\"Are security patches applied to operating systems and libraries within 30 days of release?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_infra_3\",\"text\":\"Describe your backup and disaster recovery strategy.\",\"type\":\"text\",\"required\":true}]},{\"title\":\"Physical & Data Center Security\",\"description\":\"Questions regarding physical access controls.\",\"questions\":[{\"id\":\"vsaq_phys_1\",\"text\":\"Is physical access to data centers restricted to authorized personnel only?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_phys_2\",\"text\":\"Are physical access logs retained for at least 90 days?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Privacy & Compliance\",\"questions\":[{\"id\":\"vsaq_priv_1\",\"text\":\"Do you comply with GDPR and/or CCPA requirements where applicable?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_priv_2\",\"text\":\"Have you undergone a third-party security audit (e.g., SOC 2, ISO 27001) in the last 12 months?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_priv_3\",\"text\":\"Upload your latest SOC 2 Type II or ISO 27001 certificate.\",\"type\":\"file_upload\",\"required\":false}]}]}"', 1, '2026-01-18 01:10:57.416', '2026-01-18 01:10:57.416'),
	(5, 2, 'Standard Security Questionnaire (VSAQ Core)', 'Based on Google''s Vendor Security Assessment Questionnaire framework.', '"{\"sections\":[{\"title\":\"Web Application Security\",\"description\":\"Questions regarding the security of the web application.\",\"questions\":[{\"id\":\"vsaq_webapp_1\",\"text\":\"Does the application enforce strong password policies (length, complexity, rotation)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_webapp_2\",\"text\":\"Is Multi-Factor Authentication (MFA) supported and enforced for administrative access?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_webapp_3\",\"text\":\"How does the application protect against common vulnerabilities like SQL Injection and XSS?\",\"type\":\"text\",\"required\":true},{\"id\":\"vsaq_webapp_4\",\"text\":\"Are all sensitive data transmissions encrypted using TLS 1.2 or higher?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Infrastructure Security\",\"description\":\"Questions regarding the underlying infrastructure.\",\"questions\":[{\"id\":\"vsaq_infra_1\",\"text\":\"Is the production environment logically separated from development and staging environments?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_infra_2\",\"text\":\"Are security patches applied to operating systems and libraries within 30 days of release?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_infra_3\",\"text\":\"Describe your backup and disaster recovery strategy.\",\"type\":\"text\",\"required\":true}]},{\"title\":\"Physical & Data Center Security\",\"description\":\"Questions regarding physical access controls.\",\"questions\":[{\"id\":\"vsaq_phys_1\",\"text\":\"Is physical access to data centers restricted to authorized personnel only?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_phys_2\",\"text\":\"Are physical access logs retained for at least 90 days?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Privacy & Compliance\",\"questions\":[{\"id\":\"vsaq_priv_1\",\"text\":\"Do you comply with GDPR and/or CCPA requirements where applicable?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_priv_2\",\"text\":\"Have you undergone a third-party security audit (e.g., SOC 2, ISO 27001) in the last 12 months?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_priv_3\",\"text\":\"Upload your latest SOC 2 Type II or ISO 27001 certificate.\",\"type\":\"file_upload\",\"required\":false}]}]}"', 1, '2026-01-18 01:10:58.186', '2026-01-18 01:10:58.186'),
	(6, 3, 'Standard Security Questionnaire (VSAQ Core)', 'Based on Google''s Vendor Security Assessment Questionnaire framework.', '"{\"sections\":[{\"title\":\"Web Application Security\",\"description\":\"Questions regarding the security of the web application.\",\"questions\":[{\"id\":\"vsaq_webapp_1\",\"text\":\"Does the application enforce strong password policies (length, complexity, rotation)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_webapp_2\",\"text\":\"Is Multi-Factor Authentication (MFA) supported and enforced for administrative access?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_webapp_3\",\"text\":\"How does the application protect against common vulnerabilities like SQL Injection and XSS?\",\"type\":\"text\",\"required\":true},{\"id\":\"vsaq_webapp_4\",\"text\":\"Are all sensitive data transmissions encrypted using TLS 1.2 or higher?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Infrastructure Security\",\"description\":\"Questions regarding the underlying infrastructure.\",\"questions\":[{\"id\":\"vsaq_infra_1\",\"text\":\"Is the production environment logically separated from development and staging environments?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_infra_2\",\"text\":\"Are security patches applied to operating systems and libraries within 30 days of release?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_infra_3\",\"text\":\"Describe your backup and disaster recovery strategy.\",\"type\":\"text\",\"required\":true}]},{\"title\":\"Physical & Data Center Security\",\"description\":\"Questions regarding physical access controls.\",\"questions\":[{\"id\":\"vsaq_phys_1\",\"text\":\"Is physical access to data centers restricted to authorized personnel only?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_phys_2\",\"text\":\"Are physical access logs retained for at least 90 days?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Privacy & Compliance\",\"questions\":[{\"id\":\"vsaq_priv_1\",\"text\":\"Do you comply with GDPR and/or CCPA requirements where applicable?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_priv_2\",\"text\":\"Have you undergone a third-party security audit (e.g., SOC 2, ISO 27001) in the last 12 months?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"vsaq_priv_3\",\"text\":\"Upload your latest SOC 2 Type II or ISO 27001 certificate.\",\"type\":\"file_upload\",\"required\":false}]}]}"', 1, '2026-01-18 01:10:58.307', '2026-01-18 01:10:58.307'),
	(7, 1, 'Full VSAQ Standard Assessment', 'Comprehensive vendor security assessment based on Google VSAQ (50+ controls).', '"{\"sections\":[{\"title\":\"Web Application Security\",\"description\":\"Assess the security controls of the web application.\",\"questions\":[{\"id\":\"webapp_1\",\"text\":\"Does the application enforce strong password complexity (min 12 chars, mixed case, special chars)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_2\",\"text\":\"Is Multi-Factor Authentication (MFA) required for all administrative access?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_3\",\"text\":\"Is Multi-Factor Authentication (MFA) available for end users?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_4\",\"text\":\"Are session tokens invalidated upon logout?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_5\",\"text\":\"Does the application automatically log out users after a period of inactivity (e.g., 15 mins)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_6\",\"text\":\"Are all sensitive data fields (e.g., PII, passwords) masked in logs?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_7\",\"text\":\"Is input validation performed on both client and server sides?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_8\",\"text\":\"Does the application use parameterized queries to prevent SQL injection?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_9\",\"text\":\"Is Content Security Policy (CSP) implemented to mitigate XSS?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_10\",\"text\":\"Are security headers (X-Frame-Options, HSTS, X-Content-Type-Options) configured?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_11\",\"text\":\"Is TLS 1.2 or higher enforced for all data in transit?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_12\",\"text\":\"Are weak ciphers and protocols (e.g., SSLv3, TLS 1.0) disabled?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_13\",\"text\":\"Do you perform regular static application security testing (SAST)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_14\",\"text\":\"Do you perform regular dynamic application security testing (DAST)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_15\",\"text\":\"Has the application undergone a penetration test in the last 12 months?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Infrastructure & Network Security\",\"description\":\"Controls regarding the underlying infrastructure and network.\",\"questions\":[{\"id\":\"infra_1\",\"text\":\"Is the production environment logically separated from dev/stage?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_2\",\"text\":\"Are production servers patched within 30 days of critical security releases?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_3\",\"text\":\"Do you use a Web Application Firewall (WAF)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_4\",\"text\":\"Is DDoS protection implemented?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_5\",\"text\":\"Are default accounts and passwords removed or disabled on all systems?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_6\",\"text\":\"Is access to management interfaces (SSH, RDP) restricted to VPN or specific IPs?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_7\",\"text\":\"Do you maintain an up-to-date asset inventory of all servers and devices?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_8\",\"text\":\"Is Intrusion Detection/Prevention System (IDS/IPS) deployed?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_9\",\"text\":\"Are server logs centrally collected and monitored?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_10\",\"text\":\"Is minimal privilege access enforced for all system accounts?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Data Protection & Privacy\",\"description\":\"Policies and controls for protecting sensitive data.\",\"questions\":[{\"id\":\"data_1\",\"text\":\"Is data at rest encrypted using strong algorithms (e.g., AES-256)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_2\",\"text\":\"Are encryption keys managed separately from the data they protect?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_3\",\"text\":\"Do you have a documented data retention and disposal policy?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_4\",\"text\":\"Do you comply with GDPR requirements for data processing?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_5\",\"text\":\"Do you comply with CCPA requirements?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_6\",\"text\":\"Is customer data logically isolated from other customers (multi-tenancy controls)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_7\",\"text\":\"Are backups encrypted?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_8\",\"text\":\"Are backups tested for restorability at least annually?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_9\",\"text\":\"Do you have a formal incident response plan?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_10\",\"text\":\"Are employees trained on data privacy and security awareness annually?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Physical & Operational Security\",\"description\":\"Controls for physical access and organizational operations.\",\"questions\":[{\"id\":\"phys_1\",\"text\":\"Is physical access to data centers restricted to authorized personnel?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_2\",\"text\":\"Are visitors required to sign in and be escorted at all times?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_3\",\"text\":\"Are physical access logs retained for at least 90 days?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_4\",\"text\":\"Are employee background checks performed prior to employment?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_5\",\"text\":\"Is access revoked immediately upon employee termination?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_6\",\"text\":\"Do you have a Business Continuity Plan (BCP)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_7\",\"text\":\"Do you have a Disaster Recovery (DR) plan?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_8\",\"text\":\"Are BCP/DR plans tested annually?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Supply Chain & Third-Party Risk\",\"description\":\"Management of vendors and third-party dependencies.\",\"questions\":[{\"id\":\"supply_1\",\"text\":\"Do you have a formal vendor management program?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"supply_2\",\"text\":\"Are third-party vendors assessed for security risks before onboarding?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"supply_3\",\"text\":\"Do contracts include security and privacy clauses?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"supply_4\",\"text\":\"Is open source software analyzed for vulnerabilities (SCA)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"supply_5\",\"text\":\"Do you monitor critical vendors for security incidents?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Compliance Certifications\",\"description\":\"External validation of the security program.\",\"questions\":[{\"id\":\"cert_1\",\"text\":\"Are you SOC 2 Type II compliant?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"cert_2\",\"text\":\"Are you ISO 27001 certified?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"cert_3\",\"text\":\"Please upload your latest SOC 2 report (if applicable).\",\"type\":\"file_upload\",\"required\":false},{\"id\":\"cert_4\",\"text\":\"Please upload your latest ISO 27001 certificate (if applicable).\",\"type\":\"file_upload\",\"required\":false},{\"id\":\"cert_5\",\"text\":\"Please provide a link to your public Trust Center (if available).\",\"type\":\"text\",\"required\":false}]}]}"', 1, '2026-01-18 01:14:07.931', '2026-01-18 01:14:07.931'),
	(8, 2, 'Full VSAQ Standard Assessment', 'Comprehensive vendor security assessment based on Google VSAQ (50+ controls).', '"{\"sections\":[{\"title\":\"Web Application Security\",\"description\":\"Assess the security controls of the web application.\",\"questions\":[{\"id\":\"webapp_1\",\"text\":\"Does the application enforce strong password complexity (min 12 chars, mixed case, special chars)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_2\",\"text\":\"Is Multi-Factor Authentication (MFA) required for all administrative access?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_3\",\"text\":\"Is Multi-Factor Authentication (MFA) available for end users?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_4\",\"text\":\"Are session tokens invalidated upon logout?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_5\",\"text\":\"Does the application automatically log out users after a period of inactivity (e.g., 15 mins)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_6\",\"text\":\"Are all sensitive data fields (e.g., PII, passwords) masked in logs?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_7\",\"text\":\"Is input validation performed on both client and server sides?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_8\",\"text\":\"Does the application use parameterized queries to prevent SQL injection?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_9\",\"text\":\"Is Content Security Policy (CSP) implemented to mitigate XSS?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_10\",\"text\":\"Are security headers (X-Frame-Options, HSTS, X-Content-Type-Options) configured?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_11\",\"text\":\"Is TLS 1.2 or higher enforced for all data in transit?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_12\",\"text\":\"Are weak ciphers and protocols (e.g., SSLv3, TLS 1.0) disabled?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_13\",\"text\":\"Do you perform regular static application security testing (SAST)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_14\",\"text\":\"Do you perform regular dynamic application security testing (DAST)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"webapp_15\",\"text\":\"Has the application undergone a penetration test in the last 12 months?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Infrastructure & Network Security\",\"description\":\"Controls regarding the underlying infrastructure and network.\",\"questions\":[{\"id\":\"infra_1\",\"text\":\"Is the production environment logically separated from dev/stage?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_2\",\"text\":\"Are production servers patched within 30 days of critical security releases?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_3\",\"text\":\"Do you use a Web Application Firewall (WAF)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_4\",\"text\":\"Is DDoS protection implemented?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_5\",\"text\":\"Are default accounts and passwords removed or disabled on all systems?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_6\",\"text\":\"Is access to management interfaces (SSH, RDP) restricted to VPN or specific IPs?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_7\",\"text\":\"Do you maintain an up-to-date asset inventory of all servers and devices?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_8\",\"text\":\"Is Intrusion Detection/Prevention System (IDS/IPS) deployed?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_9\",\"text\":\"Are server logs centrally collected and monitored?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"infra_10\",\"text\":\"Is minimal privilege access enforced for all system accounts?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Data Protection & Privacy\",\"description\":\"Policies and controls for protecting sensitive data.\",\"questions\":[{\"id\":\"data_1\",\"text\":\"Is data at rest encrypted using strong algorithms (e.g., AES-256)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_2\",\"text\":\"Are encryption keys managed separately from the data they protect?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_3\",\"text\":\"Do you have a documented data retention and disposal policy?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_4\",\"text\":\"Do you comply with GDPR requirements for data processing?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_5\",\"text\":\"Do you comply with CCPA requirements?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_6\",\"text\":\"Is customer data logically isolated from other customers (multi-tenancy controls)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_7\",\"text\":\"Are backups encrypted?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_8\",\"text\":\"Are backups tested for restorability at least annually?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_9\",\"text\":\"Do you have a formal incident response plan?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"data_10\",\"text\":\"Are employees trained on data privacy and security awareness annually?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Physical & Operational Security\",\"description\":\"Controls for physical access and organizational operations.\",\"questions\":[{\"id\":\"phys_1\",\"text\":\"Is physical access to data centers restricted to authorized personnel?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_2\",\"text\":\"Are visitors required to sign in and be escorted at all times?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_3\",\"text\":\"Are physical access logs retained for at least 90 days?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_4\",\"text\":\"Are employee background checks performed prior to employment?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_5\",\"text\":\"Is access revoked immediately upon employee termination?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_6\",\"text\":\"Do you have a Business Continuity Plan (BCP)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_7\",\"text\":\"Do you have a Disaster Recovery (DR) plan?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"phys_8\",\"text\":\"Are BCP/DR plans tested annually?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Supply Chain & Third-Party Risk\",\"description\":\"Management of vendors and third-party dependencies.\",\"questions\":[{\"id\":\"supply_1\",\"text\":\"Do you have a formal vendor management program?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"supply_2\",\"text\":\"Are third-party vendors assessed for security risks before onboarding?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"supply_3\",\"text\":\"Do contracts include security and privacy clauses?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"supply_4\",\"text\":\"Is open source software analyzed for vulnerabilities (SCA)?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"supply_5\",\"text\":\"Do you monitor critical vendors for security incidents?\",\"type\":\"yes_no\",\"required\":true}]},{\"title\":\"Compliance Certifications\",\"description\":\"External validation of the security program.\",\"questions\":[{\"id\":\"cert_1\",\"text\":\"Are you SOC 2 Type II compliant?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"cert_2\",\"text\":\"Are you ISO 27001 certified?\",\"type\":\"yes_no\",\"required\":true},{\"id\":\"cert_3\",\"text\":\"Please upload your latest SOC 2 report (if applicable).\",\"type\":\"file_upload\",\"required\":false},{\"id\":\"cert_4\",\"text\":\"Please upload your latest ISO 27001 certificate (if applicable).\",\"type\":\"file_upload\",\"required\":false},{\"id\":\"cert_5\",\"text\":\"Please provide a link to your public Trust Center (if available).\",\"type\":\"text\",\"required\":false}]}]}"', 1, '2026-01-18 01:14:08.691', '2026-01-18 01:14:08.691'),
