	(679, '3.8.5', '3.8.5 - Control access to media containing CUI and maintain accounta...', 'Control access to media containing CUI and maintain accountability for media during transport outside of controlled areas.', 'NIST 800-171', NULL, NULL, NULL, 'active', 1, 'Media Protection', NULL, '2026-01-06 19:50:14.296871', '2026-01-06 19:50:14.296871', NULL, 'Determine if:', NULL, NULL, NULL, NULL, NULL),
