	(1079, 9, 105, 'SAMM-SECURITY-TESTING', 'Security Testing', 'Security Practice: Security Testing under Verification', NULL, '"[\"SAMM\",\"Verification\"]"', '2026-02-05 00:26:58.856177', '2026-02-05 00:26:58.856177'),
	(1080, 9, 105, 'SAMM-REQUIREMENTS-DRIVEN-TESTING', 'Requirements-driven Testing', 'Security Practice: Requirements-driven Testing under Verification', NULL, '"[\"SAMM\",\"Verification\"]"', '2026-02-05 00:26:59.077111', '2026-02-05 00:26:59.077111'),
