	(28, 'CVE-2001-0590', '5', 'AV:N/AC:L/Au:N/C:P/I:N/A:N', '"[]"', 'Apache Software Foundation Tomcat Servlet prior to 3.2.2 allows a remote attacker to read the source code to arbitrary ''jsp'' files via a malformed URL request which does not end with an HTTP protocol specification (i.e. HTTP/1.0).', '2001-08-02 02:00:00', '2025-04-02 23:03:51.193', '"[\"cpe:2.3:a:apache:tomcat:*:*:*:*:*:*:*:*\"]"', '"[{\"url\":\"http://archives.neohapsis.com/archives/bugtraq/2001-04/0031.html\",\"source\":\"cve@mitre.org\",\"tags\":[\"Exploit\",\"Vendor Advisory\"]},{\"url\":\"http://www.osvdb.org/5580\",\"source\":\"cve@mitre.org\"},{\"url\":\"http://www1.itrc.hp.com/service/cki/docDisplay.do?docId=HPSBTL0112-004\",\"source\":\"cve@mitre.org\"},{\"url\":\"https://exchange.xforce.ibmcloud.com/vulnerabilities/6971\",\"source\":\"cve@mitre.org\"},{\"url\":\"http://archives.neohapsis.com/archives/bugtraq/2001-04/0031.html\",\"source\":\"af854a3a-2127-422b-91ae-364da2661108\",\"tags\":[\"Exploit\",\"Vendor Advisory\"]},{\"url\":\"http://www.osvdb.org/5580\",\"source\":\"af854a3a-2127-422b-91ae-364da2661108\"},{\"url\":\"http://www1.itrc.hp.com/service/cki/docDisplay.do?docId=HPSBTL0112-004\",\"source\":\"af854a3a-2127-422b-91ae-364da2661108\"},{\"url\":\"https://exchange.xforce.ibmcloud.com/vulnerabilities/6971\",\"source\":\"af854a3a-2127-422b-91ae-364da2661108\"}]"', '"{\"id\":\"CVE-2001-0590\",\"sourceIdentifier\":\"cve@mitre.org\",\"published\":\"2001-08-02T04:00:00.000\",\"lastModified\":\"2025-04-03T01:03:51.193\",\"vulnStatus\":\"Deferred\",\"cveTags\":[],\"descriptions\":[{\"lang\":\"en\",\"value\":\"Apache Software Foundation Tomcat Servlet prior to 3.2.2 allows a remote attacker to read the source code to arbitrary ''jsp'' files via a malformed URL request which does not end with an HTTP protocol specification (i.e. HTTP/1.0).\"}],\"metrics\":{\"cvssMetricV2\":[{\"source\":\"nvd@nist.gov\",\"type\":\"Primary\",\"cvssData\":{\"version\":\"2.0\",\"vectorString\":\"AV:N/AC:L/Au: